object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  val N = in.next().toInt
  val A = new Array[Long](N+1)
  val B = new Array[Long](N+1)
  for (i <- 1 to N) {
    val a, b = in.next().toInt
    A(i) = a
    B(i) = b
  }


  // check smallest
  val hoge = new Array[(Long, Int)](2*N)
  for (i <- 1 to N) {
    val ind = 2*(i-1)
    hoge(ind) = (A(i), -i)
    hoge(ind+1) = (B(i), i)
  }

  val ord = hoge.sorted
  var ans = ord.take(N).map(_._1).sum
  var flag1 = false
  val memo = new Array[Boolean](N+1)
  for (i <- 0 until N) {
    val (_, _ind) = ord(i)
    val ind = _ind.abs

    if(memo(ind))
      flag1 = true
    else
      memo(ind) = true
  }

  if(A.sum == ans || B.sum == ans || flag1)
    ()
  else {
    val dpA = new Array[Boolean](N+1)
    val dpB = new Array[Boolean](N+1)

    for (i <- 0 until N) {
      val (_, ind) = ord(i)

      if(ind < 0)
        dpA(ind.abs) = true
      else
        dpB(ind.abs) = true
    }

    var diff = 0L
    val (maxNum, maxi) = ord(N-1)
    breakable {
      for ((nowNum, nowi) <- ord.slice(N, 2*N)) {
        if(nowi.abs != maxi.abs) {
          if(nowi < 0 && !dpA(nowi.abs)) {
            diff = nowNum - maxNum
            break
          }
          else if(nowi > 0 && !dpB(nowi.abs)) {
            diff = nowNum - maxNum
            break
          }
        }
      }
    }

    var diff2 = Long.MaxValue
    val (maxNum2, maxi2) = ord(N-2)
    breakable {
      for ((nowNum, nowi) <- ord.slice(N, 2*N)) {
        if(nowi.abs != maxi2.abs) {
          if(nowi < 0 && !dpA(nowi.abs)) {
            diff2 = nowNum - maxNum2
            break
          }
          else if(nowi > 0 && !dpB(nowi.abs)) {
            diff2 = nowNum - maxNum2
            break
          }
        }
      }
    }
    diff = diff min diff2

    ans = A.sum min B.sum min (ans+diff)
  }


  println(ans)
}


