#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

struct Item {
  int index;
  char type;
  int64 value;
};

constexpr int DEBUG = 0;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<Item> items;
  for (int i = 0; i < n; i++) {
    int64 a, b;
    cin >> a >> b;
    items.push_back({i, 'A', a});
    items.push_back({i, 'B', b});
  }

  sort(items.begin(), items.end(), [](const Item& item1, const Item& item2) {
    return item1.value < item2.value;
  });

  int64 total = 0;
  vector<int> a_used(n);
  vector<int> b_used(n);
  for (int i = 0; i < n; i++) {
    if (DEBUG) {
      cout << items[i].index << " " << items[i].type << " "
           << items[i].value << endl;
    }
    if (items[i].type == 'A') {
      a_used[items[i].index] = 1;
    } else if (items[i].type == 'B') {
      b_used[items[i].index] = 1;
    } else {
      exit(1);
    }
    total += items[i].value;
  }

  int ox_count = 0;
  int xo_count = 0;
  for (int i = 0; i < n; i++) {
    if (a_used[i] && !b_used[i]) {
      ox_count++;
    }
    if (!a_used[i] && b_used[i]) {
      xo_count++;
    }
  }
  if (DEBUG) {
    cout << "ox_count: " << ox_count << " xo_count: " << xo_count << endl;
  }

  if (ox_count + xo_count < n || ox_count == n || xo_count == n) {
    cout << total << endl;
    return 0;
  }

  if (items[n - 1].index != items[n].index) {
    cout << total - items[n - 1].value + items[n].value << endl;
    return 0;
  } else {
    int64 min_addition = min(
        -items[n - 1].value + items[n + 1].value,
        -items[n - 2].value + items[n].value);
    cout << total + min_addition << endl;
    return 0;
  }
}

