namespace TYC
{
	typedef long long ll;
	typedef pair<int, int> pii;

	const int N = 1e5 + 5;

	int n, A[N], B[N], Mark[N], P[N];
	pii C[N << 2];

	inline int read()
	{
		int x = 0, f = 0, ch = getchar();
		while (!isdigit(ch))
			f |= (ch == '-'), ch = getchar();
		while (isdigit(ch))
			x = x * 10 + ch - '0', ch = getchar();
		return f ? -x : x;
	}

	ll solve()
	{
		int flag = 0, cnt = 0;
		ll ans = 0;
		memset(Mark, 0, sizeof(int[n + 1]));
		for (int i = 1; i <= n; i++)
		{
			ans += C[P[i]].first;
			int p = C[P[i]].second;
			if (p > n)
				p -= n, cnt++;
			if (++Mark[p] == 2)
				flag = 1;
		}
		return (flag || !cnt || cnt == n) ? ans : LLONG_MAX;
	}

	void work()
	{
		n = read();
		for (int i = 1; i <= n; i++)
		{
			C[i] = pii(read(), i);
			C[i + n] = pii(read(), i + n);
		}
		sort(C + 1, C + 1 + (n << 1));
		for (int i = 1; i <= n; i++)
			P[i] = i;	
		ll ans = solve();
		P[n] = n + 1;
		ans = min(ans, solve());
		P[n] = n + 2;
		ans = min(ans, solve());
		P[n - 1] = n, P[n] = n + 1;
		ans = min(ans, solve());
		printf("%lld\n", ans);
	}
}

