#include <bits/stdc++.h>

using namespace std;
int par[1000000];
int rank[100000];

//nの要素で初期化
void init(int n){
  for(int i = 0; i < n; i++){
    par[i] = i;
    rank[i] = 0;
  }
}

//木の根を求める
int find(int x){
  if(par[x] == x){
    return x;
  } else {
    return par[x] = find(par[x]);
  }
}

//xとyの属する集合を併合
void unite(int x, int y){
  x = find(x);
  y = find(y);
  if(x == y) return ;

  if(rank[x] < rank[y]){
    par[x] = y;
  } else {
    par[y] = x;
    if(rank[x] == rank[y]) rank[x]++;
  }
}

// xとyが同じ属性に属するか否か
bool same(int x, int y){
  return find(x) == find(y);
}
int main(){
  long long n;
  cin >> n;
  vector<pair<long long,int> > to(n);
  vector<pair<long long,int> > from(n);

  for(int i = 0; i < n; i++){
    cin >> to[i].first >> from[i].first;
    to[i].second = i;
    from[i].second = i;
  }
  sort(to.begin(),to.end());
  sort(from.begin(),from.end());

  long long ans = 0;
  deque<long long> mismatch;
  int toCnt = 0, fromCnt = 0;
  init(n);
  while(toCnt != n || fromCnt != n){
    if(mismatch.empty() == false){
      ans += min(to[toCnt].first , mismatch.front());
      mismatch.pop_front();
      toCnt ++;
      continue;
    }
    if(toCnt != n-1 || unite(to[toCnt].second, from[n-fromCnt-1].second)){
      mismatch.push_back(from[n-1-fromCnt].first);
      fromCnt++;
      ans += min(to[toCnt].first, from[n-fromCnt-1].first);
      toCnt++;
      fromCnt++;
    }else{
      ans += min(to[toCnt].first , from[n-fromCnt-1].first);
      toCnt ++;
      fromCnt ++;
    }
    //cout << ans << " toCnt " << toCnt << " fromCnt " << fromCnt << endl;

  }
  cout << ans << endl;
  return 0;
}

