void _main()
{
    ll n; llin(n);
    S V<t2> ablist; llinl2(ablist, n);

    priority_queue_incr<t2> qa;
    priority_queue_incr<t2> qb;
    rep (idx, n) {
        ll a = get<0>(ablist[idx]);
        ll b = get<1>(ablist[idx]);
        qa.push(t2(a, idx));
        qb.push(t2(b, idx));
    }

    ll ans = 0LL;
    ll cnt = 0LL;
    ll cnt_a = 0LL;
    ll cnt_b = 0LL;
    V<t2> popped;
    S bool checked[100005];
    memset(checked, 0, sizeof(checked));

    rep (xx, n) {
        t2 aa = qa.top();
        t2 bb = qb.top();

        ll a = get<0>(aa);
        ll aidx = get<1>(aa);
        ll b = get<0>(bb);
        ll bidx = get<1>(bb);

        ll val = 1e18;
        ll idx = 1e18;

        if (a < b) {
            val = a;
            idx = aidx;
            cnt_a++;
            qa.pop();
        }
        else {
            val = b;
            idx = bidx;
            cnt_b++;
            qb.pop();
        }

        popped.pb(t2(val, idx));
        if (!checked[idx]) cnt++;
        checked[idx] = true;
        ans += val;
    }

    if (cnt_a && cnt_b && cnt == n) {
        sort_reverse(popped);
        ll incr_min = 1e18;

        while (!qa.empty()) {
            auto aa = qa.top(); qa.pop();
            ll a = get<0>(aa);
            ll aidx = get<1>(aa);
            rep (i, n) {
                ll val = get<0>(popped[i]);
                ll pidx = get<1>(popped[i]);
                if (aidx == pidx) continue;
                incr_min = min(incr_min, a - val);
                break;
            }
        }

        while (!qb.empty()) {
            auto bb = qb.top(); qb.pop();
            ll b = get<0>(bb);
            ll bidx = get<1>(bb);
            rep (i, n) {
                ll val = get<0>(popped[i]);
                ll pidx = get<1>(popped[i]);
                if (bidx == pidx) continue;
                incr_min = min(incr_min, b - val);
                break;
            }
        }

        ans += incr_min;
    }

    cout << ans << endl;
}

