struct UnionFind{
    vector<int> parent, rank;
    UnionFind(int n) : parent(n, -1), rank(n, 0) { }
    int find(int x){
        if(parent[x] == -1) return x;
        else return (parent[x] = find(parent[x]));
    }
    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(rank[x] < rank[y])
            parent[x] = y;
        else
            parent[y] = x;
        if(rank[x] == rank[y]) rank[x]++;
        return true;
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
};


ll solve(){
    ll res = 0;
    int N; cin >> N;
    vector<ll> A(N),B(N);
    for(int i = 0; i < N;i++) cin >> A[i] >> B[i];

    priority_queue<pll,vector<pll>,greater<pll>> pq1;
    priority_queue<pll> pq2;

    UnionFind UF(2*N);
    for(int i = 0; i < N;i++) UF.unite(i, i+N);
    for(int i = 0;i < N;i++){
        pq1.push({A[i],i});
        pq2.push({B[i],i});
    }
    while(pq1.size()!=1){
        auto q1 = pq1.top(); pq1.pop();
        auto q2 = pq2.top(); pq2.pop();


        ll Bid = q1.second + N;
        ll Aid = q2.second;
        vector<pll> in;
        while(UF.same(q2.second,Bid)){
            in.push_back(q2);
            q2 = pq2.top(); pq2.pop();
        }

        UF.unite(q2.second,Bid);
        res += min(q1.first,q2.first);
        for(const pll& q:in) pq2.push(q);
    }
    res += min(pq1.top().first,pq2.top().first);

    ll T = res;
    res = 0;
    UF = UnionFind(2*N);
    for(int i = 0; i < N;i++) UF.unite(i, i+N);
    for(int i = 0;i < N;i++){
        pq1.push({A[i],i});
        pq2.push({B[i],i});
    }
    while(pq1.size()!=1){
        auto q1 = pq1.top(); pq1.pop();
        auto q2 = pq2.top(); pq2.pop();


        ll Bid = q1.second + N;
        ll Aid = q2.second;
        vector<pll> in;
        while(UF.same(Aid,q1.second+N)){
            in.push_back(q1);
            q1 = pq1.top(); pq1.pop();
        }

        UF.unite(Aid,q1.second+N);
        res += min(q1.first,q2.first);
        for(const pll& q:in) pq1.push(q);
    }
    res += min(pq1.top().first,pq2.top().first);

    res = min(res,T);
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    cout << solve() << endl;
    return 0;
}

#include "bits/stdc++.h"
using namespace std;
int main(){
  int n;
  cin >> n;
  struct state {
    int a, b, i;
  };
  struct cmp {
    bool operator () (const state a, const state b) const {
      if(a.a == b.a) return a.b < b.b;
      return a.a < b.a;
    }
  };
  multiset<state, cmp> ab, ba;
  for(int e = 0; e < n; e++){
    int x, y;
    cin >> x >> y;
    ab.insert({x, y, e});
    ba.insert({y, x, e});
  }
  long long ans = 0;
  while(ab.size() > 2){
    vector<state> sab, sba;
    for(int e = 0; e < 2 && !ab.empty(); e++){
      auto it = *ab.begin(); ab.erase(ab.begin());
      sab.push_back(it);
    }
    for(int e = 0; e < 2 && !ab.empty(); e++){
      auto it = *(--ab.end()); ab.erase(--ab.end());
      sab.push_back(it);
    }
    for(int e = 0; e < 2 && !ba.empty(); e++){
      auto it = *ba.begin(); ba.erase(ba.begin());
      sba.push_back(it);
    }
    for(int e = 0; e < 2 && !ba.empty(); e++){
      auto it = *(--ba.end()); ba.erase(--ba.end());
      sba.push_back(it);
    }
    // cerr << "extracted" << endl;
    int best = 1<<30;
    int rbest = 0;
    for(int e = 0; e < sab.size(); e++){
      for(int f = 0; f < sba.size(); f++){
        if(sab[e].i != sba[f].i){
          if(min(sab[e].a, sba[f].a) <= best){
            best = min(sab[e].a, sba[f].a);
            rbest = max(rbest, max(sab[e].a, sba[f].a) );
          } 
          if(min(sab[e].b, sba[f].b) <= best){
            best = min(sab[e].b, sba[f].b);
            rbest = max(rbest, max(sab[e].b, sba[f].b) );
          } 
        }
      }
    }
    // cerr << best << " " << rbest << endl;
    ans += best;
    bool over = false;
    vector<state> rem, add;
    for(int e = 0; e < sab.size() && !over; e++){
      for(int f = 0; f < sba.size() && !over; f++){
        if(sab[e].i != sba[f].i){
          if(best == min(sab[e].a, sba[f].a) && rbest == max(sab[e].a, sba[f].a)){
            // cerr << sab[e].i << " " << sba[f].i << endl;
            rem.push_back(sab[e]);
            rem.push_back({sba[f].b, sba[f].a, sba[f].i});
            add.push_back({sba[f].b, sab[e].b, sab[e].i});
            over = true;
          }
          else if (best == min(sab[e].b, sba[f].b) && rbest == max(sab[e].b, sba[f].b)){
            // cerr << sab[e].i << " " << sba[f].i << endl;
            rem.push_back(sab[e]);
            rem.push_back({sba[f].b, sba[f].a, sba[f].i});
            add.push_back({sab[e].a, sba[f].a, sab[e].i});
            over = true;
          }
        }
      }
    }
    // cerr << "todos " << rem.size() << " " << add.size() << endl;
    for(auto it : sab) ab.insert(it);
    for(auto it : sba) ba.insert(it);
    // cerr << "stable" << endl;
    for(auto it : rem){
      auto it0 = ab.find(it); ab.erase(it0);
      auto it1 = ba.find({it.b, it.a, it.i}); ba.erase(it1); 
    }
    // cerr << "rem" << endl;
    for(auto it : add){
      ab.insert({it.a, it.b, it.i});
      ba.insert({it.b, it.a, it.i});
    }
  }
  vector<state> fu;
  for(auto it : ab) fu.push_back(it);
  ans += min(fu[0].a, fu[1].b);
  ans += min(fu[1].a, fu[0].b);
  cout << ans << endl;
  return 0;
}

