const int N = 200010;
const int mod = 1000000007; // 10^9+7
int n;
int a[N];
int b[N];
int type[N];
int cnt[4];

ll solve() {
    ll suma = 0;
    ll sumb = 0;
    forn (i, n) {
        suma += a[i];
        sumb += b[i];
    }
    ll ans = min(suma, sumb);

    vector<pair<int, pii>> arr;
    forn (i, n) {
        arr.emplace_back(MP(a[i], MP(i, 1)));
        arr.emplace_back(MP(b[i], MP(i, 2)));
    }
    sort(all(arr));
    clr(type, 0);
    clr(cnt, 0);
    ll val = 0;
    forn (i, n) {
        auto v = arr[i];
        val += v.first;
        type[v.second.first] |= v.second.second;
    }
    forn (i, n) {
        cnt[ type[i] ]++;
    }
    if (cnt[0] != 0) {
        return val;
    }
    forn (i, n) {
        auto v = arr[n + i];
        for (int j = n - 1; j >= 0; --j) {
            if (arr[j].second.first != v.second.first) {
                ans = min(ans, val + v.first - arr[j].first);
                break;
            }
        }
    }
    return ans;
}

