class UnionFind {
public:
  VI par, rank;
  UnionFind(int n) {
    par = VI(n); iota(par.begin(), par.end(), 0);
    rank = VI(n, 0);
  }
  int root(int x) {
    if (par[x] == x) {
      return x;
    } else {
      return par[x] = root(par[x]);
    }
  }
  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) { return; }
    if (rank[x] < rank[y]) {
      par[x] = y;
    } else {
      par[y] = x;
      if (rank[x] == rank[y]) { rank[x]++; }
    }
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
};

signed main() {
  int N; cin >> N;
  VII A(N), B(N);
  REP (i, N) {
    cin >> A[i].first >> B[i].first;
    A[i].second = i; B[i].second = i;
  }
  sort(A.begin(), A.end());
  sort(B.begin(), B.end());
  UnionFind uf(N);
  vector<bool> used(N);
  int ans = 0;
  int k = N - 1;
  REP (i, N) {
    while (used[k]) {
      k--;
    }
    int j = k;
    if (i < N - 1) {
      while (uf.same(A[i].second, B[j].second)) {
        j--;
      }
      used[j] = true;
      uf.unite(A[i].second, B[j].second);
    }
    ans += min(A[i].first, B[j].first);
  }
  cout << ans << endl;
}

