void solve() {
  int n; cin >> n;
  pqasc<tuple<int, int, int>> q;
  rep(i, n) {
    int a, b; cin >> a >> b;
    q.emplace(a, i, 0);
    q.emplace(b, i, 1);
  }
  set<int> in;
  vector<int> co(2);
  long long ans = 0;
  int la;
  rep(i, n) {
    int x, y, z;
    tie(x, y, z) = q.top(), q.pop();
    la = x;
    ans += x;
    in.insert(y);
    co[z]++;
  }
  if (in.size() == n && (co[0] == 1 || co[1] == 1)) {
    ans -= la;
    int x, y, z;
    tie(x, y, z) = q.top(), q.pop();
    ans += x;
  }
  cout << ans << '\n';
}

