vi V;
multiset<ll> lset,rset;

int main(){
	cin>>N;
	for (ll i=1;i<=N;++i)cin>>A[i].f>>A[i].s;
	for (ll i=1;i<=N;++i){
		L+=A[i].f;
		R+=A[i].s;
	}
	ans = min(L,R);
	ll T = 0;
	for (int i=1;i<=N;++i){lset.insert(A[i].f);T += A[i].f;}
	for (int i=1;i<=N;++i){lset.insert(A[i].s);T += A[i].s;}

	for (ll i=1;i<=N;++i){
		if (i>1){
			lset.insert(A[i-1].f);
			lset.insert(A[i-1].s);
			T += A[i-1].f;
			T += A[i-1].s;
		}
		if (lset.find(A[i].f) == lset.end()){
			rset.erase(rset.find(A[i].f));
		}else{
			lset.erase(lset.find(A[i].f));
			T -= A[i].f;
		}
		if (lset.find(A[i].s) == lset.end()){
			rset.erase(rset.find(A[i].s));
		}else{
			lset.erase(lset.find(A[i].s));
			T -= A[i].s;
		}
		while (SZ(lset) > N-2){
			T -= *(--lset.end());
			rset.insert(*(--lset.end()));
			lset.erase(--lset.end());
		}
		while (SZ(lset) < N-2){
			T += *(rset.begin());
			lset.insert(*(rset.begin()));
			rset.erase(rset.begin());
		}
		ans = min(ans,T+A[i].f+A[i].s);
		assert(SZ(lset) == N-2);
		// for (auto i : lset)cout<<i<<' ';cout<<'\n';
		// cout<<T<<'\n';
	}
	cout<<ans;
}

