LL inv(LL x, LL m) { return x > 1 ? inv(m % x, m) * (m - m / x) % m : x; }
LL powmod(LL a, LL k, LL m) { LL res = 1; for (a %= m; k; k >>= 1, a = a * a % m) if (k & 1)res = res * a % m; return res; }


int main() {
    int n;
    scanf("%d", &n);
    vector<int> A(n + 1), B(n + 1);
    FI(i, 1, n) scanf("%d%d", &A[i], &B[i]);
    auto cmpa = [&](int i, int j) { return A[i] != A[j] ? A[i] < A[j] : i < j; };
    auto cmpb = [&](int i, int j) { return B[i] != B[j] ? B[i] < B[j] : i < j; };
    set<int, decltype(cmpa)> X(cmpa);
    set<int, decltype(cmpb)> Y(cmpb);
    FI(i, 1, n) X.insert(i), Y.insert(i);
    LL ans = 0;
    while (!X.empty()) {
        int i = *X.begin(), j = *Y.begin();
        LL x = A[i], y = B[j];
        if (X.size() == 1) {
            ans += min(x, y);
            break;
        }
        if (x <= y) {
            ans += x;
            auto p = Y.rbegin();
            if (*p == i) advance(p, 1);
            j = *p;
            X.erase(i);
            Y.erase(j);
            A[i] = A[j];
            X.erase(j);
            X.insert(i);
        } else {
            ans += y;
            auto p = X.rbegin();
            if (*p == j) advance(p, 1);
            i = *p;
            Y.erase(j);
            X.erase(i);
            B[j] = B[i];
            Y.erase(i);
            Y.insert(j);
        }
    }
    cout << ans << endl;
    return 0;
}

