#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int n = 1e5 + 10;
int N;
deque<pair<ll, ll>> A, B;
int cmp[n];

int find(int cur){
  if(cmp[cur] != cur){
    cmp[cur] = find(cmp[cur]);
  }
  return cmp[cur];
}

void comb(int a, int b){
  cmp[find(a)] = find(b);
}

void printCmp(){
  for(int i=0; i<N; i++){
    cout << find(i) << " ";
  }
  cout << endl;
}

int main(){
  cin >> N;
  A.resize(N);
  B.resize(N);
  for(int i=0; i<N; i++){
    cin >> A[i].first >> B[i].first;
    A[i].second = B[i].second = i;
    cmp[i] = i;
  }
  sort(A.begin(), A.end());
  sort(B.begin(), B.end());

  ll res = 0;
  for(int i=0; i<N-1; i++){
    if(A[0].first < B[0].first){
      for(int j=B.size()-1; j>=0; j--){
        if(find(A[0].second) != find(B[j].second)){
          comb(A[0].second, B[j].second);
          res += min(A[0].first, B[j].first);
          B[j] = B[B.size()-1];
          B.pop_back();
          A.pop_front();
          break;
        }
      }
    }
    else{
      for(int j=A.size()-1; j>=0; j--){
        if(find(B[0].second) != find(A[j].second)){
          comb(B[0].second, A[j].second);
          res += min(B[0].first, A[j].first);
          A[j] = A[A.size()-1];
          A.pop_back();
          B.pop_front();
          break;
        }
      }
    }
    /*
    cout << res << endl;
    printCmp();
    */
  }
  res += min(A[0].first, B[0].first);
  cout << res << endl;

  return 0;
}

