#include<bits/stdc++.h>
#define inf 0x3f3f3f3f
using namespace std;
typedef long long ll;
const int N=1e5+5;
int n,a[N],b[N];
struct node
{
    int mxa,mxb,mn;
    node(int mxa=0,int mxb=0,int mn=0):mxa(mxa),mxb(mxb),mn(mn){}
    node operator+(const node&o)const
    {
        return node(max(mxa,o.mxa),max(mxb,o.mxb),min(mn,o.mn));
    }
}t[N<<2];
void build(int l,int r,int k)
{
    if(l==r)
    {
        t[k].mxa=a[l];
        t[k].mxb=b[l];
        t[k].mn=min(a[l],b[l]);
        return;
    }
    int m=l+r>>1;
    build(l,m,k<<1);build(m+1,r,k<<1|1);
    t[k]=t[k<<1]+t[k<<1|1];
}
int qmn(int l,int r,int k)
{
    if(l==r) return l;
    int m=l+r>>1;
    if(t[k<<1].mn<=t[k<<1|1].mn) return qmn(l,m,k<<1);
    return qmn(m+1,r,k<<1|1);
}
int qmxa(int l,int r,int k)
{
    if(l==r) return l;
    int m=l+r>>1;
    if(t[k<<1].mxa>=t[k<<1|1].mxa) return qmxa(l,m,k<<1);
    return qmxa(m+1,r,k<<1|1);
}
int qmxb(int l,int r,int k)
{
    if(l==r) return l;
    int m=l+r>>1;
    if(t[k<<1].mxb>=t[k<<1|1].mxb) return qmxb(l,m,k<<1);
    return qmxb(m+1,r,k<<1|1);
}
void del(int l,int r,int k,int x)
{
    if(l==r){t[k].mxa=t[k].mxb=-inf;t[k].mn=inf;return;}
    int m=l+r>>1;
    if(x<=m) del(l,m,k<<1,x);
    else del(m+1,r,k<<1|1,x);
    t[k]=t[k<<1]+t[k<<1|1];
}
void fix(int l,int r,int k,int x)
{
    if(l==r)
    {
        t[k].mxa=a[l];
        t[k].mxb=b[l];
        t[k].mn=min(a[l],b[l]);
        return;
    }
    int m=l+r>>1;
    if(x<=m) fix(l,m,k<<1,x);
    else fix(m+1,r,k<<1|1,x);
    t[k]=t[k<<1]+t[k<<1|1];
}
int main()
{
    scanf("%d",&n);
    for(int i=1;i<=n;i++) scanf("%d%d",&a[i],&b[i]);
    build(1,n,1);
    ll ans=0;
    for(int i=1;i<n;i++)
    {
        int pos=qmn(1,n,1);
        del(1,n,1,pos);
        if(a[pos]<b[pos])
        {
            ans+=a[pos];
            int s=qmxb(1,n,1);
            b[s]=b[pos];
            fix(1,n,1,s);
        }
        else
        {
            ans+=b[pos];
            int s=qmxa(1,n,1);
            a[s]=a[pos];
            fix(1,n,1,s);
        }
    }
    int pos=qmn(1,n,1);
    ans+=min(a[pos],b[pos]);
    printf("%lld\n",ans);
}

