void solve(long long N, std::vector<long long> A, std::vector<long long> B){
    int a = 0, b = 0;
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> Q;
    priority_queue<pair<int,int>> R;

    int s = 0;
    for(int i = 0; i < N; ++i) {
        a += A[i];
        b += B[i];
        s += min(A[i],B[i]);
        Q.push(make_pair(max(A[i], B[i]), i));
        R.push(make_pair(min(A[i], B[i]), i));
    }
    int res = min(a, b);
    vector<bool> f(N);

    s += Q.top().first;
    f[Q.top().second] = true;
    Q.pop();
    s -= R.top().first;
    f[R.top().second] = true;
    R.pop();
    for(int i = 1; i <= N / 2; ++i) {
        res = min(res, s);

        while (!Q.empty()) {
            if (f[Q.top().second]) {
                Q.pop();
                continue;
            }
            s += Q.top().first;
            f[Q.top().second] = true;
            Q.pop();
            break;
        }
        while (!R.empty()) {
            if (f[R.top().second]) {
                R.pop();
                continue;
            }
            s -= R.top().first;
            f[R.top().second] = true;
            R.pop();
            break;
        }
    }

    cout << res << endl;
}

