template<class T> inline bool chmin(T &a,T b){
    if (a>b){a=b; return true;}
    return false;
}
template<class T> inline bool chmax(T &a,T b){
    if (a<b){a=b; return true;}
    return false;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    vector<Pll> A(N),B(N);
    rep(i,N){
        ll a,b; cin >> a >> b;
        A[i]={a,i},B[i]={b,i};
    }
    sort(all(A)),sort(all(B)),reverse(all(B));
    vector<int> mini(N,0);
    rep(i,N) if (A[i].first<B[i].first) mini[i]=1;
    rep(i,N){
        if (A[i].second!=B[i].second) continue;
        if (i<N-1&&mini[i]==mini[i+1]) swap(B[i],B[i+1]);
        else if (i>0&&mini[i-1]==mini[i]) swap(B[i-1],B[i]);
    }
    if (A[0].second==B[0].second){
        ll cnt=IINF,m,a=A[0].first,b=B[0].first;
        rep2(i,1,N){
            ll c=A[i].first,d=B[i].first;
            ll e=(min(a,d)+min(b,c))-(min(a,b)+min(c,d));
            if (chmin(cnt,e)) m=i;
        }
        swap(B[0],B[m]);
    }
    if (A[N-1].second==B[N-1].second){
        ll cnt=IINF,m,a=A[N-1].first,b=B[N-1].first;
        rep(i,N-1){
            ll c=A[i].first,d=B[i].first;
            ll e=(min(a,d)+min(b,c))-(min(a,b)+min(c,d));
            if (chmin(cnt,e)) m=i;
        }
        swap(B[m],B[N-1]);
    }
    ll ans=0;
    rep(i,N) ans+=min(A[i].first,B[i].first);
    cout << ans << endl;
}

