    long i;
    for(i=0; i<n; i++) {
        scanf("%ld%ld", &a[i], &b[i]);
        zz[2*i]   = make_pair( a[i], 2*i );
        zz[2*i+1] = make_pair( b[i], 2*i+1);
    }
    sort( zz.begin(), zz.end() );

    vector<long>  id_save(n*2);
    for(i=0; i<2*n; i++) {
        id_save[zz[i].second] = i;
    }

    vector<ll> szz(2*n+1);
    szz[0]=0;
    for(i=0; i<n+2; i++) {
        szz[i+1] = szz[i] + zz[i].first;
    }

    // Select n items simply
    vector<long> cnt(n); 
    long cnt2[2]={0, 0};
    for(i=0; i<n; i++) {
        cnt[zz[i].second /2] ++;
        cnt2[zz[i].second %2] ++;
    }

    if(cnt2[0]==0 || cnt2[1]==0) {
        printf("%lld\n", szz[n]); return 0;
    }

    for(i=0; i<n; i++) {
        if(cnt[i]==0) {
            printf("%lld\n", szz[n]); return 0;
        }
    }

    // Select n items, avoiding 1 vertex
    ll ans = LINF;
    for(i=0; i<n; i++) {
        long id0 = id_save[2*i];
        long id1 = id_save[2*i+1];

        if(id0<n && id1>=n) {
            if(id1>n) {
                ans = MIN(ans, szz[n]-zz[id0].first+zz[n].first);
            }
            else {
                ans = MIN(ans, szz[n]-zz[id0].first+zz[n+1].first);
            }
        }
        else if(id0>=n && id1<n) {
            if(id0>n) {
                ans = MIN(ans, szz[n]-zz[id1].first+zz[n].first);
            }
            else {
                ans = MIN(ans, szz[n]-zz[id1].first+zz[n+1].first);
            }
        }
        else {
            printf("internal error\n");
        }
    }
    printf("%lld\n", ans);

    return 0;
}

