struct Data {
  ll v, is_b, idx;
};
bool operator<(const Data& d1, const Data& d2) {
  return d1.v < d2.v;
}

ll solve() {
  ll n; cin >> n;
  vector<ll> a(n), b(n);
  rep(i, n) cin >> a[i] >> b[i];
  vector<Data> v;
  rep(i, n) {
    v.pb({a[i], false, i});
    v.pb({b[i], true, i});
  }
  sort(all(v));
  ll sum = 0;
  rep(i, n) {
    sum += v[i].v;
  }
  set<bool> s1;
  set<ll> s2;
  rep(i, n) {
    s1.insert(v[i].is_b);
    s2.insert(v[i].idx);
  }
  if (s1.size() == 1) return sum;
  if (s2.size() != n) return sum;
  ll res = linf;
  rep(i, n, 2*n) {
    if (v[i].idx == v[n-1].idx) {
      chmin(res, sum - v[n-2].v + v[i].v);
    }
    else {
      chmin(res, sum - v[n-1].v + v[i].v);
    }
  }
  return res;
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout << solve() << endl;
}

