    ll cur = 0;
    fori (i, n) {
        h1.insert(a[i]);
        cur += a[i];
        h2.insert(a[i + n]);
    }

    auto erase = [&] (int x) -> void {
        if (h2.count(x)) {
            h2.erase(h2.find(x));
        } else {
            assert(h1.count(x));
            cur -= x;
            h1.erase(h1.find(x));
        }
    };


    auto norm = [&] () -> void {
        while (SZ(h2) > n) {
            auto it = h2.begin();
            h1.insert(*it);
            cur += *it;
            h2.erase(it);
        }
        while (SZ(h2) < n) {
            assert(h1.size());
            auto it = prev(h1.end());
            h2.insert(*it);
            cur -= *it;
            h1.erase(it);
        }
        while (SZ(h1) && SZ(h2) && *h1.rbegin() > *h2.begin()) {
            int f = *h1.rbegin();
            int s = *h2.begin();
            h1.insert(s);
            h1.erase(h1.find(f));
            cur += s - f;
            h2.insert(f);
            h2.erase(h2.find(s));
        }
    };
