		if(a[orda[i]].a>a[ordb[i]].b)posb=min(i,posb);
		ans+=min(a[orda[i]].a,a[ordb[i]].b);
	}
	if(posa==0||posb==n+1){
		ans+=0;
	}
	else{
		for(int i=1;i<=n;++i){
			rka[orda[i]]=i;
			rkb[ordb[i]]=i;
		}
		bool fl=0;
		for(int i=1;i<=n;++i){
			if(!((rka[i]<=posa&&rkb[i]<=posa)||(rka[i]>=posb&&rkb[i]>=posb))){
				fl=1;
			}
		}
		if(!fl){
			int up=0;
			if(a[ordb[posa]].b<a[orda[posa+1]].a)up=ordb[posa];
			else up=orda[posa+1];
			int down=0;
			if(a[orda[posa]].a>a[ordb[posa+1]].b)down=orda[posa];
			else down=ordb[posa+1];
			if(up!=down){
				ans+=min(a[ordb[posa]].b,a[orda[posa+1]].a)-max(a[orda[posa]].a,a[ordb[posa+1]].b);
			}

			else{
				if(a[ordb[posa]].b<a[orda[posa+1]].a)up=posa;
				else up=posa+1;
				int down=0;
				if(a[orda[posa]].a>a[ordb[posa+1]].b)down=posa;
				else down=posa+1;
				LL res1=1e9+1,res2=0;
				for(int i=1;i<=n;++i){
					if(i!=up)res1=min(res1,max(a[orda[i]].a,a[ordb[i]].b));
					if(i!=down)res2=max(res2,min(a[orda[i]].a,a[ordb[i]].b));
				}
				res1=res1-max(a[orda[posa]].a,a[ordb[posa+1]].b);
				res2=min(a[ordb[posa]].b,a[orda[posa+1]].a)-res2;
				ans+=min(res1,res2);
			}
		}
	}
	printf("%lld\n",ans);
	close();
	return 0;
}

