long long sumFirst(const vector<pair<long long, long long>>& vp){
    long long res = 0;
    for(auto& p : vp) res += p.first;
    return res;
}

int main(){
    int n;
    while(cin >> n){
        vector<pair<long long, long long>> in(n);
        vector<pair<long long, long long>> out(n);
        for(int i=0;i<n;i++){
            cin >> in[i].first; in[i].second = i;
            cin >> out[i].first; out[i].second = i;
        }
        sort(in.begin(), in.end());
        sort(out.begin(), out.end());
        long long res = min(sumFirst(in), sumFirst(out));
        vector<int> hold(n, 0);
        int holdNum = 0;
        auto push = [&](int idx){
            hold[idx]++;
            if(hold[idx] == 1) ++holdNum;
        };
        auto pop = [&](int idx){
            hold[idx]--;
            if(hold[idx] == 0) --holdNum;
        };
        long long sumIn = 0;
        long long sumOut = 0;
        for(int i=0;i<n;i++){
            sumOut += out[i].first;
            push(out[i].second);
        }
        for(int i=0;i<n-1;i++){
            sumOut -= out[n-1-i].first;
            pop(out[n-1-i].second);
            sumIn += in[i].first;
            push(in[i].second);
            if(holdNum < n){
                res = min(res, sumIn + sumOut);
            } else {
                res = min(res, sumIn + sumOut + min(in[i+1].first - in[i].first, out[n-1-i].first - out[n-2-i].first));
            }
        }
        cout << res << endl;
    }
}

