const int MAXN = 1e6 + 10;
int nums[2][MAXN];
int tot;
int solve(set<pii> & a, set<pii> & b, int numa[], int numb[]) {
    auto itema = *a.begin();
    a.erase(a.begin());
    auto itb = b.end();
    itb--;
    if (itb->second == itema.second) itb--;
    auto itemb = *itb;
    b.erase(itb);
    auto ita = a.lower_bound({numa[itemb.second], itemb.second});
    numa[tot] = ita->first;
    a.erase(ita);
    itb = b.lower_bound({numb[itema.second], itema.second});
    numb[tot] = itb->first;
    b.erase(itb);
    a.emplace(numa[tot], tot);
    b.emplace(numb[tot], tot);
    tot++;
    return itema.first;
}





