const ll INF = 1e18;

ll brut() {
    ll ans = INF;
    vi p(n);
    iota(all(p), 0);
    do {
        ll cur = 0;
        forn(it, n) {
            int i = p[it];
            int j = p[(it + 1) % n];
            cur += min(a[i], b[j]);
        }
        remin(ans, cur);
    } while (next_permutation(all(p)));
    return ans;
}

ll solve() {
    vii vals;
    forn(i, n) {
        vals.pb(mp(a[i], 2 * i));
        vals.pb(mp(b[i], 2 * i + 1));
    }
    sort(all(vals));

    vvi type(n, vi(2, -1));
    const auto get_type = [&](int i, int name) -> int {
        int& t = type.at(i).at(name);
        if (t != -1) {
            return t;
        }
        if (name == 0) {
            int A = lower_bound(all(vals), mp(a[i], 2 * i)) - vals.begin();
            return (t = A >= n);
        } else if (name == 1) {
            int B = lower_bound(all(vals), mp(b[i], 2 * i + 1)) - vals.begin();
            return (t = B >= n);
        } else {
            assert(0);
        }
    };

    vector<vvi> who(2, vvi(2));
    forn(i, n) {
        int A = get_type(i, 0);
        int B = get_type(i, 1);
        who[A][B].pb(i);
    }

    ll pref = 0;
    forn(A, 2) forn(B, 2) {
        for (int i : who[A][B]) {
//            debug(A, B, i);
            if (A == 0) {
                pref += a[i];
            }
            if (B == 0) {
                pref += b[i];
            }
        }
    }

    vi is;
    forn(A, 2) forn(B, 2) {
        auto w = who[A][B];

        if (A == 0 && B == 0) {
            sort(all(w), [&](int i, int j) { return b[i] < b[j]; });
            if (!w.empty()) {
                is.pb(w.at(0));
            }
        } else if (A + B == 1) {
            sort(all(w), [&](int i, int j) { return a[i] < a[j]; });
            if (!w.empty()) {
                is.pb(w.at(0));
                is.pb(w.back());
                w.pop_back();
                reverse(all(w));
                if (!w.empty())
                w.pop_back();
            }

            sort(all(w), [&](int i, int j) { return b[i] < b[j]; });
            if (!w.empty()) {
                is.pb(w.at(0));
                is.pb(w.back());
            }
        } else {
            sort(all(w), [&](int i, int j) { return a[i] < a[j]; });
            if (!w.empty()) {
                is.pb(w.at(0));
            }
        }
    }

    sort(all(is));
    is.resize(unique(all(is)) - is.begin());

    ll ans = INF;
    do {
        ll cur = 0;
        forn(it, sz(is)) {
            int i = is[it];
            int j = is[(it + 1) % sz(is)];

            int A = get_type(i, 0);
            int B = get_type(j, 1);

            if (A + B == 1) {
                continue;
            }

            if (A == 0 && B == 0) {
                cur -= a[i];
                cur -= b[j];
            }
            cur += min(a[i], b[j]);
        }
        remin(ans, cur);
    } while (next_permutation(all(is)));

//    debug(is);
//    debug(pref, ans);

    return pref + ans;
}

