#define tll tuple<ll,ll,ll>
#define mkt make_tuple

ll N,A[101010],B[101010];

ll i,j,k;

ll ABmin[101010];
priority_queue<tll> gr;
priority_queue<tll,vector<tll>,greater<tll>> lo;
bool ck[101010];
ll ans=0;

int main(){
    scanf("%lld",&N);
    fornum(i,0,N){
        scanf("%lld%lld",&A[i],&B[i]);
        if(A[i]<B[i]){
            ABmin[i]=A[i];
        }else{
            ABmin[i]=B[i];
        }
        lo.push(mkt(A[i]+B[i]-ABmin[i],A[i]+B[i],i));
        gr.push(mkt(ABmin[i],A[i]+B[i],i));
    }
    ll rslt=0;
    fornum(i,0,N)
        ans+=A[i];
    fornum(i,0,N)
        rslt+=B[i];
    if(rslt<ans)ans=rslt;

    rslt=0;
    fornum(i,0,N)
        rslt+=ABmin[i];

    while(true){
        auto L=lo.top();lo.pop();
        ll ln=get<2>(L);
        if(ck[ln])
            break;
        ck[ln]=true;
        auto H=gr.top();gr.pop();
        ll hn=get<2>(H);
        if(ck[hn])
            break;
        ck[hn]=true;

        rslt-=ABmin[ln]+ABmin[hn];
        rslt+=get<1>(L);
        //printf("%lld %lld %lld\n",ln,hn,rslt);
        if(rslt<ans)ans=rslt;
    }
    printf("%lld\n",ans);

    return 0;
}

