LL N;
LL A[100000], B[100000];
bool usedA[100000], usedB[100000];
LL sub() {
	vector<PP> v;
	REP(i, 0, N) {
		v.push_back(PP(A[i], i));
		v.push_back(PP(B[i], i + N));
	}
	sort(v.begin(), v.end());

	REP(i, 0, N) {
		int idx = v[i].second;
		if (idx < N) {
			usedA[idx] = true;
		} else {
			usedB[idx - N] = true;
		}
	}


	bool ok = false;
	int cntA = 0;
	int cntB = 0;
	REP(i, 0, N) {
		if (usedA[i] == usedB[i]) ok = true;
		if (usedA[i] && !usedB[i]) ++cntA;
		if (!usedA[i] && usedB[i]) ++cntB;
	}

	if (cntA != 1 && cntB != 1) ok = true;

	LL sum = 0;
	REP(i, 0, N) {
		sum += v[i].first;
	}
	if (ok) return sum;

	if (cntB == 1) {
		REP(i, 0, N) {
			swap(A[i], B[i]);
			swap(usedA[i], usedB[i]);
		}
	}
	LL mxB = 0;
	REP(i, 0, N) {
		if (!usedB[i]) continue;
		mxB = max(mxB, B[i]);
	}

	LL mnA = INFLL;
	REP(i, 0, N) {
		if (usedA[i]) {
			mnA = min(mnA, B[i]);
			continue;
		}
		mnA = min(mnA, A[i]);
	}
	return sum - mxB + mnA;
}

int main() {
	cin >> N;
	REP(i, 0, N) {
		cin >> A[i] >> B[i];
	}
	cout << sub() << endl;

	return 0;
}

