	int num = N - (lower_bound(X, X+N*2, border) - X);  
	for(int i = 0; i < N; i++){
		if(A[i] < border) MA[i] = true; 
		else if(A[i] == border && num > 0){
			MA[i] = true; num--; 
		}
		if(B[i] < border) MB[i] = true; 
		else if(B[i] == border && num > 0){
			MB[i] = true; num--; 
		}
	}
