	int SS = 0; int SL = 0; int LS = 0; int LL = 0; 
	for(int i = 0; i < N; i++) ans += X[i]; 
	for(int i = 0; i < N; i++){
		if(MA[i] && MB[i]) SS++; 
		else if(MA[i] && !MB[i]) SL++; 
		else if(!MA[i] && MB[i]) LS++; 
		else if(!MA[i] && !MB[i]) LL++;
	}
