typedef long long ll;

ll sum(const vector<long long> &A) {
	ll res = 0;
	for(auto a: A) {
		res += a;
	}
	return res;
}

void solve(long long N, vector<long long> A, vector<long long> B){
	ll res = min(sum(A), sum(B));

	vector<pair<ll, ll>> C;
	vector<bool> used(2 * N);
	for(int i = 0; i < N; ++i) {
		C.push_back(make_pair(A[i], i));
		C.push_back(make_pair(B[i], i + N));
	}
	sort(C.begin(), C.end());

	ll sum = 0;
	for(int i = 0; i < N; ++i) {
		sum += C[i].first;
		used[C[i].second] = true;
	}
	for(int i = 0; i < N; ++i) {
		if(used[i] && used[i + N]) {
			cout << min(res, sum) << endl;
			return;
		}
	}

	for(int i = 0; i < N; ++i) {
		if (C[N].second == i || C[N].second == i + N) {
			res = min(res, sum - min(A[i], B[i]) + C[N + 1].first);
		} else {
			res = min(res, sum - min(A[i], B[i]) + C[N].first);
		}
	}

	cout << res << endl;
}

