LL N;
LL A[100000], B[100000];
bool usedA[100000], usedB[100000];

LL sum = 0;
LL cat() {
	LL mxqq = 0;
	LL mxqw = 0;
	LL mnwq = INFLL;
	LL mnqw = INFLL;
	REP(i, 0, N) {
		if (usedA[i] && usedB[i]) mxqq = max(mxqq, B[i]);
		if (usedA[i] && !usedB[i]) mxqw = max(mxqw, A[i]);
		if (!usedA[i] && usedB[i]) mnwq = min(mnwq, A[i]);
		if (usedA[i] && !usedB[i]) mnqw = min(mnqw, B[i]);
	}
	return sum - max(mxqq, mxqw) + min(mnwq, mnqw);
}

LL sub() {
	vector<PP> v;
	REP(i, 0, N) {
		v.push_back(PP(A[i], i));
		v.push_back(PP(B[i], i + N));
	}
	sort(v.begin(), v.end());

	REP(i, 0, N) {
		int idx = v[i].second;
		if (idx < N) {
			usedA[idx] = true;
		} else {
			usedB[idx - N] = true;
		}
	}

	int cntA = 0;
	int cntB = 0;
	REP(i, 0, N) {
		if (usedA[i] && !usedB[i]) ++cntA;
		if (!usedA[i] && usedB[i]) ++cntB;
	}

	REP(i, 0, N) {
		sum += v[i].first;
	}
	if (cntA == 0 || cntB == 0) return sum;

	LL mn = INFLL;
	mn = min(mn, cat());
	REP(i, 0, N) {
		swap(A[i], B[i]);
		swap(usedA[i], usedB[i]);
	}
	mn = min(mn, cat());
	return mn;
}

int main() {
	cin >> N;
	REP(i, 0, N) {
		cin >> A[i] >> B[i];
	}
	cout << sub() << endl;

	return 0;
}

