void dfs(int depth) {
  if(depth > n) {
    path[depth] = path[1];
    ll cost = 0;
    for(int i = 1; i <= n; i++) {
      cost += min(a[path[i]], b[path[i + 1]]);
    }
    if(cost < ans) {
      ans = cost;
      way.clear();
      for(int i = 1; i <= n + 1; i++) {
        way.push_back(path[i]);
      }
    }
  } else {
    for(int i = 1; i <= n; i++) {
      if(!vis[i]) {
        vis[i] = 1;
        path[depth] = i;
        dfs(depth + 1);
        vis[i] = 0;
      }
    }
  }
}


