int n;
set < pair < int, int > > s, A, B;

void make(int i, int j)
{
        res += min(a[i], b[j]);

        s.erase({a[i], i});
        s.erase({a[j], j});
        s.erase({b[j], - j});
        A.erase({a[i], i});
        A.erase({a[j], j});
        B.erase({b[j], j});

        a[i] = a[j];
        s.insert({a[i], i});
        A.insert({a[i], i});
}

long long solve1()
{
        res = 0;
        A.clear();
        B.clear();
        s.clear();

        for(int i = 1; i <= n; i++){
                A.insert({a[i], i});
                B.insert({b[i], i});

                s.insert({a[i], i});
                s.insert({b[i], - i});
        }

        for(int i = 1; i < n; i++){
                auto p = *A.begin();
                int h = abs(p.se);

                if(p.se > 0){
                        B.erase({b[h], h});
                        int need = (--B.end())->se;
                        B.insert({b[h], h});
                        make(h, need);
                } else{
                        A.erase({a[h], h});
                        int need = (--A.end())->se;
                        A.insert({a[h], h});
                        make(need, h);
                }
        }

        res += min(A.begin()->fi, B.begin()->fi);
        return res;
}

