#define int long long
using namespace std;
using II = pair<int, int>;
using VI = vector<int>;
using VVI = vector<VI>;
using VVVI = vector<VVI>;
using VII = vector<II>;
const int MOD = 1e9 + 7;
class UnionFind {
public:
  VI par, rank;
  UnionFind(int n) {
    par = VI(n); iota(par.begin(), par.end(), 0);
    rank = VI(n, 0);
  }
  int root(int x) {
    if (par[x] == x) {
      return x;
    } else {
      return par[x] = root(par[x]);
    }
  }
  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) { return; }
    if (rank[x] < rank[y]) {
      par[x] = y;
    } else {
      par[y] = x;
      if (rank[x] == rank[y]) { rank[x]++; }
    }
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
};

int N;
int solve(const VII& A, const VII& B) {
  UnionFind uf(N);
  vector<bool> used(N);
  int ans = 0;
  int k = N - 1;
  REP (i, N) {
    while (used[k]) {
      k--;
    }
    int j = k;
    if (i < N - 1) {
      while (uf.same(A[i].second, B[j].second)) {
        j--;
      }
      used[j] = true;
      uf.unite(A[i].second, B[j].second);
    }
    ans += min(A[i].first, B[j].first);
  }
  return ans;
}

