#define int long long
using namespace std;
typedef tuple<int, int, int> T;

int n;
int a[100000], b[100000];
T tup[200000];	//(cost, type, id)

bool check(bool used[]) {
	int i;
	bool exist[2][100000] = {false};

	rep(i, 2 * n) {
		if (used[i]) {
			exist[get<1>(tup[i])][get<2>(tup[i])] = true;
		}
	}

	rep(i, n) if (!exist[0][i]) break; if (i == n) return true;
	rep(i, n) if (!exist[1][i]) break; if (i == n) return true;
	rep(i, n) if (exist[0][i] && exist[1][i]) break; return i < n;
}

int toAns(bool used[]) {
	int i, ret = 0;
	rep(i, 2 * n) {
		if (used[i]) ret += get<0>(tup[i]);
	}
	return ret;
}

signed main() {
	int i;

	cin >> n;
	rep(i, n) cin >> a[i] >> b[i];
	rep(i, n) { tup[2 * i] = T(a[i], 0, i); tup[2 * i + 1] = T(b[i], 1, i); }
	sort(tup, tup + 2 * n);

	static bool used[200000] = {false};
	int ans = 1e+15;

	rep(i, n) used[i] = true;
	if (check(used)) { ans = min(ans, toAns(used)); }

	used[n - 1] = false; used[n] = true;
	if (check(used)) { ans = min(ans, toAns(used)); }

	used[n] = false; used[n + 1] = true;
	if (check(used)) { ans = min(ans, toAns(used)); }

	rep(i, n) used[i] = true;
	used[n - 2] = false; used[n] = true;
	if (check(used)) { ans = min(ans, toAns(used)); }

	cout << ans << endl;
	return 0;
}

