    scanf("%d", &n);
    vector<int> A(n + 1), B(n + 1);
    FI(i, 1, n) scanf("%d%d", &A[i], &B[i]);
    auto cmpa = [&](int i, int j) {
        return A[i] != A[j] ? A[i] < A[j] : i < j;
    };
    auto cmpb = [&](int i, int j) {
        return B[i] != B[j] ? B[i] < B[j] : i < j;
    };
    set<int, decltype(cmpa)> X(cmpa);
