int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    ll tmp_a, tmp_b;
    pair_ll a[n];
    pair_ll b[n];
    for (int i = 0; i < n; ++i) {
        cin >> tmp_a >> tmp_b;
        a[i] = make_pair(i, tmp_a);
        b[i] = make_pair(i, tmp_b);
    }

    sort(a, a + n, comp_sec);
    sort(b, b + n, comp_sec);

    int a_ix = 0;
    int b_ix = 0;
    int count = 1;
    int ab[n];
    memset(ab, 0, sizeof(ab));
    ll sum = 0;
    ll last_val = 0;
    bool dob = false;
    while (count <= n){
        if (a[a_ix].second < b[b_ix].second) {
            if (count == n) last_val = a[a_ix].second;
            sum += a[a_ix].second;
            if (ab[a[a_ix].first] != 0) {
                dob = true;
            }
            ab[a[a_ix].first]++;
            a_ix++;
        } else {
            if (count == n) last_val = b[b_ix].second;
            sum += b[b_ix].second;
            if (ab[b[b_ix].first] != 0) {
                dob = true;
            }
            ab[b[b_ix].first]++;
            b_ix++;
        }  
        count++;
    }

    if (dob || a_ix * b_ix == 0) {
        cout << sum << '\n';
        return 0;
    }

    ll last_val_plus;
    if (a[a_ix].second < b[b_ix].second) {
        last_val_plus = a[a_ix].second;
    } else {
        last_val_plus = b[b_ix].second;
    }

    cout << sum + last_val_plus - last_val << '\n';

    return 0;
}

