#include <bits/stdc++.h>
using namespace std;
#define N 201000

struct node {
	int num,d,id;
}a[N];
int n,x,y,cnt,v[N][2],s[2];
long long ans,Ans,res;

bool cmp(node a,node b) {return a.num<b.num;}

int main()
{
	scanf("%d",&n);
	for (int i=1;i<=n;i++) {
		scanf("%d%d",&x,&y);
		a[++cnt].num=x; a[cnt].d=0; a[cnt].id=i;
		a[++cnt].num=y; a[cnt].d=1; a[cnt].id=i;
	}
	sort(a+1,a+cnt+1,cmp);
	for (int i=1;i<=n;i++) v[a[i].id][a[i].d]=1,ans+=a[i].num;
	for (int i=1;i<=n;i++)
		if (v[i][0]+v[i][1]==1) {
			if (v[i][0]) s[0]++;
			if (v[i][1]) s[1]++;
		}
	if (s[0] && s[1] && s[0]+s[1]==n); else return printf("%lld\n",ans),0;

	Ans=1e17;
	for (int st=1;st<=n;st++)
	{
		res=ans-a[st].num+a[n+1].num;
		v[a[st].id][a[st].d]=0,s[a[st].d]--;
		v[a[n+1].id][a[n+1].d]=1;
		if (v[a[n+1].id][0]+v[a[n+1].id][1]==1) s[a[n+1].d]++;
		else s[a[n+1].d^1]--;
		if (s[0] && s[1] && s[0]+s[1]==n); else {Ans=min(Ans,res); continue;}

		res=res-a[n+1].num+a[n+2].num;
		v[a[n+1].id][a[n+1].d]=0,s[a[n+1].d]--;
		v[a[n+2].id][a[n+2].d]=1;
		if (v[a[n+2].id][0]+v[a[n+2].id][1]==1) s[a[n+2].d]++;
		else s[a[n+2].d^1]--;
		if (s[0] && s[1] && s[0]+s[1]==n); else Ans=min(Ans,res);		
	}
	printf("%lld\n",Ans);
	return 0;
}

