using namespace std;

typedef vector<int> vec;
typedef vector<vec> mat;
typedef pair<int, int> Pii;

template<typename T>
void readvec(vector<T> &a);
void readindex(vector<int> &a);



signed main(){

    int N; cin >> N;
    vec A(N), B(N);
    REP(i, N) cin >> A[i] >> B[i];
    vector<Pii> a(N), b(N);
    REP(i, N){
        a[i] = Pii(A[i], i);
        b[i] = Pii(B[i], i);
    }
    SORT(a); SORT(b);
    SORT(A); SORT(B);

    vec Bm(N);
    REP(i, N) Bm[i] = B[a[i].second];
    IREP(i, N - 1) Bm[i] = min(Bm[i], Bm[i + 1]);

    int ans = INF;
    int tmp = 0;
    REP(i, N) tmp += B[i];
    ans = min(ans, tmp);
    tmp = 0;
    REP(i, N) tmp += A[i];
    ans = min(ans, tmp);


    REP(i, N - 1){
        tmp += B[i] - A[N - 1 - i];
        int tmp2 = tmp;
        if(B[i] == Bm[N - 1 - i]){
            tmp2 += B[i + 1] - B[i];
        }
        ans = min(ans, tmp2);
    }
    cout << ans;

    return 0;
}


