int main()
{

	cin>>n;
	for(int i=1;i<=n;i++)
	{
		cin>>a[i]>>b[i];
		sum1+=a[i]; sum2+=b[i];
		v.pb(mp(a[i],i)); v.pb(mp(b[i],i));
	}
	sort(v.begin(),v.end());
	for(int i=0;i<n;i++)
