#define SIZE 100005

using namespace std;
typedef long long int ll;
typedef pair <int,int> P;

ll A[SIZE];
ll B[SIZE];
bool use[SIZE];

int main()
{
	int n;
	scanf("%d",&n);
	for(int i=0;i<n;i++) scanf("%lld %lld",&A[i],&B[i]);
	ll sa=0,sb=0;
	for(int i=0;i<n;i++) sa+=A[i],sb+=B[i];
	vector <P> vx;
	for(int i=0;i<n;i++)
	{
		vx.push_back(P(A[i],i));
		vx.push_back(P(B[i],i));
	}
	sort(vx.begin(),vx.end());
	for(int i=0;i<n;i++) use[vx[i].second]=true;
	bool up=true;
	for(int i=0;i<n;i++)
	{
		if(!use[i])
		{
			up=false;
		}
	}
	ll ret=0;
	if(!up)
	{
		for(int i=0;i<n;i++) ret+=vx[i].first;
	}
	else
	{
		for(int i=0;i<n;i++) ret+=vx[i].first;
		ll mn=-1;
		for(int i=0;i<n;i++)
		{
			ll vl;
			if(i==vx[n-1].second)
			{
				vl=max(A[i],B[i])-vx[n-2].first;
			}
			else
			{
				vl=max(A[i],B[i])-vx[n-1].first;
			}
			if(mn==-1) mn=vl;
			else mn=min(mn,vl);
		}
		ret+=mn;
	}
	ret=min(ret,sa);
	ret=min(ret,sb);
	printf("%lld\n",ret);
	return 0;
}

