	REP(i,n){
		ll a,b;cin >> a >> b;
		ans += a;
		A.PB(MP(a,i));
		B.PB(MP(b,i));
	}

	sort(ALL(A),greater<pair<ll,ll>>());
	sort(ALL(B));
	ll cou = 0;

	REP(i,n){
		//cout << A[i].FI << " " << A[i].SE << " " << mp[A[i].SE] << endl;
		while(used[B[cou].SE])cou++;
		int tmp = cou;
		while(tmp < n && uf.same(B[tmp].SE,A[i].SE) || used[B[tmp].SE])tmp++;
		if(tmp < n - 1 && A[i].FI > B[tmp].FI){
			ans -= A[i].FI;
			ans += B[tmp].FI;				
			used[B[tmp].SE] = true;
			uf.unite(B[tmp].SE,A[i].SE);
		}
	}

	ll seica = 0;
	UF uuf(n);
	REP(i,111111)used[i] = false;
	sort(ALL(A));
	sort(ALL(B),greater<pair<ll,ll>>());
	REP(i,n)seica += B[i].FI;
	cou = 0;
	REP(i,n){
		//cout << A[i].FI << " " << A[i].SE << " " << mp[A[i].SE] << endl;
		while(used[A[cou].SE])cou++;
		int tmp = cou;
		while(tmp < n && uuf.same(A[tmp].SE,B[i].SE) || used[A[tmp].SE])tmp++;
		if(tmp < n - 1 && B[i].FI > A[tmp].FI){
			seica -= B[i].FI;
			seica += A[tmp].FI;				
			used[A[tmp].SE] = true;
			uuf.unite(A[tmp].SE,B[i].SE);
		}
	}

	cout << min(ans,seica) << endl;

	return 0;
}

