ll calc(int n)
{
    ll cnt = 0;
    for(int i = 1; i <= n; i++)
    {
        if(i<n)
        {
            cnt += min(a[s[i]], b[s[i+1]]);
        }
        else
        {
            cnt += min(a[s[n]], b[s[1]]);
        }
    }
    return cnt;
}
int main()
{
    int n;
