#include <iostream>
#include <algorithm>
#include <vector>

using namespace std;

typedef pair<int, int> P;
typedef pair<P, int> P_;

vector<P_> p;
int A[100000];
int B[100000];
int ord_a[100000];
int ord_b[100000];
bool used[100000];

int main(){
    int N;
    cin >> N;

    long suma = 0, sumb = 0;
    for(int i = 0; i < N; i++){
        cin >> A[i] >> B[i];
        p.push_back(P_(P(A[i], i), 0));
        p.push_back(P_(P(B[i], i), 1));
        suma += A[i];
        sumb += B[i];
    }
    long ans = min(suma, sumb);
    sort(p.begin(), p.end());
    bool doubled = false;
    long sum = 0;
    for(int i = 0; i < N; i++){
        int a = p[i].first.first;
        int idx = p[i].first.second;
        int f = p[i].second;
        if(!used[idx]) used[idx] = true;
        else doubled = true;
        if(f == 0) ord_a[idx] = i;
        else ord_b[idx] = i;
        sum += a;
    }
    for(int i = N; i < 2*N; i++){
        int a = p[i].first.first;
        int idx = p[i].first.second;
        int f = p[i].second;
        if(f == 0) ord_a[idx] = i;
        else ord_b[idx] = i;
    }
    if(doubled){
        ans = min(ans, sum);
    }else{
        for(int i = 0; i < N; i++){
            long tmp = sum;
            if(ord_a[i] < N){
                tmp -= A[i];
                if(ord_b[i] == N) tmp += p[N+1].first.first;
                else tmp += p[N].first.first;
            }else{
                tmp -= B[i];
                if(ord_a[i] == N) tmp += p[N+1].first.first;
                else tmp += p[N].first.first;
            }
            ans = min(ans, tmp);
        }
    }
    cout << ans << endl;
}

