using namespace std;
#define ll long long
#define Maxn 100000
set<pair<int,int> > st;
int a[Maxn+5],b[Maxn+5];
int x[Maxn+5];
int have[Maxn+5];
int main(){
	int n;
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%d%d",&a[i],&b[i]);
		st.insert(make_pair(a[i],i<<1));
		st.insert(make_pair(b[i],(i<<1)|1));
	}
	set<pair<int,int> >::iterator it;
	int now=n,tmp;
	it=st.begin();
	ll sum=0;
	while(now--){
		tmp=(it->second)>>1;
		sum+=(it->first);
		if((it->second)&1){
			x[tmp]+=1;
		}
		else{
			x[tmp]+=2;
		}
		it++;
	}
	for(int i=1;i<=n;i++){
		have[x[i]]++;
	}
	if(have[3]||have[0]||(!have[2])||(!have[1])){
		cout<<sum<<endl;
		return 0;
	}
	it--;
	x[tmp]-=(it->first);
	sum-=(it->first);
	it++;
	while(it!=st.end()){
		tmp=(it->second)>>1;
		if(x[tmp]){
			sum+=(it->first);
			break;
		}
		it++;
	}
	cout<<sum<<endl;
	return 0;
}

