ll pow_long(ll x, ll k){
  ll res = 1;
  while(k > 0){
    if(k % 2) res *= x;
    x *= x;
    k /= 2;
  }
  return res;
}

ll pow_mod(ll x, ll k){
  ll res = 1;
  while(k > 0){
    if(k % 2){
      res *= x; res %= MOD;
    }
    x *= x; x %= MOD;
    k /= 2;
  }
  return res;
}

ll inverse(ll x){return pow_mod(x, MOD - 2);};

ll gcd(ll a, ll b){
    if(b == 0) return a;
    return gcd(b, a % b);
}

ll lcm(ll x, ll y){return x / gcd(x, y) * y;};

ll kai_mod(ll x){
  if(x == 0) return 1;
  return x * kai_mod(x-1) % MOD;
}

//約数の列挙O(√n)
vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}

//素因数列挙
vector<ll> MakePrimeList(ll x) {
    vector<ll> res;
    for(ll k=2; k*k<=x; k++) {
        if(x % k == 0) {
            res.pb(k);
            while(x % k == 0) x /= k;
        }
    }
    if(x > 1) res.push_back(x);
    return res;
}


//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}
ll N;
vector<pair<ll, ll>> AB;
void solve(){
  vector<pair<ll, ll>> X;
  ll left = 0, right = 0;
  rep(i, N){
    X.pb({AB[i].f, i+1});
    X.pb({AB[i].s, -(i+1)});
    left += AB[i].f;
    right += AB[i].s;
  }
  sort(X.begin(), X.end());
  ll ans = min(left, right);
  ll sum = 0;
  set<ll> used;
  bool ok = 0;
  rep(i, N){
    sum += X[i].f;
    if(used.count(abs(X[i].s))) ok = 1;
    used.insert(abs(X[i].s));
  }
  if(ok){
    chmin(ans, sum);
  }else{
    sum -= X[N-1].f;
    ll l = INFL;
    ll r = INFL;
    for(ll i = N; i < 2 * N; i++){
      if(X[i].s > 0) l = min(l, X[i].f);
      if(X[i].s < 0) r = min(r, X[i].f);
    }
    sum += min(l, r);
    chmin(ans, sum);
  }
  cout << ans << endl;
}
int main(){
  cin >> N;
  AB.resize(N);
  rep(i, N) cin >> AB[i].f >> AB[i].s;
  solve();
}

