	int newSum=Sum-sum[t]+(3-sum[t]);
	if(ID(sx[n].se)!=t || (newSum==n || newSum==2*n))chkmin(ANS,ans-sx[n].fi);
	else {
		chkmin(ANS,ans+sx[n+1].fi-sx[n-1].fi);
		chkmin(ANS,ans+sx[n+2].fi-sx[n].fi);
	}
	printf("%lld\n",ANS);
}

