const int N = 1e5+7, p = 1e9+7;
int a[N], b[N], s[N];
ll calc(int n)
{
    ll cnt = 0;
    for(int i = 1; i <= n; i++)
    {
        if(i<n)
        {
            cnt += min(a[s[i]], b[s[i+1]]);
        }
        else
        {
            cnt += min(a[s[n]], b[s[1]]);
        }
    }
    return cnt;
}
int main()
{
    int n;
    srand(time(0));
    scanf("%d", &n);
    ll ans = 1e18, last = 1e18;
    for(int i = 1; i <= n; i++)
    {
        s[i] = i;
        scanf("%d%d", &a[i], &b[i]);
    }
    for(int i = 1; i <= 1e8/n; i++)
    {
        ll cnt = 0;
        int x = rand()%n+1, y = rand()%n+1;
        swap(s[x], s[y]);
        cnt = calc(n);
        if(cnt>last)
        {
            swap(s[x], s[y]);
        }
        ans = min(ans, cnt);
    }
    printf("%lld\n", ans);
    return 0;
}

