        if (take_a == 0 || take_b == 0 || hsh_a != hsh_b)
            ans = min(ans, sum_a + sum_b);
        else
        {
            ans = min(ans, sum_a + sum_b + b[take_b].fst - b[take_b - 1].fst);
            ans = min(ans, sum_a + sum_b + a[take_a].fst - a[take_a - 1].fst);
        }

        if (take_b > 0)
        {
            sum_b -= b[take_b - 1].fst;
            hsh_b ^= value[b[take_b - 1].snd];
        }
        if (take_a < n)
        {
            sum_a += a[take_a].fst;
            hsh_a ^= value[a[take_a].snd];
        }
    }

    return ans;
}

