void solve(long long N, std::vector<long long> A, std::vector<long long> B){
  long long ans;
  ans = accumulate(A.begin(), A.end(), 0LL);
  ans = min(ans, accumulate(B.begin(), B.end(), 0LL));
  vector< pair<long long, int> > s;
  for (int i = 0; i < N; i++) {
    s.emplace_back(A[i], i);
    s.emplace_back(B[i], i);
  }
  sort(s.begin(), s.end());

  vector<int> d(N, 0);
  bool flag = false;

  long long t = 0;
  for (int i = 0; i < N; i++) {
    t += s[i].first;
    ++d[s[i].second];
    if (d[s[i].second] == 2) {
      flag = true;
    }
  }

  if (flag) {
    ans = min(ans, t);
  } else {
    int n1 = s[N].second;
    for (int i = 0; i < N; i++) {
      if (s[i].second == n1) {
        ans = min(ans, t - s[i].first + s[N+1].first);
      } else {
        ans = min(ans, t - s[i].first + s[N].first);
      }
    }
  }

  std::cout << ans << std::endl;
}

int main(){
  long long N;
  scanf("%lld",&N);
  std::vector<long long> A(N);
  std::vector<long long> B(N);
  for(int i = 0 ; i < N ; i++){
    scanf("%lld",&A[i]);
    scanf("%lld",&B[i]);
  }
  solve(N, std::move(A), std::move(B));
  return 0;
}

