constexpr ll TEN(int n) { return (n == 0) ? 1 : 10 * TEN(n - 1); }
template <class T> using V = vector<T>;
template <class T> using VV = V<V<T>>;

struct Scanner {
    FILE* fp = nullptr;
    char line[(1 << 15) + 1];
    size_t st = 0, ed = 0;
    void reread() {
        memmove(line, line + st, ed - st);
        ed -= st;
        st = 0;
        ed += fread(line + ed, 1, (1 << 15) - ed, fp);
        line[ed] = '\0';
    }
    bool succ() {
        while (true) {
            if (st == ed) {
                reread();
                if (st == ed) return false;
            }
            while (st != ed && isspace(line[st])) st++;
            if (st != ed) break;
        }
        if (ed - st <= 50) reread();
        return true;
    }
    template <class T, enable_if_t<is_same<T, string>::value, int> = 0>
    bool read_single(T& ref) {
        if (!succ()) return false;
        while (true) {
            size_t sz = 0;
            while (st + sz < ed && !isspace(line[st + sz])) sz++;
            ref.append(line + st, sz);
            st += sz;
            if (!sz || st != ed) break;
            reread();
        }
        return true;
    }
    template <class T, enable_if_t<is_integral<T>::value, int> = 0>
    bool read_single(T& ref) {
        if (!succ()) return false;
        bool neg = false;
        if (line[st] == '-') {
            neg = true;
            st++;
        }
        ref = T(0);
        while (isdigit(line[st])) {
            ref = 10 * ref + (line[st++] - '0');
        }
        if (neg) ref = -ref;
        return true;
    }
    template <class T> bool read_single(V<T>& ref) {
        for (auto& d : ref) {
            if (!read_single(d)) return false;
        }
        return true;
    }
    void read() {}
    template <class H, class... T> void read(H& h, T&... t) {
        bool f = read_single(h);
        assert(f);
        read(t...);
    }
    Scanner(FILE* _fp) : fp(_fp) {}
};

struct Printer {
  public:
    template <bool F = false> void write() {}
    template <bool F = false, class H, class... T>
    void write(const H& h, const T&... t) {
        if (F) write_single(' ');
        write_single(h);
        write<true>(t...);
    }
    template <class... T> void writeln(const T&... t) {
        write(t...);
        write_single('\n');
    }

    Printer(FILE* _fp) : fp(_fp) {}
    ~Printer() { flush(); }

  private:
    static constexpr size_t SIZE = 1 << 15;
    FILE* fp;
    char line[SIZE], small[50];
    size_t pos = 0;
    void flush() {
        fwrite(line, 1, pos, fp);
        pos = 0;
    }
    void write_single(const char& val) {
        if (pos == SIZE) flush();
        line[pos++] = val;
    }
    template <class T, enable_if_t<is_integral<T>::value, int> = 0>
    void write_single(T val) {
        if (pos > (1 << 15) - 50) flush();
        if (val == 0) {
            write_single('0');
            return;
        }
        if (val < 0) {
            write_single('-');
            val = -val; // todo min
        }
        size_t len = 0;
        while (val) {
            small[len++] = char('0' + (val % 10));
            val /= 10;
        }
        for (size_t i = 0; i < len; i++) {
            line[pos + i] = small[len - 1 - i];
        }
        pos += len;
    }
    void write_single(const string& s) {
        for (char c : s) write_single(c);
    }
    void write_single(const char* s) {
        size_t len = strlen(s);
        for (size_t i = 0; i < len; i++) write_single(s[i]);
    }
    template <class T> void write_single(const V<T>& val) {
        auto n = val.size();
        for (size_t i = 0; i < n; i++) {
            if (i) write_single(' ');
            write_single(val[i]);
        }
    }
};

Scanner sc = Scanner(stdin);
Printer pr = Printer(stdout);

int main() {
    int n;
    sc.read(n);
    using P = pair<ll, ll>;
    V<P> p(n);
    for (int i = 0; i < n; i++) {
        sc.read(p[i].first, p[i].second);
    }

    ll ans = TEN(18);
    {
        ll sm = 0;
        for (int i = 0; i < n; i++) {
            sm += p[i].first;
        }
        ans = min(ans, sm);
    }
    {
        ll sm = 0;
        for (int i = 0; i < n; i++) {
            sm += p[i].second;
        }
        ans = min(ans, sm);
    }
    for (int ph = 0; ph < 2; ph++) {
        ll sm = 0;
        for (int i = 0; i < n; i++) {
            sm += p[i].first;
        }

        ll buf = 0;
        for (int ph0 = 0; ph0 < 2; ph0++) {
            ll mi = TEN(18);
            for (int i = 0; i < n; i++) {
                buf = min(buf, mi - p[i].first);
                mi = min(mi, p[i].second);
            }
            reverse(p.begin(), p.end());
        }
        ans = min(ans, sm + buf);
    }

    {
        ll sm = 0;
        priority_queue<ll, V<ll>, greater<ll>> que0, que1;
        for (int i = 0; i < n; i++) {
            if (p[i].first > p[i].second) swap(p[i].first, p[i].second);
            sm += p[i].first;
            que0.push(p[i].second);
            que1.push(-p[i].first);
        }
               ;
        int cnt = 0;
        while (que0.size()) {
            ll p0 = que0.top(); que0.pop();
            ll p1 = que1.top(); que1.pop();
                       ;
            if (cnt < 2 || p0 + p1 < 0) {
                cnt++;
                sm += p0 + p1;
            }
        }
        ans = min(ans, sm);
    }
    pr.writeln(ans);
    return 0;
}

