namespace ds {
	struct UnionFind {
		vector<int> par, rank;
		int n_merges;

		UnionFind(int n) : par(n), rank(n, 1), n_merges(0) {
			iota(begin(par), end(par), 0);
		}
		void merge(int a, int b) {
			int x = group(a), y = group(b);
			if (x == y) return;  //same
			n_merges++;
			if (rank[x] < rank[y]) par[x] = y;
			else if (rank[x] > rank[y]) par[y] = x;
			else { par[x] = y; rank[x]++; }
		}
		int group(int a) {
			if (par[a] == a) return a;
			return par[a] = group(par[a]);
		}
		bool same(int a, int b) {
			return group(a) == group(b);
		}
	};
}

int main() {
	int N; cin >> N;
	vi A(N), B(N);
	rep(i, N) cin >> A[i] >> B[i];
	minPQ<pair<pii, int> > minval;
	maxPQ<pii> maxval[2];
	rep(i, N) {
		minval.push(mp(mp(A[i], i), 0));
		minval.push(mp(mp(B[i], i), 1));
		maxval[0].push(mp(A[i], i));
		maxval[1].push(mp(B[i], i));
	}
	vvi used(N, vi(2));
	ds::UnionFind uf(N);
	ll ans = 0;
	rep(i, N) {
		while (!minval.empty() && used[minval.top().first.second][minval.top().second]) minval.pop();
		while (!maxval[0].empty() && used[maxval[0].top().second][0]) maxval[0].pop();
		while (!maxval[1].empty() && used[maxval[1].top().second][1]) maxval[1].pop();

		pair<pii, int> top;
		for(;;) {
			top = minval.top();
			minval.pop();
			if (! used[top.first.second][top.second]) {
				used[top.first.second][top.second] = 1;
				break;
			}
		}
		ans += top.first.first;
		if (i == N - 1) break;
		int ind = top.first.second;
		int side = top.second;
		int opp = maxval[1 - side].top().second;
		while (uf.same(ind, opp)) {
			auto temp = maxval[1 - side].top();
			maxval[1 - side].pop();
			opp = maxval[1 - side].top().second;
			maxval[1 - side].pop();
			maxval[1 - side].push(temp);
		}
		else {
			maxval[1 - side].pop();
		}
		uf.merge(ind, opp);
		used[opp][1 - side] = 1;
	}
	cout << ans << endl;
	exit(0);
	return 0;
}

