bool check(bool used[]) {
	int i;
	bool exist[2][100000] = {false};

	rep(i, 2 * n) {
		if (used[i]) {
			exist[get<1>(tup[i])][get<2>(tup[i])] = true;
		}
	}

	rep(i, n) if (!exist[0][i]) break; if (i == n) return true;
	rep(i, n) if (!exist[1][i]) break; if (i == n) return true;

	int cnt1 = 0, cnt2 = 0;
	rep(i, n) if (exist[0][i] && exist[1][i]) { cnt1++; }
	rep(i, n) if (!exist[0][i] && !exist[1][i]) { cnt2++; }
	return (cnt1 > 0 && cnt1 == cnt2);
}

int toAns(bool used[]) {
	int i, ret = 0;
	rep(i, 2 * n) {
		if (used[i]) ret += get<0>(tup[i]);
	}
	return ret;
}

