void solve() {
  int n; cin >> n;
  vi arr(2*n); cin >> arr;
  vi num(2*n);
  iota(ALL(num), 0);
  sort(ALL(num), [&](int a, int b) { return arr[a] < arr[b]; });
  vb det(2, false);
  vi cnt(n, 0);
  bool ok = false;
  ll ans = 0;
  rep(i,n) {
    ans += arr[num[i]];
    det[num[i] & 1] = true;
    ok |= cnt[num[i] >> 1]++;
  }
  if (det[0] && det[1] && !ok) {
    if (num[n] ^ num[n-1] != 1) {
      ans += arr[num[n]] - arr[num[n-1]];
    } else {
      ans += min(arr[num[n]] - arr[num[n-2]], arr[num[n+1] - arr[num[n-1]]]);
    }
  }
  cout << ans << endl;
}


