int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int N;
    cin >> N;

    priority_queue<tuple<int64_t, int>> A;
    for (int i = 0; i < N; i++) {
        int64_t a;
        cin >> a;

        A.push(make_tuple(a, i));
    }

    vector<tuple<int64_t, int>> B(N);
    for (int i = 0; i < N; i++) {
        cin >> get<0>(B[i]);
        get<1>(B[i]) = i;
    }

    sort(B.begin(), B.end());

    map<int64_t, bool> used;

    int64_t ans = 0;
    for (int i = 0; i < N; i++) {
        int64_t a = get<0>(A.top()),
                b = get<0>(B[i]);
        int ai = get<1>(A.top()),
            bi = get<1>(B[i]);

        if (ai != bi) {
            used[a] = true;
            ans += min(a, b);
            A.pop();
            continue;
        }
        if (used[a]) {
            ans += min(a, b);
            A.pop();
            continue;
        }
        if (A.size() == 1) assert(false);

        A.pop();

        used[get<0>(A.top())] = true;
        ans += min(get<0>(A.top()), b);

        A.pop();

        A.push(make_tuple(a, ai));
    }
    cout << ans << endl;

    return 0;
}

