struct Data {
    long long val;
    int ind;
    char c;
    Data(long long val, int ind, char c) : val(val), ind(ind), c(c) { }
    friend bool operator < (Data a, Data b) { return a.val < b.val; }
};

int main() {
    int n; cin >> n;
    vector<Data> input;
    for (int i = 0; i < n; ++i) {
        long long a, b;
        cin >> a >> b;
        input.push_back(Data(a, i, 'a'));
        input.push_back(Data(b, i, 'b'));
    }
    sort(input.begin(), input.end());

    long long res = 0;
    bool existA = false;
    bool existB = false;
    set<int> se;
    for (int i = 0; i < n; ++i) {
        res += input[i].val;
        if (input[i].c == 'a') existA = true;
        else existB = true;
        se.insert(input[i].ind);
    }

    if (se.size() == n) {
        if (existA && existB) {
            if (input[n-1].ind == input[n].ind) {
                res += input[n+1].val - input[n-1].val;
            }
            else {
                res += input[n].val - input[n-1].val;
            }
        }
    }

    cout << res << endl;
}

