struct Pt {
    ll a, b, num;
} a[N], b[N];

ll f1(Pt a) {
    return a.a + a.b - min(a.a, a.b);
}

ll f2(Pt a) {
    return min(a.a, a.b);
}

bool cmp1(Pt a, Pt b) {
    return f1(a) < f1(b);
}

bool cmp2(Pt a, Pt b) {
    return f2(a) > f2(b);
}

