	rep(i,n) cin >> a[i] >> b[i];

	vector<pll> ary;

	rep(i,n){
		ary.push_back(pll(a[i],i));
		ary.push_back(pll(b[i],n+i));
	}

	sort(begin(ary),end(ary));
	ll ans = 0LL;

	rep(i,2*n){
		const ll val = ary[i].first;
		const int idx = ary[i].second;
		if(i < n) ans += val;

		if(i < n){
			if(idx < n)
				aused.push_back(pll(val,idx));
			else
				bused.push_back(pll(val,idx - n));
		} else {
			if(idx < n)
				arest.push_back(pll(val,idx));
			else 
				brest.push_back(pll(val,idx - n));
		}
	}

	sort(begin(aused),end(aused));
	sort(begin(bused),end(bused));
	sort(rbegin(arest),rend(arest));
	sort(rbegin(brest),rend(brest));

	Union_find uf(n);
	if(aused.size()){
		const int idx = aused[0].second;
		for(auto& elem:aused){
			const int tmp = elem.second;
			uf.unite(idx,tmp);
		}

		for(auto& elem:brest){
			const int tmp = elem.second;
			uf.unite(idx,tmp);
		}
	}

	if(bused.size()){
		const int idx = bused[0].second;
		for(auto& elem:bused){
			const int tmp = elem.second;
			uf.unite(idx,tmp);
		}

		for(auto& elem:arest){
			const int tmp = elem.second;
			uf.unite(idx,tmp);
		}
	}

	int cnt = 0;
	rep(i,n) if(uf.find(i) == i) cnt++;
	if(cnt != 1){
		ll add = 1LL << 50;
		{
			const int asz = min<int>(arest.size(),2);
			const int bsz = min<int>(bused.size(),2);
			rep(i,asz)rep(j,bsz){
				if(arest[i].second == bused[j].second) continue;
				chmin(add,arest[i].first - bused[j].first);
			}	
		}

		{
			const int bsz = min<int>(brest.size(),2);
			const int asz = min<int>(aused.size(),2);
			rep(i,bsz)rep(j,asz){
				if(brest[i].second == aused[j].second) continue;
				chmin(add,brest[i].first - aused[j].first);
			}	
		}

		ans += add;
	}


	cout << ans << endl;

	return 0;
}

