typedef pair<long long, int> P;

int main() {
    int N;
    cin >> N;
    vector<long long> A(N), B(N);
    for(int i=0; i<N; ++i) cin >> A[i] >> B[i];

    long long res = min(accumulate(A.begin(), A.end(), 0LL), 
    accumulate(B.begin(), B.end(), 0LL));

    vector<P> C;
    for(int i=0; i<N; ++i) {
        C.push_back(P(A[i], i));
        C.push_back(P(B[i], i));
    }
    sort(C.begin(), C.end());
    long long sum = 0;
    for(int i=0; i<N; ++i) sum += C[i].first;

    bool flag = false;
    for(int i=0; i<N; ++i) {
        int d1 = distance(C.begin(), lower_bound(C.begin(), C.end(), P(A[i], -1)));
        int d2 = distance(C.begin(), lower_bound(C.begin(), C.end(), P(B[i], -1)));
        if(d1 < N && d2 < N) {
            flag = true;
            break;
        }
    }

    if(flag) {
        res = min(res, sum);
    } else {
        for(int w=0; w<N; ++w) {
            long long tmp = sum;
            if(A[w] <= B[w]) {
                tmp -= A[w];
                if(C[N] != P(B[w], w)) tmp += C[N].first;
                else tmp += C[N + 1].first;
            } else {
                tmp -= B[w];
                if(C[N] != P(A[w], w)) tmp += C[N].first;
                else tmp += C[N + 1].first;
            }
            res = min(res, tmp);
        }
    }

    cout << res << endl;
}

