using namespace std;
using ll=long long;

void solve() {
    int n; cin >> n;
    vector<pair<int, int>> a;
    for (int i = 1; i <= n; i++) {
        int x,y;
        cin >> x >> y;
        a.emplace_back(x,i);
        a.emplace_back(y,-i);
    }
    sort(a.begin(), a.end());

    vector<bool> trk(n);
    ll res = 0;
    int pos = 0, neg = 0;
    for (int i = 0; i < n; i++) {
        res += a[i].first;
        int j = a[i].second;
        trk[abs(j)-1] = true;
        j>0?pos++:neg++;
    }

    int cnt = 0;
    for (int x: trk) cnt+=x;
    int k = n-1;
    while (cnt == n && (pos > 0 && neg > 0)) {
        res -= a[k].first;
        int j = a[k].second;
        trk[abs(j)-1] = false; cnt--; j>0?pos--:neg--;

        res += a[k+1].first;
        j = a[k+1].second;
        if (!trk[abs(j)-1]) cnt++;
        trk[abs(j)-1] = true;
        j>0?pos++:neg++;

        k++;
    }
    cout << res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    solve();
    cout << endl;
}

