typedef long long LL;
const int N=100005;
LL read(){
	LL x=0,f=1;
	char ch=getchar();
	while (!isdigit(ch)&&ch!='-')
		ch=getchar();
	if (ch=='-')
		f=-1,ch=getchar();
	while (isdigit(ch))
		x=(x<<1)+(x<<3)+ch-48,ch=getchar();
	return x*f;
}
int n;
struct IO{
	int v,id;
}a[N],b[N];
bool cmp(IO x,IO y){
	return x.v<y.v;
}
int tax[N],tot=0;
void ins(int id,int p){
	if (tax[id]!=0)
		tot--;
	tax[id]+=p;
	if (tax[id]!=0)
		tot++;
}
LL L[N],R[N];
void solve(){
	LL ans=0;
	for (int i=1;i<=n;i++)
		ans+=min(a[i].v,b[i].v);
	cout << ans << endl;
	exit(0);
}
int main(){
	n=read();
	for (int i=1;i<=n;i++){
		a[i].v=read(),a[i].id=i;
		b[i].v=read(),b[i].id=i;
	}
	sort(a+1,a+n+1,cmp);
	sort(b+1,b+n+1,cmp);
	reverse(b+1,b+n+1);
	memset(L,0,sizeof L);
	memset(R,0,sizeof R);
	for (int i=1;i<=n;i++)
		L[i]=L[i-1]+min(a[i].v,b[i].v);
	for (int i=n;i>=1;i--)
		R[i]=R[i+1]+min(a[i].v,b[i].v);
	int m=1;
	while (m<=n&&a[m].v<b[m].v)
		m++;
	int t=m;
	while (t<=n&&a[t].v==b[t].v)
		t++;
	if (m==1||t>n)
		solve();
	m--,t--;
	memset(tax,0,sizeof tax);
	for (int i=1;i<=m;i++)
		ins(a[i].id,1);
	for (int i=1;i<=m;i++)
		ins(b[i].id,-1);
	if (tot)
		solve();
	for (int i=m+1;i<=t;i++){
		ins(a[i].id,1);
		ins(b[i].id,-1);
		if (tot)
			solve();
	}
	LL ans=1LL<<60;
	for (int i=m+1;i<=t+1;i++)
		ans=min(ans,L[i-2]+R[i+1]+min(a[i].v,b[i-1].v)
								 +min(a[i-1].v,b[i].v));
	cout << ans << endl;
	return 0;
}

