struct W{ll a, b; int id;};

bool cmpA(W l, W r){
	return l.a < r.a;
}

bool cmpB(W l, W r){
	return l.b < r.b;
}

int main(void){
	int n;
	ll a,b;
	vector<W> useA, useB, useA2, useB2;
	cin>>n;
	ll onlyA = 0, onlyB = 0, ans = 0;
	rep(i,n){
		cin>>a>>b;
		W w;
		w.a = a;
		w.b = b;
		w.id = i;
		if(a<=b){
			useA.push_back(w);
			useA2.push_back(w);
		}else{
			useB.push_back(w);
			useB2.push_back(w);
		}
		onlyA += a;
		onlyB += b;
	}
	if(useA.size() == 0){
		cout<<onlyB<<endl;
		return 0;
	}
	if(useB.size() == 0){
		cout<<onlyA<<endl;
		return 0;
	}

	if(n == 2){
		cout<< (min(useA[0].a , useB[0].b) + min(useA[0].b , useB[0].a))<<endl;
		return 0;
	}

	//二重にしたいやつ探す
	sort(useA.begin(),useA.end(),cmpB);
	sort(useB.begin(),useB.end(),cmpA);

	//消したいやつ探す
	sort(useA2.begin(),useA2.end(),cmpA);
	reverse(useA2.begin(),useA2.end());
	sort(useB2.begin(),useB2.end(),cmpB);
	reverse(useB2.begin(),useB2.end());


	W niju,kesi;
	if(useA[0].b < useB[0].a){
		niju = useA[0];
	}else{
		niju = useB[0];
	}
	if(useA2[0].a < useB2[0].b){
		kesi = useB2[0];
	}else{
		kesi = useA2[0];
	}
	if(niju.id != kesi.id){
		ans += max(niju.a, niju.b) - min(kesi.a, kesi.b);
		rep(i,useA.size()){
			ans += useA[i].a;
		}
		rep(i,useB.size()){
			ans += useB[i].b;
		}
		cout<<min(ans,min(onlyA, onlyB))<<endl;
	}else{
		//nijuにする場合
		ll memoMax = 0;
		rep(i,useA.size()){
			if(useA[i].id != niju.id){
				memoMax = max(memoMax, useA[i].a);
			}
		}
		rep(i,useB.size()){
			if(useB[i].id != niju.id){
				memoMax = max(memoMax, useB[i].b);
			}
		}

		//kesiにする場合
		ll memoMin = LINF;
		rep(i,useA.size()){
			if(useA[i].id != kesi.id){
				memoMin = min(memoMin, useA[i].b);
			}
		}
		rep(i,useB.size()){
			if(useB[i].id != kesi.id){
				memoMin = min(memoMin, useB[i].a);
			}
		}
		//cout<<memoMin<<" "<<memoMax<<endl;
		ans += min(max(kesi.a, kesi.b) - memoMax , memoMin - min(niju.a, niju.b));
		rep(i,useA.size()){
			ans += useA[i].a;
		}
		rep(i,useB.size()){
			ans += useB[i].b;
		}
		cout<<min(ans,min(onlyA, onlyB))<<endl;

	}
	return 0;
}

