ll read(){ll x=0,f=1;char c=getchar();while(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}while(c>='0'&&c<='9'){x=x*10+c-'0';c=getchar();}return f*x;}
ll max(ll a,ll b){return a>b?a:b;}
ll min(ll a,ll b){return a<b?a:b;}
void umax(ll& a,ll t){if(t>a)a=t;}
void umin(ll& a,ll t){if(t<a)a=t;}
const ll INF=1ll<<58;
#define MAXN 200011
pll b[MAXN];
ll n;
struct node
	{
		ll minv,pos;
		node(){minv=INF,pos=0;}
		node operator +(const node t)
		{
			node res;
			if(minv<t.minv)res=*this;
			else res=t;
			return res;
		}
	};
struct Segment_Tree
{
	node t[MAXN<<2|1];
	#define rt t[num]
	void modify(un pos,ll k,un l=1,un r=n,un num=1)
	{
		if(l==r){rt.minv=k,rt.pos=l;return;}
		un mid=(l+r)>>1;
		if(pos<=mid)modify(pos,k,l,mid,num<<1);
		else modify(pos,k,mid+1,r,num<<1|1);
		rt=t[num<<1]+t[num<<1|1];
	}
	node Qmin(un ql,un qr,un l=1,un r=n,un num=1)
	{
		if(ql>qr)return node();
		if(ql<=l&&r<=qr)return rt;
		un mid=(l+r)>>1;node res;
		if(ql<=mid)res=res+Qmin(ql,qr,l,mid,num<<1);
		if(qr>mid)res=res+Qmin(ql,qr,mid+1,r,num<<1|1);
		return res;
	}
}sgt;
int main()
{
	n=read();
	for(ll i=1;i<=n;++i)sgt.modify(i,read()),b[i]=pll(read(),i);
	std::sort(b+1,b+n+1),std::reverse(b+1,b+n+1);
	ll ans=0;
	for(ll i=1;i<=n;++i)
	{
		node t=sgt.Qmin(1,b[i].second-1)+sgt.Qmin(b[i].second+1,n);
		ans+=min(b[i].first,t.minv);
		sgt.modify(t.pos,INF);
	}
	printf("%lld\n",ans );
	return 0;
}

