	LL ans = LLONG_MAX, sum = 0;
	for(int i = 1; i <= n; ++i) sum += A[i];
	chkmin(ans, sum);
	sum = 0;
	for(int i = 1; i <= n; ++i) sum += B[i];
	chkmin(ans, sum);

	static int seq[MAXN * 2 + 5];

	for(int i = 1; i <= n; ++i) seq[i] = A[i], seq[n + i] = B[i];
	sort(seq + 1, seq + 2 * n + 1);

	sum = 0;
	for(int i = 1; i <= n; ++i) sum += seq[i];
	for(int i = 1; i <= n; ++i)
	{
		int p0 = lower_bound(seq + 1, seq + 2 * n + 1, A[i]) - seq;
		int p1 = A[i] == B[i] ? p0 + 1 : lower_bound(seq + 1, seq + 2 * n + 1, B[i]) - seq;

		int t = n;
		if(p0 > n) sum += A[i], sum -= seq[t--];
		if(p1 > n) sum += B[i], sum -= seq[t--];
		chkmin(ans, sum);
		if(p1 > n) sum -= B[i], sum += seq[++t];
		if(p0 > n) sum -= A[i], sum += seq[++t];
	}
	printf("%lld\n", ans);
}

int main()
{
	input();
	solve();

	return 0;
}

