ll solve(int n, vector<int> a, vector<int> b) {
    {  // sort by a
        vector<int> order(n);
        iota(ALL(order), 0);
        sort(ALL(order), [&](int i, int j) {
            return a[i] < a[j];
        });
        auto a_ = a;
        auto b_ = b;
        REP (i, n) {
            a[i] = a_[order[i]];
            b[i] = b_[order[i]];
        }
    }
REP (i, n){
    //cerr << i << " :  " << a[i] << " " << b[i] << endl;
}

    // sort by b
    vector<int> order(n);
    iota(ALL(order), 0);
    sort(ALL(order), [&](int i, int j) {
        return b[i] > b[j];
    });

REP (i, n) {
    int j = order[i];
//cerr << i << " -> " << j <<  " :  " << a[i] << " " << b[j] << endl;
}

    // make the graph connected
    vector<bool> used(n);
    function<void (int)> go = [&](int i) {
//cerr << " " << i;
        used[i] = true;
        int j = order[i];
        if (used[j]) return;
        go(j);
    };
    REP (i, n) if (not used[i]) {
        int j = -1;
        if (i >= 1) {
            if (i + 1 == n or not used[i + 1]) {
                j = i - 1;
            } else {
                ll k1 = (ll)min(a[i - 1], b[order[i]]) + min(a[i], b[order[i - 1]]) + min(a[i + 1], b[order[i + 1]]);
                ll k2 = (ll)min(a[i - 1], b[order[i - 1]]) + min(a[i], b[order[i + 1]]) + min(a[i + 1], b[order[i]]);
                if (k1 <= k2) {
                    j = i - 1;
                } else {
                    j = i + 1;
                }
            }
        }
//cerr << "go";
        go(i);
//cerr << endl;
        if (i >= 1) {
            swap(order[i], order[j]);
        }
    }

    ll acc = 0;
    REP (i, n) {
        int j = order[i];
        acc += min(a[i], b[j]);
//cerr << i << " -> " << j <<  " :  " << a[i] << " " << b[j] << endl;
    }
    return acc;
}

int main() {
    int n; cin >> n;
    vector<int> a(n), b(n);
    REP (i, n) cin >> a[i] >> b[i];
    cout << solve(n, a, b) << endl;
    return 0;
}

