int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; i ++)
		scanf("%d %d", &a[i], &b[i]);
	for(int i = 1; i <= n; i ++)
	{
		q[i].val = a[i]; q[i + n].val = b[i];
		q[i].IS = 1; q[i + n].IS = 0;
		q[i].num = i; q[i + n].num = i;
	}
	sort(a + 1, a + n + 1);
	sort(b + 1, b + n + 1);
	sort(q + 1, q + n * 2 + 1, cmp);
	int flag = 1;
	LL ans1 = 1e18, ans2 = 1e18, ans3 = 0;

	for(int i = 1; i <= n; i ++)
	{
		if(a[i] > b[i])
		{
			flag = 0;
			break;
		}
	}
	if(flag)
	{
		ans1 = 0;
		for(int i = 1; i <= n; i ++)
			ans1 += a[i];
	}
	//cout << "! " << ans1 << endl;
	flag = 1;
	for(int i = 1; i <= n; i ++)
	{
		if(b[i] > a[i])
		{
			flag = 0;
			break;
		}
	}
	if(flag)
	{
		ans2 = 0;
		for(int i = 1; i <= n; i ++)
			ans2 += b[i];
	}
	//cout << "! " << ans2 << endl;
	for(int i = 1; i <= n; i ++)
	{
		book[q[i].num] ++;
	}
	flag = 0;
	for(int i = 1; i <= n; i ++)
	{
		if(book[i] > 1)
		{
			flag = 1;
			break;
		}
	}
	if(flag)
	{
		for(int i = 1; i <= n; i ++)
			ans3 += q[i].val;
	}
	else
	{
		ans3 = 1e18;
		LL sum = 0;
		for(int i = 1; i <= n; i ++)
			sum += q[i].val;
		//LL temp = ans3;
		for(int i = 1; i <= n; i ++)
		{
			LL t_ans = sum;
