	int64_t ans = 0;
	for (int i = 0;i < N;++ i) use[i] = false;
	for (int i = 0;i < N;++ i) ans += edge[i].first;

	for (int i = 0;i < N;++ i) {
		if (use[edge[i].second.second]) {
			cout << ans;
			return 0;
		}
		use[edge[i].second.second] = true;
	}
	for (int i = 0;i < N - 1;++ i) {
		if (edge[i].second.first != edge[i + 1].second.first) {
			if (edge[N - 1].second.second != edge[N].second.second) ans += edge[N].first - edge[N - 1].first;
			else ans += min(edge[N].first - edge[N - 2].first, edge[N + 1].first - edge[N - 1].first);
			break;
		}
	}
