    asum += a[i];
    bsum += b[i];
  }
  vector<PL> pool(n);
  REP(i, 0, n) {
    ll x = a[i], y = b[i];
    if (x > y) swap(x, y);
    pool[i] = PL(x, y);
  }
  sort(pool.begin(), pool.end());
  vector<PL> det(n);
  REP(i, 0, n) det[i] = PL(pool[i].second, i);
  sort(det.begin(), det.end());
  ll mi = min(asum, bsum);
  ll tmp = 0;
  REP(i, 0, n) {
    tmp += pool[i].first;
  }
