			if (max(vec[n + 1].id - vec[n - 1].id, vec[n - 1].id - vec[n + 1].id) != n) ans = min(ans, sum + vec[n + 1].val - vec[n - 1].val);
		}
	}

	write(ans), putchar('\n');
	return 0;
}

