auto solve(ll n, const V<PAIR>& v) {

	set<pair<PAIR, PAIR>> s;
	REP(i, n) {
		s.emplace(PAIR{v[i].first,v[i].second}, PAIR{i,1});
		s.emplace(PAIR{v[i].second,v[i].first}, PAIR{i,2});
	}

	VL state(n); ll cnt = 0;
	ll ans = 0;
	REPC(p, s) {
		state[p.second.first] += p.second.second;
		ans += p.first.first;
		++cnt;
		if (cnt == n) { break; }
	}

	REPC(k, state)if (!(k ^ 3)) {
		return ans;
	}

	V<PAIR> l; l.reserve(n);
	V<PAIR> r; r.reserve(n);
	REP(i, n) {
		((!(state[i] ^ 1)) ? l : r).emplace_back(v[i]);
	}
	if (l.empty() || r.empty()) { return ans; }
	PAIR l1, l2, r1, r2;
	{
		std::sort(ALL(l), [](cauto a, cauto b) {
			if (a.first == b.first) { return a.second > b.second; }
			return a.first > b.first;
		});
		l1 = l[0];
		if (l.size() > 1) {
			l1.second = 1e10;
			FOR(i, 1, l.size()) { chmin(l1.second, l[i].second); }
		}
	}
	{
		std::sort(ALL(l), [](cauto a, cauto b) {
			if (a.second == b.second) { return a.first < b.first; }
			return a.second < b.second;
		});
		l2 = l[0];
		if (l.size() > 1) {
			l2.first = -1;
			FOR(i, 1, l.size()) { chmax(l2.first, l[i].first); }
		}
	}
	{
		std::sort(ALL(r), [](cauto a, cauto b) {
			if (a.first == b.first) { return a.second < b.second;; }
			return a.first < b.first;

		});
		r1 = r[0];
		if (r.size() > 1) {
			r1.second = -1;
			FOR(i, 1, r.size()) { chmax(r1.second, r[i].second); }
		}
	}
	{
		std::sort(ALL(r), [](cauto a, cauto b) {
			if (a.second == b.second) { return a.first > b.first; }
			return a.second > b.second;
		});
		r2 = r[0];
		if (r.size() > 1) {
			r2.first = 1e10;
			FOR(i, 1, r.size()) { chmin(r2.first, r[i].first); }
		}
	}
	ll tmp = ans;
	ans = 1e10;
	auto update = [&ans, &tmp](const PAIR& p1, const PAIR& p2) {
		chmin(ans, tmp - std::max(p1.first, p2.second) + std::min(p1.second, p2.first));
	};
	dump(tmp, l1, l2, r1, r2);
	update(l1, r1);
	update(l2, r1);
	update(l1, r2);
	update(l2, r2);
	return ans;
}

