	sort(c+1,c+cnt+1);
	for(int i=1;i<=n;i++)
		sum[i]=sum[i-1]+c[i];
	long long ans=min(suma,sumb);
	for(int i=1;i<=n;i++)
	{
		long long x=a[i],y=b[i];
		if(x>y) swap(x,y);
		if(lower_bound(c+1,c+cnt+1,x)-c<=n-2)
  		{
   			if(lower_bound(c+1,c+cnt+1,y)-c<=n-1) ans=min(ans,sum[n]);
   			else ans=min(ans,y+sum[n-1]);
  		}
  		else ans=min(ans,x+y+sum[n-2]);
	}
	printf("%lld",ans);
	return 0;
}

