		int mi=n,v=min(p[n].fi,p[n].se);
		For(i,n/2+1,n){
			int nv=min(p[i].fi,p[i].se);
			if (nv<v)
				v=nv,mi=i;
		}
		tot+=v;
		For(i,1,n/2)
			Q1.push(p[i]);
		For(i,n/2+1,n)
			if (i!=mi)
				Q2.push(p[i]);
	}
	else {
		For(i,1,n/2)
			Q1.push(p[i]);
		For(i,n/2+1,n)
			Q2.push(p[i]);
	}
	while (!Q1.empty()){
		ans=min(ans,tot);
		pii a=Q1.top(),b=Q2.top();
		Q1.pop(),Q2.pop();
		tot-=max(a.fi,a.se);
		tot+=min(b.fi,b.se);
	}
	cout<<ans<<endl;
	return 0;
}
