struct TEMP{int v,i;char c;bool vis;}p[MN*2+5],*mxa,*mxb;
void push(int v,int i,char c){
	static int pn=0; ++pn;
	p[pn].v=v; p[pn].i=i; p[pn].c=c;
}
void fnx(TEMP *ptr,char c){
	TEMP *tmp=ptr;
	ptr--;
	for(;ptr>&p[0];ptr--)
		if(ptr->c==c&&(!ptr->vis)) break;
	if(ptr==&p[0]){
		ptr=tmp;
	}
	ptr->vis=true;
}
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		static int a,b;
		scanf("%d%d",&a,&b);
		push(a,i,'a'),push(b,i,'b');
	}
	std::sort(p+1,p+1+2*n,[](TEMP a,TEMP b)->bool{return a.v<b.v;});
	for(mxa=&p[2*n];mxa->c!='a';mxa--);
	for(mxb=&p[2*n];mxb->c!='b';mxb--);
	for(int i=1;i<=2*n;i++){
		if(p[i].vis) continue;
		p[i].vis=true; ans+=p[i].v;
		if(p[i].c=='a'){
			if(p[i].i==mxb->i) fnx(mxb,'b');
			else{
				mxb->vis=true;
				do{--mxb;}while((mxb->c!='b'||mxb->vis)&&mxb!=&p[0]);
			}
		}
		if(p[i].c=='b'){
			if(p[i].i==mxa->i) fnx(mxa,'a');
			else{
				mxa->vis=true;
				do{--mxa;}while((mxa->c!='a'||mxa->vis)&&mxa!=&p[0]);
			}
		}
	}
	printf("%lld",ans);
}

