	n = read();
	for(rg int i = 1; i <= n; ++i) a[i] = read(), b[i] = read();
	for(rg int i = 1; i <= n; ++i) ans1 += a[i], ans2 += b[i];
	ans1 = std::min(ans1, ans2);
	for(rg int i = 1; i <= n; ++i) c[i * 2] = a[i], c[i * 2 - 1] = b[i];
