typedef long long llint;

int main(void) {
  ios_base::sync_with_stdio(false);

  int N;
  cin >> N;
  vector<int> A(N), B(N);
  vector<pair<int, int>> Ap(N), Bp(N);
  for (int i = 0; i < N; ++i) {
    cin >> A[i] >> B[i];
    Ap[i] = {A[i], i};
    Bp[i] = {B[i], i};
  }

  sort(Ap.begin(), Ap.end());
  sort(Bp.begin(), Bp.end());
  reverse(Bp.begin(), Bp.end());

  vector<int> p(N);
  for (int i = 0; i < N; ++i) {
    p[Ap[i].second] = Bp[i].second;
  }

  bool ok = false;
  bool have0 = false, have1 = false;
  llint ret = 0;
  vector<bool> bio(N, false);
  for (int i = 0; i < N; ++i) {
    ret += min(A[i], B[p[i]]);
    if (!bio[i]) {
      int x = i;
      bool i0 = false, i1 = false;
      while (!bio[x]) {
        int y = p[x];
        if (A[x] <= B[y]) i0 = true;
        if (A[x] >= B[y]) i1 = true;
        bio[x] = true;
        x = y;
      }

      if (i0 && i1) ok = true;
      have0 |= i0;
      have1 |= i1;
    }
  }

  if (have0 && have1 && !ok) {
    llint best = 1e18;
    for (int i = 0; i < N; ++i) {
      if (Ap[i].first < Bp[i].first) {
        for (int j = N - 1; j >= 0; --j) {
          if (Ap[j].first > Bp[j].first) {
            llint g = 0;
            g -= min(Ap[i].first, Bp[i].first);
            g -= min(Ap[j].first, Bp[j].first);
            g += min(Ap[i].first, Bp[j].first);
            g += min(Ap[j].first, Bp[i].first);
            best = min(best, g);
          } else {
            break;
          }
        }
      } else {
        break;
      }
    }

    ret += best;
  }
  cout << ret << "\n";
  return 0;
}

