int N,A[100010] = {0},B[100010] = {0};
ll a,b;
vector<PP> v;
int main(){
	cin >> N;
	priority_queue<pair<ll,int>> Qa,Qb;
	for(int i=0;i<N;i++){
		cin >> a >> b;
		v.push_back({a,{0,i}});
		v.push_back({b,{1,i}});
		Qa.push({a,i});
		Qb.push({b,i});
	}
	sort(v.begin(),v.end());
	ll ans = 0;
	int count = 0;
	for(int i=0;i<2*N;i++){
		PP t = v[i];
		P id = t.second;
		if(id.first==0 && A[id.second]==1) continue;
		if(id.first==1 && B[id.second]==1) continue;
		if(count==N-1){
			ans += v[i].first;
			break;
		}
		if(id.first==0){
			pair<ll,int> p = Qb.top(),q;
			Qb.pop();
			if(p.second==id.second){
				q = p;
				p = Qb.top();
				Qb.pop();
				Qb.push(q);
			}
			ans += t.first;
			A[id.second] = 1;
			B[p.second] = 1;
		}else{
			pair<ll,int> p = Qa.top(),q;
			Qa.pop();
			if(p.second==id.second){
				q = p;
				p = Qa.top();
				Qa.pop();
				Qa.push(q);
			}
			ans += t.first;
			B[id.second] = 1;
			A[p.second] = 1;
		}
		count++;
	}
