int main() {
	int n; scanf("%d", &n);
	i64 A = 0, B = 0, tmp = 0;
	std::vector<i64> a(n), b(n);
	std::vector<std::pair<i64, int>> X, Y;
	for(int i = 0; i < n; i++) {
		scanf("%lld%lld", &a[i], &b[i]);

		X.push_back({a[i] + b[i] - std::min(a[i], b[i]), i});
		Y.push_back({-std::min(a[i], b[i]), i});

		A += a[i];
		B += b[i];
		tmp += std::min(a[i], b[i]);
	}
	sort(begin(X), end(X)); sort(begin(Y), end(Y));

	int x = 0, y = 0;
