  }

  //caution : position "i" must be 1-indexed
  void add(int i, const T x){
    while(i <= N){
      tree[i] += x;
      i += i & -i;
    }
  }

  //update node i to zero
  void to_zero(const int i){
    T val = get_at(i);
    add(i, -val);
  }

  //get sums [0,i]
  T get_sum(int i){
    T ret=0;
    while(i>0){
      ret += tree[i];
      i -= i & -i;
    }
    return ret;
  }

  //get sums [from,to]
  T get_sums_range(const int from, const int to){
    return get_sum(to) - get_sum(from-1);
  }

  //get at [i]
  T get_at(const int i){
    return get_sum(i) - get_sum(i-1);
  }

  int lower_bound(T val){
    if(val<=0) return 0;
    int x = 0;
    int k = 1;
    while((k<<1) <= N) k<<=1;

    for( ; k>0; k>>=1){
      if( x+k <= N && tree[x+k] < val ){
        val -= tree[x+k];
        x += k;
      }
    }
    return x+1;
  }

  void print(){
    for(int i=0; i<=N; i++){
      cerr << tree[i] << " ";
    }
    cerr << endl;
  }
};

void do_shuffle(vector<long long>& a, vector<long long>& b){
  vector<int> ord(a.size());
  iota(ord.begin(), ord.end(), 0);
  shuffle(ord.begin(), ord.end(), mt);

  auto a_ = a;
  auto b_ = b;
  for(int i=0; i<a.size(); i++){
    a[i] = a_[ord[i]];
    b[i] = b_[ord[i]];
  }
}

long long solve(int n, vector<long long>& a, vector<long long>& b){
  do_shuffle(a,b);

  using tt = tuple<long long, int, int, int>;
  vector<tt> c;
  for(int i=0; i<n; i++){
    c.emplace_back(a[i], mt(), i, 1);
    c.emplace_back(b[i], mt(), i, 2);
  }
  sort(c.begin(), c.end());

  long long ans = accumulate(a.begin(), a.end(), 0ll);
  ans = min(ans, accumulate(b.begin(), b.end(), 0ll));

  vector<int> min_idx(n, n*10);
  vector<long long> val(n, 0);
  for(int i=0; i<(int)c.size(); i++){
    min_idx[ get<2>(c[i]) ] = min(min_idx[ get<2>(c[i]) ], i);
  }
  vector<int> flag(n, 0);
  vector<int> cnt(4, 0);
  vector<long long> sum(4, 0);
  cnt[0] = n;
  sum[0] = 0;

  BinaryIndexedTree_1_indexed<long long> acc(c.size()+20);
  BinaryIndexedTree_1_indexed<int> pop_count(c.size()+20);

  for(int j=0; j<(int)c.size(); j++){
    long long w; int i, k;
    tie(w, ignore, i, k) = c[j];

    cnt[ flag[i] ]--;
    sum[ flag[i] ] -= val[i];
    flag[i] |= k;
    val[i] += w;
    cnt[ flag[i] ]++;
    sum[ flag[i] ] += val[i];
    if(flag[i] == 1 || flag[i] == 2){
      acc.add(j+1, w);
      pop_count.add(j+1, 1);
    }else if(flag[i] == 0b11){
      acc.add(min_idx[i]+1, -(val[i]-w) );
      pop_count.add(min_idx[i]+1, -1);
    }

    if( cnt[0b11] >= cnt[0b00] && cnt[0b11] ){
      long long tmp = sum[0b11];
      int must_pop = cnt[0b11] - cnt[0b00];

      if( cnt[1] + cnt[2] >= must_pop ){
        int lb = pop_count.lower_bound(cnt[1] + cnt[2] - must_pop);
        tmp += acc.get_sum(lb);

        ans = min(ans, tmp);
      }
    }

  }

  return ans;
}

int main(){
  int n;
  cin >> n;

  vector<long long> a(n), b(n);
  for(int i=0; i<n; i++){
    cin >> a[i], b[i];
  }

  long long ans = 1ll<<58;
  for(int k=0; k<10; k++){
    ans = min(ans, solve(n,a,b));
  }

  println(ans);
  return 0;
}

