using namespace std;
typedef long long ll;

struct V {
  ll a, b;
  V(ll a, ll b) : a(a), b(b) {}
  V() {}
};

V vs[100000+10];

struct P {
  ll v;
  int i;
  bool isA;
};
bool operator<(const P& p1, const P& p2) {
  if(p1.v != p2.v) return p1.v < p2.v;
  return p1.i < p2.i;
}

bool st[100000+10][2];

int main(void) {
  int n;
  scanf("%d", &n);
  vector<P> ps;
  REP(i, n) {
    scanf("%lld%lld", &vs[i].a, &vs[i].b);
    ps.push_back((P){vs[i].a, i, true});
    ps.push_back((P){vs[i].b, i, false});
  }
  sort(ps.begin(), ps.end());
  ll res = 0;
  REP(i, n) {
    P p = ps[i];
    res += ps[i].v;
    st[p.i][p.isA ? 0 : 1] = true;
  }
  int nA = 0;
  int nB = 0;
  REP(i, n) {
    if(st[i][0] && !st[i][1]) {
      ++nA;
    } else if(!st[i][0] && st[i][1]) {
      ++nB;
    }
  }

  // cerr << ">" << res << endl;
  if(nA == 0 || nB == 0 || nA + nB < n) {
    // do nothing
  } else {
    // 今使ってる中で一番でかいやつのindexを取る
    int idx = -1;
    int idx2 = -1;
    int maxi = -1;
    REP(i, n) {
      REP(j, 2) {
        if(st[i][j]) {
          int v = j==0 ? vs[i].a : vs[i].b;
          if(maxi < v) {
            maxi = v;
            idx = i;
            idx2 = j;
          }
        }
      }
    }
    // idxの箇所を捨てて他の使ってない最小を採用
    ll res1 = res;
    {
      res1 -= idx2==0 ? vs[idx].a : vs[idx].b;
      int mini = 2e9;
      REP(i, n) {
        if(i != idx) {
          REP(j, 2) {
            if(!st[i][j]) {
              int v = j==0 ? vs[i].a : vs[i].b;
              if(mini > v) {
                mini = v;
              }
            }
          }
        }
      }
      res1 += mini;
    }
    // cerr << ">> " << res1 << endl;
    // idxの箇所を両取りして他の箇所でmaxを捨てる
    ll res2 = res;
    {
      res2 += idx2==0 ? vs[idx].b : vs[idx].a;
      int maxi = -1;
      REP(i, n) {
        if(i != idx) {
          REP(j, 2) {
            if(st[i][j]) {
              int v = j==0 ? vs[i].a : vs[i].b;
              if(maxi < v) {
                maxi = v;
              }
            }
          }
        }
      }
      res2 -= maxi;
    }
    res = min(res1, res2);
    {
      // AまたはBに統一する
      ll sumA = 0;
      ll sumB = 0;
      REP(i, n) {
        sumA += vs[i].a;
        sumB += vs[i].b;
      }
      res = min(min(res, sumA), sumB);
    }
  }

  printf("%lld\n", res);

  return 0;
}

