    to[i].second = i;
    from[i].second = i;
  }
  sort(to.begin(),to.end());
  sort(from.begin(),from.end());

  long long ans = 0;
  deque<long long> mismatch;
  int toCnt = 0, fromCnt = 0;
  while(toCnt != n || fromCnt != n){
    if(mismatch.empty() == false){
      ans += min(to[toCnt].first , mismatch.front());
      mismatch.pop_front();
      toCnt ++;
      continue;
    }
    if(to[toCnt].second == from[n-fromCnt-1].second){
      mismatch.push_back(from[n-1-fromCnt].first);
      fromCnt++;
      ans += min(to[toCnt].first, from[n-fromCnt-1].first);
      toCnt++;
      fromCnt++;
    }else{
      ans += min(to[toCnt].first , from[n-fromCnt-1].first);
      toCnt ++;
      fromCnt ++;
    }
    //cout << ans << " toCnt " << toCnt << " fromCnt " << fromCnt << endl;

  }
  cout << ans << endl;
  return 0;
}

