struct Problem {

	void Solve() {
		UL N; cin >> N;
		vector<pair<ULL, UL>> V(N * 2);
		vector<pair<ULL, ULL>> V2(N);
		ULL ansL = 0, ansR = 0;
		rep(i, N) {
			cin >> V[i * 2].first >> V[i * 2 + 1].first;
			V2[i].first = V[i * 2].first;
			V2[i].second = V[i * 2 + 1].first;
			ansL += V[i * 2].first;
			ansR += V[i * 2 + 1].first;
		}
		rep(i, N) { V[i * 2].second = V[i * 2 + 1].second = i; }
		sort(V.begin(), V.end());
		vector<UL> F(N);
		ULL ans = 0;
		rep(i, N) {
			ans += V[i].first;
			F[V[i].second]++;
		}
		rep(i, N) if (V2[i].first > V2[i].second) swap(V2[i].first, V2[i].second);
		bool ok = false;
		rep(i, N) if (F[i] == 2) ok = true;
		if (!ok) {
			ULL tmp = 10000000000;
			sort(V2.begin(), V2.end());
			rep(i, N - 1) {
				tmp = min(tmp, V2[i].second - V2[N - 1].first);
			}
			tmp = min(tmp, V2[N - 1].second - V2[N - 2].first);
			ans += tmp;
		}
		ans = min(ans, min(ansL, ansR));
		cout << ans << endl;
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
