int main(){
  ll n;cin >> n;
  vector<vector<ll>> dat(n, vector<ll>(2, 0));
  for(int i=0;i<n;i++) {
    scanf("%lld %lld", &dat[i][0], &dat[i][1]);
  }
  vector<ll> x(2*n), X(2*n);
  for(int i=0;i<n;i++) x[i] = dat[i][0], x[i+n] = dat[i][1];
  sort(x.begin(), x.end());
  for(int i=0;i<n;i++) X[i] = (i==0?0:X[i-1]) + x[i];

  bool f = false;
  for(int i=0;i<n;i++){
    ll p = dat[i][0], q = dat[i][1];
    ll idx1 = lower_bound(x.begin(), x.end(), p) - x.begin();
    ll idx2 = lower_bound(x.begin(), x.end(), q) - x.begin();
    if(idx1>=n||idx2>=n) continue;
    if(idx1==n-1&&idx2==n-1) continue;
    f = true;
  }
  if(f){
    ll ans = 0;
    for(int i=0;i<n;i++) ans += x[i];
    std::cout << ans << '\n';
    return 0;
  }

  ll ans = 1000000000000000000;

  for(int i=0;i<n;i++){
    ll tmp;
    ll p = dat[i][0], q = dat[i][1];
    ll idx1 = lower_bound(x.begin(), x.end(), p) - x.begin();
    ll idx2 = lower_bound(x.begin(), x.end(), q) - x.begin();

    if(idx1==n-1||idx2==n-1){
      tmp = (n==2?0:X[n-3]) + p + q;
    }else if(idx1<n-1){
      tmp = X[n-2] + q;
    }else if(idx2<n-1){
      tmp =  X[n-2] + p;
    }else{
      tmp = (n==2?0:X[n-3]) + p + q;
    }
    ans = min(ans, tmp);
  }
  std::cout << ans << '\n';
  return 0;
}

