#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<ll, ll>;

int main() {
    int n; cin >> n;
    vector<int> a(n * 2), b(n * 2);
    priority_queue<pii, vector<pii>, greater<>> que1, que1t;
    priority_queue<pii> que2, que2t;
    for(int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
        que1.emplace(a[i], i); que2t.emplace(a[i], i);
        que2.emplace(b[i], i); que1t.emplace(b[i], i);
    }
    auto at = a, bt = b;
    ll tans = 0;
    for(int i = 0; i < 2; ++i) {
        int iter = n;
        ll ans = 0;
        vector<bool> used(2 * n);
        while(iter < 2 * n - 1) {
            auto p = que1.top(); que1.pop();
            if(used[p.second]) continue;
            used[p.second] = true;
            if(que2.top().second == p.second) {
                auto tp = que2.top(); que2.pop();
                auto p2 = que2.top(); que2.pop();
                while(used[p2.second]) {
                    p2 = que2.top(); que2.pop();
                }
                a[iter] = a[p2.second], b[iter] = b[p.second];
                que2.push(tp);
                used[p.second] = used[p2.second] = true;
                que1.emplace(a[iter], iter);
                que2.emplace(b[iter], iter);
                ans += min(p.first, p2.first);
                iter++;
            } else {
                auto p2 = que2.top(); que2.pop();
                while(used[p2.second]) {
                    p2 = que2.top(); que2.pop();
                }
                if(p2.second == p.second) {
                    auto tp = p2;
                    p2 = que2.top(); que2.pop();
                    while(used[p2.second]) {
                        p2 = que2.top(); que2.pop();
                    }
                    ans += min(p.first, p2.first);
                    a[iter] = a[p2.second], b[iter] = b[p.second];
                    que2.push(tp);
                    used[p.second] = used[p2.second] = true;
                    que1.emplace(a[iter], iter);
                    que2.emplace(b[iter], iter);
                    iter++;
                } else {
                    ans += min(p.first, p2.first);
                    a[iter] = a[p2.second], b[iter] = b[p.second];
                    used[p.second] = used[p2.second] = true;
                    que1.emplace(a[iter], iter);
                    que2.emplace(b[iter], iter);
                    iter++;
                }
            }
        }
        while(used[que1.top().second]) que1.pop();
        while(used[que2.top().second]) que2.pop();
        ans += min(que1.top().first, que2.top().first);
        tans = max(tans, ans);
        a = move(bt), b = move(at);
        que1 = move(que1t);
        que2 = move(que2t);
    }
    cout << tans << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

typedef pair<ll, ll> pii;
typedef pair<pii, int> piii;
set<piii> abi, bai;

int main() {
    int N;
    scanf("%d", &N);
    for(int i = 1; i <= N; ++i) {
        ll A, B;
        scanf("%lld %lld", &A, &B);
        abi.insert(piii(pii(A, B), i));
        bai.insert(piii(pii(B, A), i));
    }
    ll ans = 0;
    for(int i = 1; i < N; ++i) {
        if((*abi.begin()).first.first < (*bai.begin()).first.first) {
            piii t1 = *abi.begin();
            ll A1 = t1.first.first, B1 = t1.first.second;int i1 = t1.second;
            abi.erase(piii(pii(A1, B1), i1));
            bai.erase(piii(pii(B1, A1), i1));
            piii t2 = *bai.rbegin();
            ll A2 = t2.first.second, B2 = t2.first.first;int i2 = t2.second;
            abi.erase(piii(pii(A2, B2), i2));
            bai.erase(piii(pii(B2, A2), i2));
            ans += A1;
            abi.insert(piii(pii(A2, B1), i1));
            bai.insert(piii(pii(B1, A2), i1));
        }
        else {
            piii t1 = *bai.begin();
            ll A1 = t1.first.second, B1 = t1.first.first;int i1 = t1.second;
            abi.erase(piii(pii(A1, B1), i1));
            bai.erase(piii(pii(B1, A1), i1));
            piii t2 = *abi.rbegin();
            ll A2 = t2.first.first, B2 = t2.first.second;int i2 = t2.second;
            abi.erase(piii(pii(A2, B2), i2));
            bai.erase(piii(pii(B2, A2), i2));
            ans += B1;
            abi.insert(piii(pii(A1, B2), i1));
            bai.insert(piii(pii(B2, A1), i1));
        }
    }
    piii tmp = *abi.begin();
    ans += min(tmp.first.first, tmp.first.second);
    printf("%lld\n", ans);
    return 0;
}

