using namespace std;

typedef long long ll;

const int MAXN = (int)1e5 + 5;

pair<int, int> p[MAXN * 2];

pair<int, int> arr[MAXN];

int a[MAXN], b[MAXN];

ll ans;	

int n;

void solve() {
	scanf("%d", &n);

	for (int i = 1; i <= n; ++i) {
		scanf("%d %d", &a[i], &b[i]);
	}

	for (int i = 1; i <= n; ++i) {
		p[i] = mp(a[i], i);
		p[n + i] = mp(b[i], n + i);
	}	

	sort(p + 1, p + (2 * n) + 1);

	for (int i = 1; i <= (2 * n); ++i) {
		if (p[i].se > n) {
			arr[p[i].se - n].se = i;
		}
		else {
			arr[p[i].se].fi = i;
		}
	}

	ans = (ll)1e18;

	{
		ll s1 = 0, s2 = 0;

		for (int i = 1; i <= n; ++i) {
			s1 += a[i];
			s2 += b[i];
		}

		ans = min(ans, s1);
		ans = min(ans, s2);
	}

	ll S = 0;

	for (int i = 1; i <= n - 2; ++i) {
		S += p[i].fi;
	}

	for (int i = 1; i <= n; ++i) {
		if (arr[i].fi > n - 2 && arr[i].se > n - 2) {
			ans = min(ans, S + a[i] + b[i]);
			continue;
		}

		if (arr[i].fi <= n - 2 && arr[i].se <= n - 2) {
			ans = min(ans, S + p[n - 1].fi + p[n].fi);
			continue;
		}        

		if (arr[i].fi <= n - 2) {
			if (arr[i].se == n - 1) {
				ans = min(ans, S + p[n].fi + b[i]);
			}
			else {
				ans = min(ans, S + p[n - 1].fi + b[i]);
			}
		}
		else {
			if (arr[i].fi == n - 1) {
				ans = min(ans, S + p[n].fi + a[i]);
			}
			else {
				ans = min(ans, S + p[n - 1].fi + a[i]);
			}
		}
    }

	printf("%lld\n", ans);
}

int main() {
    int tt = 1;

    while (tt--) {
        solve();
    }

    return 0;
}

