  }
  for (int i = 1; i <= n * 2; ++i) {
    que.push({ A[i], i }), vis[i] = 1;
    if (que.size() > n)
      vis[que.top().second] = 0, que.pop();
  }
  for (int i = 1; i <= n; ++i) {
    B[i] = que.top().first;
    C[i] = que.top().second;
    sum += B[i], que.pop();
  }
  ans = std::min(tmp1, tmp2);
  for (int i = 1; i <= n; ++i) {
    long long tmp = sum;
