      tmp += A[i] + A[n + i] - B[1] - B[2];
    else if (!vis[i])
      tmp += A[i] - (C[i] == i ? B[2] : B[1]);
    else if (!vis[n + i])
      tmp += A[n + i] - (C[i] == n + i ? B[2] : B[1]);
    ans = std::min(ans, tmp);
