deque<pll> parse(vector<pll> v) {
    deque<pll> dq;
    for (auto p : v)dq.push_back(p);
    return dq;
}

ll solve_impl(deque<pll> dq, const ll threth) {
    ll score = 0;
    pll base = dq.front(); dq.pop_front();
    while (!dq.empty()) {
        pll next = [&]() {
            if (threth < base.second) {
                auto next = dq.front();
                dq.pop_front();
                return next;
            }
            else {
                auto next = dq.back();
                dq.pop_back();
                return next;
            }
        }();
        score += min(base.second, next.first);
        base.second = next.second;
    }
    score += min(base.first, base.second);
    return score;
}

ll solve(const vector<pll>& ab) {
    const auto dq = parse(ab);
    ll out = 0, safe = 1e9 + 7;
    while (abs(safe - out) > 2) {
        ll midl = (out * 2 + safe) / 3;
        ll midr = (out + safe * 2) / 3;
        ll vl = solve_impl(dq, midl);
        ll vr = solve_impl(dq, midr);
        if (vl < vr)safe = midr;
        else out = midl;
    }
    ll res = INFL;
    REP(i, out, safe + 1)res = min(res, solve_impl(dq, i));
    return res;
}

