		scanf("%d%d", a + i, a + n + i),
		q.insert(std::pair<int, int>(a[i], e[i] = i)),
		p.insert(std::pair<int, int>(a[i + n], e[i + n] = i + n));
	std::sort(e + 1, e + n * 2 + 1, [](int x, int y) {
		return a[x] < a[y];
	});
	int m = 0;
	for (int i = 1, x, y; m < n - 2; ++i) {
		if (del[e[i]]) continue;
		x = e[i];
		auto j = x <= n ? p.end() : q.end();
		if (((--j)->second - x) % n == 0) --j;
		y = j->second;
		if (x > y) std::swap(x, y);
		ans += std::min(a[x], a[y]);
		del[x] = del[y] = 1;
		q.erase(std::pair<int, int>(a[x], x));
		p.erase(std::pair<int, int>(a[y], y));
		++m;
	}
	auto x1 = *q.begin();
	q.erase(q.begin());
	auto x2 = *q.begin();
	auto y1 = *p.begin();
	p.erase(p.begin());
	auto y2 = *p.begin();
