using namespace std;

using Pair = pair<int, int>;

struct Set {
    set<Pair> sa, sb;

    void Add(int a, int b, int i) {
        sa.emplace(a, i);
        sb.emplace(b, i);
    }
    void Remove(int a, int b, int i) {
        sa.erase(sa.find({a, i}));
        sb.erase(sb.find({b, i}));
    }

    void get(set<Pair>& s1, set<Pair>& s2, vector<pair<Pair, Pair>>& to) {
        auto it1 = s1.begin(), it2 = prev(s2.end());
        if (it1->second == it2->second) {
            to.emplace_back(*next(it1), *it2);
            to.emplace_back(*it1, *prev(it2));
        } else {
            to.emplace_back(*it1, *it2);
        }
    }

    Pair Get() {
        assert(sa.size() >= 2);

        vector<pair<Pair, Pair>> to;
        get(sa, sb, to); 
        for (auto& p : to) swap(p.first, p.second);
        get(sb, sa, to);
        for (auto& p : to) swap(p.first, p.second);

        pair<Pair, Pair> choose;
        int best = -1;

        for (auto p : to) {
            int now = abs(p.second.first - p.first.first);
            if (now > best) {
                best = now;
                choose = p;
            }
        }
        // cerr << "NOW: " << best << endl;
        return {choose.first.second, choose.second.second};
    }
};

int main() {
    int n; cin >> n;

    Set s;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
        s.Add(a[i], b[i], i);
    }

    long long total = 0;

    auto couple = [&](int a, int b) {
        total += min(a, b);
        // cerr << "COUPLED: " << a << ' ' << b << endl;

    };

    for (int i = 1; i < n; ++i) {
        int i1, i2; tie(i1, i2) = s.Get();
        s.Remove(a[i1], b[i1], i1); 
        s.Remove(a[i2], b[i2], i2);

        couple(a[i1], b[i2]);

        int now = a.size();
        a.push_back(a[i2]);
        b.push_back(b[i1]);
        s.Add(a[now], b[now], now);
    }

    couple(a.back(), b.back());
    cout << total << endl;
    return 0;
}

