const ll MOD=1000000007LL;

ll ADD(ll x, ll y) { return (x+y) % MOD; }
ll SUB(ll x, ll y) { return (x-y+MOD) % MOD; }
ll MUL(ll x, ll y) { return x*y % MOD; }
ll POW(ll x, ll e) { ll v=1; for(; e; x=MUL(x,x), e>>=1) if (e&1) v = MUL(v,x); return v; }
ll DIV(ll x, ll y) { /*assert(y%MOD!=0);*/ return MUL(x, POW(y, MOD-2)); }

ll solve(int N, vi& a, vi& b) {
	vector<pair<int,ii>> ab(N*2);
	rep(i,N) ab[i] = cons(a[i], ii('a',i));
	rep(i,N) ab[N+i] = cons(b[i], ii('b',i));
	sort(ALL(ab));
	ll ans = 0;
	vi usage(N, 0);
	rep(i,N){
		int val = ab[i].first, side = ab[i].second.first, ix = ab[i].second.second;
		ans += val;
		if (side == 'a') usage[ix] |= 1;
		else usage[ix] |= 2;
	}

	vi types(4, 0);
	rep(i,N){
		types[usage[i]]++;
	}
	if (types[1] == N || types[2] == N) return ans;
	assert(types[0] == types[3]);
	if (types[3] > 0) return ans;
	ll best = LLONG_MAX;
	rep(w,N){
		int inN_val = min(a[w], b[w]);
		int next_val = (ab[N].second.second == w) ? ab[N+1].first : ab[N].first;
		best = min(best, ans - inN_val + next_val);
	}
	return best;
}

int main() {
    int N; scanf("%d", &N);
    vi a(N), b(N);
    rep(i,N) {
        scanf("%d%d", &a[i], &b[i]);
    }
    cout << solve(N,a,b) << endl;
    return 0;
}

