int main() {
  int N;
  while (cin >> N) {
    vector<ll> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i] >> B[i];
    vector<P> C;
    for (int i = 0; i < N; i++) {
      C.emplace_back(A[i], 2 * i + 0);
      C.emplace_back(B[i], 2 * i + 1);
    }
    sort(C.begin(), C.end());
    vector<int> Q(2 * N);
    for (int i = 0; i < 2 * N; i++) Q[C[i].snd] = i;
    ll res = min(accumulate(A.begin(), A.end(), 0ll),
                 accumulate(B.begin(), B.end(), 0ll));
    ll sum = 0;
    for (int i = 0; i < N; i++) sum += C[i].fst;
    for (int i = 0; i < N; i++) {
      int a = Q[2 * i + 0];
      int b = Q[2 * i + 1];
      if (a > b) swap(a, b);
      if (N <= a) {
        res = min(res, sum);
      } else if (N <= b) {
        res = min(res, sum - C[a].fst + (b == N ? C[N + 1].fst : C[N].fst));
      } else {
        res = min(res, sum - C[a].fst - C[b].fst + C[N].fst + C[N + 1].fst);
      }
    }
    cout << res << endl;
  }
  return 0;
}

