void rob(vector<PII> v1, vector<PII> v2) {
	set<int> AbezB, BbezA;
	lint prefA = 0, prefB = 0;
	FOR(i,0,n) prefB += v2[i].st;
	FOR(i,0,n) {
		prefA += v1[i].st;
		prefB -= v2[n-1-i].st;
		if (v1[i].nd != v2[n-1-i].nd)	{
			if (BbezA.find(v1[i].nd) == BbezA.end()) {
				AbezB.insert(v1[i].nd);
			} else {
				BbezA.erase(BbezA.find(v1[i].nd));
			}

			if (AbezB.find(v2[n-1-i].nd) == AbezB.end()) {
				BbezA.insert(v2[n-1-i].nd);
			} else {
				AbezB.erase(AbezB.find(v2[n-1-i].nd));
			}
		}
		if (!AbezB.empty()) ans = min(ans, prefA+prefB);
	}
}

