    for (int i = 0; i < n; i++) {
        std::cin >> a[i] >> b[i];
        ss.emplace(a[i], true, i);
        ss.emplace(b[i], false, i);
    }

    std::set<int> nums;
    std::deque<std::tuple<long long, bool, long long>> q;
    while (q.size() < n) {
        auto el = *ss.begin();
        q.push_back(el);
        nums.insert(std::get<2>(el));
        ss.erase(ss.begin());
    }

    if (nums.size() == n && 
        std::adjacent_find(q.begin(), q.end(), [](auto i, auto j) {
            return std::get<1>(i) ^ std::get<1>(j);
        }) != q.end()) {
        if (std::get<0>(q[n - 1]) == std::get<0>(q[n - 2])) {
            q.pop_back();
            q.push_back(*ss.begin());
        } else {
            auto ln = std::get<2>(q.back());
            auto it = ss.begin();
            while (std::get<2>(*it) == ln) it++;
            q.pop_back();
            q.push_back(*it);
        }
    }

    auto s = std::accumulate(q.begin(), q.end(), 0ll, [](auto init, auto& el) { return init + std::get<0>(el); });
