  for (int i = 0; i < n - 1; i++) {
    auto ita = aa.begin();
    A x = *ita;
    auto itb = bb.begin();
    A y = *itb;
    if (x.i == y.i) {
      itb++;
    }
    x = *ita;
    y = *itb;
    if (x.i != y.i) {
      aa.erase(ita);
