struct Node {
  int val;
  int id, type;
} node[maxn * 2];

int main(void) {
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d", A + i, B + i);
    ord1[i] = ord2[i] = i;
  }
  sort(ord1, ord1 + n, [](int i, int j) { return A[i] < A[j]; });
  sort(ord2, ord2 + n, [](int i, int j) { return B[i] < B[j]; });

  li case1 = accumulate(A, A + n, 0LL);
  li case2 = accumulate(B, B + n, 0LL);

  for (int i = 0; i < n; ++i) {
    node[2 * i] = {A[i], i, 0};
    node[2 * i + 1] = {B[i], i, 1};
  }
  sort(node, node + 2 * n, [](const Node &a, const Node &b) {
      return a.val < b.val;
    });
  li sum = 0;
  for (int i = 0; i < n; ++i) {
    sum += node[i].val;
    if (node[i].type == 0) {
      use1[node[i].id] = true;
    }
    if (node[i].type == 1) {
      use2[node[i].id] = true;
    }
  }

