struct QU {
  V<> par, rank, _size;

  QU(int n) : par(n), rank(n), _size(n, 1) { 
    iota(par.begin(), par.end(), 0);
  }

  int find(int a) {
    if (par[a] == a) return a;
    return par[a] = find(par[a]);
  }

  bool same(int a, int b) { return find(a) == find(b); }

  int size(int a) { return _size[find(a)]; }

  void unite(int a, int b) {
    a = find(a), b = find(b);
    if (a == b) return;
    if (rank[a] < rank[b]) {
      par[a] = b;
      _size[b] += _size[a];
    } else {
      par[b] = a;
      _size[a] += _size[b];
    }
    if (rank[a] == rank[b]) rank[a]++;
  }
};

int main() {
  cin.tie(NULL); ios::sync_with_stdio(false);
  int n; cin >> n;
  V<lint> a(n), b(n); for (int i = 0; i < n; i++) cin >> a[i] >> b[i];
  V< pair<lint, int> > ps(2 * n);
  for (int i = 0; i < n; i++) {
    ps[i] = {a[i], i};
    ps[i + n] = {b[i], i + n};
  }
  sort(ps.begin(), ps.end());
  QU qu(n);
  int p = 0;
  V<bool> used(2 * n);
  V< pair<lint, int> > ap(n), bp(n);
  for (int i = 0; i < n; i++) ap[i] = {a[i], i}, bp[i] = {b[i], i + n};
  sort(ap.rbegin(), ap.rend());
  sort(bp.rbegin(), bp.rend());
  int pa = 0, pb = 0;
  lint res = 0;
  for (int _ = 0; _ < n - 1; _++) {
    while (used[ps[p].second]) p++;
    while (used[ap[pa].second]) pa++;
    while (used[bp[pb].second]) pb++;
    res += ps[p].first;
    if (ps[p].second < n) {
      while (true) {
        if (!qu.same(ps[p].second, bp[pb].second - n)) break;
        pb++;
        while (used[bp[pb].second]) pb++;
      }
      qu.unite(ps[p].second, bp[pb].second - n);
      used[ps[p].second] = true;
      used[bp[pb].second] = true;
    } else {
      while (true) {
        if (!qu.same(ps[p].second - n, ap[pa].second)) break;
        pa++;
        while (used[ap[pa].second]) pa++;
      }
      qu.unite(ps[p].second - n, ap[pa].second);
      used[ps[p].second] = true;
      used[ap[pa].second] = true;
    }
  }
  lint mn = 2e9;
  for (int i = 0; i < 2 * n; i++) if (!used[ps[i].second]) mn = min(mn, ps[i].first);
  cout << res + mn << '\n';
}

