struct SNode
{
    int v, ind;
};
deque<SNode> fi, se;

int main()
{
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
    {
        scanf("%d%d", &a, &b);
        fi.push_back((SNode){a, i});
        se.push_back((SNode){b, i});
    }
    sort(fi.begin(), fi.end(), [](const SNode &a, const SNode &b) { return a.v < b.v; });
    sort(se.begin(), se.end(), [](const SNode &a, const SNode &b) { return a.v < b.v; });
    while (fi.size() > 2)
    {
        if (fi.front().v > se.front().v)
            fi.swap(se);
        if (se.back().ind == fi.front().ind)
            se[se.size() - 2] = se.back();
        ans += fi.front().v;
        fi.pop_front();
        se.pop_back();
    }
    if (fi.front().v > se.front().v)
        fi.swap(se);
    if (fi.back().ind == se.front().ind)
        ans += fi.front().v + min(fi.back().v, se.back().v);
    else
        ans += fi.front().v + min(fi.back().v, se.front().v);
    printf("%lld", ans);
}

