using namespace std;

typedef pair<int, int> ii;

const int N = 1e5 + 10;
const int MOD = 1e9 + 7;

int n, a[N], b[N];
int pb[N], pa[N];
int posa[N], posb[N];

vector<int> mem[N];
int gr[N];


void merge(int x, int y) {
    x = gr[pa[x]], y = gr[pa[y]];
    assert(x != y);
    if (mem[x].size() > mem[y].size()) swap(x,y);
    for(auto i : mem[x]){
        gr[i] = y;
        mem[y].push_back(i);
    }
}


int get(int x){
    return min(a[pa[x]], b[pb[x]]);
}
int cost(int x){
    swap(pb[x], pb[x + 1]);
    int ans = get(x) + get(x + 1);
    swap(pb[x], pb[x + 1]);
    ans -= get(x) + get(x + 1);
    return ans;
}
long long solve() {
    int ngr = 0;
    for(int st = 1; st <= n; st++) if (!gr[pa[st]]){
        ++ngr;
        int cur = st;
        while (!gr[pa[cur]]) {
            gr[pa[cur]] = ngr;
            mem[ngr].push_back(pa[cur]);
            cur = posa[pb[cur]];
        }
    }
    priority_queue<ii, vector<ii>, greater<ii>> pq;
    for(int i = 1; i < n; i++) {
        pq.push(ii(cost(i), i));
    }
    long long ans = 0;
    for(int i = 1; i <= n; i++) ans += get(i);
    while (ngr != 1){
        ii cur = pq.top(); pq.pop();
        int pos = cur.second;
        if (gr[pa[pos]] == gr[pa[pos + 1]]) continue;
        if (cur.first != cost(pos)) continue;
        ans += cost(pos);
        swap(pb[pos], pb[pos + 1]);
        merge(pos, pos + 1);
        for(int j = max(1, pos - 1); j <= min(pos + 1, n - 1); j++){
            pq.push(ii(cost(j), j));
        }
        ngr--;
    }
    return ans;
}
int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> n;
    for(int i = 1; i <= n; i++) cin >> a[i] >> b[i];

    long long ans = 1e18;
    for(int j = 0; j <= 1; j++){
            for(int i = 1; i <= n; i++) mem[i].clear();
            memset(gr, 0, sizeof(gr));
            for(int i = 1; i <= n; i++) pb[i] = pa[i] = i;
            sort(pa + 1, pa + n + 1, [](int x, int y){return a[x] < a[y];});
            sort(pb + 1, pb + n + 1, [](int x, int y){return b[x] > b[y];});
            for(int i = 1; i <= n; i++){
                posa[pa[i]] = i;
                posb[pb[i]] = i;
            }
            ans = min(ans,solve());
            for(int i = 1; i <= n; i++) swap(a[i], b[i]);
    }
    cout << ans;
}

