	FOR(i,N) {
		if(ok[i][0]) sum+=A[i],sok[0]++;
		if(ok[i][1]) sum+=B[i],sok[1]++;
		if(ok[i][0]&&ok[i][1]) both=1;
	}

	if(both==0 && sok[0] && sok[1]) {
