priority_queue<P>pq;
int p[100009];

int main(){
  int n;
  long long ans=0;
  cin>>n;
  for(int i=0;i<=n;i++)p[i]=i;
  for(int i=0;i<n;i++){
    long long s,t;
    cin>>s>>t;
    a.push_back(P(s,i));
    pq.push(P(t,i));
  }
  sort(a.begin(),a.end());
  for(int i=0;i<a.size();i++){
    long long cost=a[i].fi;
    long long idx=a[i].se;
    P now=pq.top();pq.pop();
    long long ncost=now.fi;
    long long nidx=now.se;
    if(i!=n-1&&same(idx,nidx)){
      now=pq.top();pq.pop();
      pq.push(P(ncost,nidx));
      ncost=now.fi;
      nidx=now.se;
    }
    //cout<<cost<<' '<<ncost<<endl;
    unite(idx,nidx);
    if(cost>ncost){
      ans+=ncost;
    }
    else ans+=cost;
    //cout<<pq.size()<<endl;
  }
  cout<<ans<<endl;
  return(0);
}

int find(int x){
  if(x==p[x])return x;
  else return p[x]=find(p[x]);
}

int same(int x,int y){
  if(find(x)==find(y))return 1;
  else return 0;
}

void unite(int x,int y){
  x=find(x);
  y=find(y);
  p[x]=y;
}

