    yx.erase(yx.find({y, x}));
}

vector<int> all;

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d%d", &a[i], &b[i]);
        add(a[i], b[i]);
        all.push_back(a[i]);
        all.push_back(b[i]);
    }
    sort(all.begin(), all.end());
    long long qqq = 0;
    for (int i = 0; i < n; ++i) {
        qqq += all[i];
    }
    long long ans = 0;
    while (xy.size() > 1) {
        pair<int, int> p1 = *xy.begin();
        pair<int, int> p2 = *yx.begin();
        int x, y, tp;
        if (p1.first < p2.first) {
            x = p1.first;
            y = p1.second;
            tp = 0;
        } else {
            x = p2.second;
            y = p2.first;
            tp = 1;
        }
        ans += min(x, y);
        //cout << x << " " << y << endl;
        del(x, y);
