	ll n;
	cin>>n;
	vector<ll> a(n);
	vector<ll> b(n);
	REP(i,n) cin>>a[i]>>b[i];
	ll ans=INF*INF;
	ll sum=0;
	REP(i,n) sum+=a[i];
	ans=min(ans,sum);
	sum=0;
	REP(i,n) sum+=b[i];
	ans=min(ans,sum);
	sum=0;
	vector<pair<P,ll>> c;
	REP(i,n) {
		ll aa=a[i],bb=b[i];
		c.pb(make_pair(P(aa,i),0));
		c.pb(make_pair(P(bb,i),1));
	}
	sort(ALL(c));
	vector<ll> det1(n,false);
	vector<ll> det2(n,false);
	REP(i,n) {
		if(c[i].second==0) {
			det1[c[i].first.second]=true;
		} else {
			det2[c[i].first.second]=true;
		}
		sum+=c[i].first.first;
	}
	vector<ll> t1; // 00
	vector<ll> t2; // 11
	vector<ll> t3; // 10
	vector<ll> t4; // 01
	REP(i,n) {
		if(det1[i]&&det2[i]) t2.pb(i);
		if(!det1[i]&&!det2[i]) t1.pb(i);
		if(!det1[i]&&det2[i]) t4.pb(i);
		if(det1[i]&&!det2[i]) t3.pb(i);
	}
	if(t1.size()!=0||t3.size()==n||t4.size()==n) {
		ans=min(ans,sum);
		cout<<ans<<endl;
	} else {
		vector<ll> tmp(n);
		REP(i,t3.size()) tmp[t3[i]]=3;
		REP(i,t4.size()) tmp[t4[i]]=4;
		ll mincost=INF*INF;
		REP(i,n) {
			if(tmp[i]==3) ans=min(ans,sum+mincost-a[i]);
			if(tmp[i]==4) ans=min(ans,sum+mincost-b[i]);

			if(tmp[i]==3) mincost=min(mincost,b[i]);
			if(tmp[i]==4) mincost=min(mincost,a[i]);
		}
		cout<<ans<<endl;
	}
	return 0;
}

