        ll a,b;
        cin >> a >> b;
        t.push_back({a,i,false});
        t.push_back({b,i,true});
    }

    sort(all(t), [](T x, T y){
        return x.value != y.value ? x.value < y.value : x.id < y.id;
    });
    vector<vector<bool>> low(n, {0,0});
