        if (!low[i][0] &&  low[i][1]) HL++;
        if ( low[i][0] && !low[i][1]) LH++;
        sum += t[i].value;
    }

    if (LL > 0 || LH == n || HL == n) {
        cout << sum << endl;
    } else if (t[n].id != t[n-1].id) {
        cout << sum - t[n-1].value + t[n].value << endl;
