	template<typename T>
	inline void write(T x)
	{
		static char buf[20];
		char *pos = buf;
		if (x < 0)
			putchar('-'), x = -x;
		do
			*pos++ = x % 10 + '0';
		while (x /= 10);
		while (pos > buf)
			putchar(*--pos);
	}
	typedef long long ll;
	typedef pair<int, int> pii;
	const int N = 1e5 + 10;
	const ll LINF = 0x3f3f3f3f3f3f3f3fLL;
	int n, A[N], B[N];
	pii buf[N << 1];
	ll ans;
	ll solve()
	{
		ll sum = 0;
		bool flag = false;
		static bool vis[N];
		memset(vis, 0, sizeof(bool[n + 1]));
		for (int i = 1; i <= n; i++)
		{
			sum += buf[i].first;
			if (vis[buf[i].second])
				flag = true;
			else
				vis[buf[i].second] = true;
		}
		if (!flag)
			return LINF;
		else
			return sum;
	}
	int work()
	{
		read(n);
		for (int i = 1; i <= n; i++)
			read(A[i]), read(B[i]), buf[i] = pii(A[i], i), ans += A[i];
		ll sum = 0;
		for (int i = 1; i <= n; i++)
			buf[i + n] = pii(B[i], i), sum += B[i];
