		ans = min(ans, solve());
		swap(buf[n], buf[n + 1]);
		ans = min(ans, solve());
		swap(buf[n], buf[n + 2]);
		ans = min(ans, solve());
		swap(buf[n], buf[n + 2]);
		swap(buf[n - 1], buf[n + 1]);
		ans = min(ans, solve());
		write(ans);
		return 0;
	}
}
