ll sum(const vector<long long> &A) {
	ll res = 0;
	for(auto a: A) {
		res += a;
	}
	return res;
}

void solve(long long N, vector<long long> A, vector<long long> B){
	ll res = min(sum(A), sum(B));

	vector<pair<ll, ll>> C;
	vector<bool> used(2 * N);
	for(int i = 0; i < N; ++i) {
		C.push_back(make_pair(A[i], i));
		C.push_back(make_pair(B[i], i + N));
	}
	sort(C.begin(), C.end());

	ll sum = 0;
	for(int i = 0; i < N; ++i) {
		sum += C[i].first;
		used[C[i].second] = true;
	}
	vector<tuple<ll, ll>> D;
	for(int i = 0; i < N; ++i) {
		ll s = A[i] + B[i];
		if(used[i]) {
			s -= A[i];
		}
		if(used[i + N]) {
			s -= B[i];
		}
		D.push_back(make_tuple(s, i));
	}
	sort(D.begin(), D.end());
	cerr << sum << endl;

	int k = 0, idx = N-1;
	for (int k = 0; 2 * (k + 1) <= N; ++k) {
		ll v = get<0>(D[k]);
		ll l = get<1>(D[k]);
		cerr << v << ",," << l << endl;
		sum += v; 
		int cnt = 0;
		if (used[l]) {
			++cnt;
		}
		if(used[l + N]) {
			++cnt;
		}
		used[l] = used[l + N] = false;
		cerr << sum << "," << cnt << endl;

		while(cnt < 2) {
			if(used[C[idx].second]) {
				cerr << sum << "," << idx << "," << C[idx].first << endl;
				sum -= C[idx].first;
				used[C[idx].second] = false;
				++cnt;
			}
			--idx;
		}

		res = min(res, sum);
	}
	cout << res << endl;
}

