//ここから編集する
class SegTree1 {
public:
    const int MAX_N = 1 << 17;
    int n;
    vector<ll> dat;
    const ll INITIAL_DAT = INFl;

    SegTree1(int n_) {
        init(n_);
    }

    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat = vector<ll>(2 * n);
        for (int i = 0; i < 2 * n - 1; ++i) dat[i] = INITIAL_DAT;
    }

    //どんなSegTreeを構築するか(デフォルトはRMQ)
    ll calc(ll vl, ll vr) {
        return min(vl, vr);
    }

    //k番目の値(0-indexed)をaに変更
    void update(int k, int a) {
        k += n - 1;
        dat[k] = a;
        //登りながら更新
        while (k > 0) {
            k = (k - 1) / 2;
//            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
            dat[k] = calc(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    //[a,b)の最小値を求める
    //kは接点の番号,l,rはその接点が[l,r)に対応づいていることを表す。
    //したがって、外からはquery(a,b,0,0,n)として呼ぶ。
    ll query(int a, int b, int k, int l, int r) {
        //[a,b)と[l,r)が交差しなければINITIAL_DAT
        if (r <= a || b <= l) return INITIAL_DAT;

        //[a,b)が[l,r)が交差しなければ、INT_MAX
        if (a <= l && r <= b) return dat[k];
        else {
            //そうでなければ、2つの子に対する処理,デフォルトは最小値
            ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return calc(vl, vr);
        }
    }

    //[a,b)の最小値を求める
    ll find(int a, int b) {
        return query(a, b, 0, 0, n);
    }
};


class SegTree2 {
public:
    const int MAX_N = 1 << 17;
    int n;
    vector<ll> dat;
    const ll INITIAL_DAT = 0;

    SegTree2(int n_) {
        init(n_);
    }

    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat = vector<ll>(2 * n);
        for (int i = 0; i < 2 * n - 1; ++i) dat[i] = INITIAL_DAT;
    }

    //どんなSegTreeを構築するか(デフォルトはRMQ)
    ll calc(ll vl, ll vr) {
        return max(vl, vr);
    }

    //k番目の値(0-indexed)をaに変更
    void update(int k, int a) {
        k += n - 1;
        dat[k] = a;
        //登りながら更新
        while (k > 0) {
            k = (k - 1) / 2;
//            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
            dat[k] = calc(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    //[a,b)の最小値を求める
    //kは接点の番号,l,rはその接点が[l,r)に対応づいていることを表す。
    //したがって、外からはquery(a,b,0,0,n)として呼ぶ。
    ll query(int a, int b, int k, int l, int r) {
        //[a,b)と[l,r)が交差しなければINITIAL_DAT
        if (r <= a || b <= l) return INITIAL_DAT;

        //[a,b)が[l,r)が交差しなければ、INT_MAX
        if (a <= l && r <= b) return dat[k];
        else {
            //そうでなければ、2つの子に対する処理,デフォルトは最小値
            ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return calc(vl, vr);
        }
    }

    //[a,b)の最小値を求める
    ll find(int a, int b) {
        return query(a, b, 0, 0, n);
    }
};


class Solve {
public:
    int N;
    vector<ll> A, B;

    void input() {
        cin >> N;
        rep(i, 0, N) {
            ll a, b;
            cin >> a >> b;
            A.push_back(a);
            B.push_back(b);
        }

    }

    void solve() {
        input();
//        priority_queue<pair<ll, pair<int, int>>> pq; //first value, second.first number, second.second A or B
        vector<pair<ll, pair<int, int>>> pq;

        for (int i = 0; i < N; ++i) {
            ll a = A[i];
            ll b = B[i];
            pq.emplace_back(a, make_pair(i, 1));
            pq.emplace_back(b, make_pair(i, 2));
        }

        vector<int> state(N);
        SegTree1 treeone(N); //min
        SegTree2 tapione(N); //max


        ll ans = 0;
        sort(all(pq));
        int pl = 0, pr = 0;
        for (int i = 0; i < N; ++i) {
            pair<ll, pair<int, int>> top = pq[pr++];
            ll value = top.first;
            int v = top.second.first;
            int ab = top.second.second;

            ans += value;
            state[v] |= ab;
        }


        for (int i = 0; i < N; ++i) {
            treeone.update(i, state[i]);
            tapione.update(i, state[i]);
        }

        while (!(treeone.find(0, N) == 0 || treeone.find(0, N) == tapione.find(0, N))) {
            //pr-1を除去
            int pt = pr - 1;
            ll delvalue = pq[pt].first;
            int v = pq[pt].second.first;
            int ab = pq[pt].second.second;


            if ((state[v] & ab) != ab) {
                cout << (state[v] & ab) << endl;
                cout << ab << endl;
                exit(-1);
            }
            state[v] ^= ab;
            treeone.update(v, state[v]);
            tapione.update(v, state[v]);
            ans -= delvalue;

            //prを追加
            pair<ll, pair<int, int>> top = pq[pr++];
            ll value = top.first;
            v = top.second.first;
            ab = top.second.second;

            if ((state[v] & ab) != 0) {
                exit(-1);
            }
            state[v] ^= ab;
            treeone.update(v, state[v]);
            tapione.update(v, state[v]);

            ans += value;


        }

        if (treeone.find(0, N) == 0 || treeone.find(0, N) == tapione.find(0, N)) {
            cout << ans << endl;
            exit(0);
        }

        exit(-1);


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    Solve().solve();


    return 0;
}

