int64_t specialCase(vector<pair<int, int> > a) {
	sort(a.begin(), a.end());
	int64_t s = 0;
	for (auto v : a)
		s += v.first;
	int64_t res = s;
	for (int i=0; i<n; ++i) {
		if (i==n-1)
			res = min(res, a[i].second + s - a[n-2].first);
		else
			res = min(res, a[i].second + s - a[n-1].first);
	}
	return res;
}

