inline void doing()
{
	int Sum=0;
	REP(i,1,n)if(sum[i]==3)printf("%lld\n",ans),exit(0);
	REP(i,1,n)Sum+=sum[i];
	if(Sum==n || Sum==2*n)printf("%lld\n",ans),exit(0);
