            sum += lq.top();lq.pop();
            cnt++;
        }
        else{
            if(lq.top()<=rq.top()){
                sum += lq.top();lq.pop();
                cnt++;
            }
            else{
                sum += rq.top();rq.pop();
                cnt--;
            }
        }
