using namespace std;

struct node {
    int x, y;
}poin[500005];

bool cmp(node a, node b) {
    return a.x < b.x;
}

int n, ans, nowx;
const double eps = 1e-15;

int check() {
    int res = 0;
    for(register int i = 1; i < n; ++i)
        res += min(poin[i].x, poin[i + 1].y);
    res += min(poin[n].x, poin[1].y);
    return res;
}

void mnth() {
    double T = 200000;
    while(T > eps) {
        swap(poin[rand() % n + 1], poin[rand() % n + 1]);
        int tmp = check();
        double delta = tmp - nowx;
        if(delta < 0) nowx = tmp;
        else if(exp(-delta / T) * RAND_MAX > rand())
            nowx = tmp;
        ans = min(ans, nowx);
        T *= 0.97;
    }
}

signed main() {
    srand((int)time(NULL));
    cin >> n;
    for(register int i = 1; i <= n; ++i)
        cin >> poin[i].x >> poin[i].y;
    sort(poin + 1, poin + 1 + n, cmp);
    for(register int i = 1; i < n; ++i)
        ans += min(poin[i].x, poin[i + 1].y);
    ans += min(poin[n].x, poin[1].y);
    nowx = ans;
    mnth();
    cout << ans << endl;
    return 0;
}

