const int MAXN = 120000;

int n;

ll a[MAXN];
ll b[MAXN];

multiset<ll> ss0, ss1;
ll cs;

void add(ll x) {
	if (ss0.size() < n)
		ss0.insert(x), cs += x;
	else if (*ss0.rbegin() > x) {
		ll y = *ss0.rbegin();
		ss0.erase(ss0.find(y));
		ss0.insert(x);
		cs -= y, cs += x;
		ss1.insert(y);
	}
	else {
		ss1.insert(x);
	}
}

void del(ll y) {
	if (ss1.find(y) != ss1.end()) {
		ss1.erase(ss1.find(y));
	}
	else {
		cs -= y;
		ss0.erase(ss0.find(y));
		if (!ss1.empty()) {
			y = *ss1.begin();
			ss1.erase(ss1.begin());
			cs += y;
			ss0.insert(y);
		}
	}
}

