#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair <int, int> pii;

const int MAXN = 2e5 + 5;

int N;
pii a[MAXN], b[MAXN];
int pos[MAXN];
vector <int> comp[MAXN];
int dad[MAXN];
set <int> diff, alive;

void load() {
	scanf("%d", &N);
	for (int i = 0; i < N; i++) {
		scanf("%d%d", &a[i].first, &b[i].first);
		a[i].second = b[i].second = i;
	}
}

inline int cost(int x, int y) {
	return min(a[x - N].first, b[y].first);
}

inline void out(int x) {
	if (diff.count(x))
		diff.erase(x);
}

void change(int x, int y) {
	if (x >= N) {
		dad[x] = y;
		return;
	}

	auto it = alive.find(x);
	auto prv = it, nxt = it;
	if (it != alive.begin())
		prv--;
	if (it != --alive.end())
		nxt++;

	out(x);
	if (it != --alive.end())
		out(*nxt);

	dad[x] = y;

	if (it != alive.begin() && dad[x] != dad[*prv])
		diff.insert(x);
	if (it != --alive.end() && dad[x] != dad[*nxt])
		diff.insert(*nxt);
}

int join(int x, int y, bool f = true) {
	int res = cost(x, y);
	if (f) {
		auto it = alive.find(y);
		auto prv = it, nxt = it;
		if (it != alive.begin())
			prv--;
		if (it != --alive.end())
			nxt++;

		if (it != --alive.end()) {			
			out(*nxt);
			if (it != alive.begin() && dad[*prv] != dad[*nxt])
				diff.insert(*nxt);
		}

		out(y);
		alive.erase(y);
	}

	x = dad[x];
	y = dad[y];
	if (comp[x].size() > comp[y].size()) 
		swap(x, y);

	for (auto it : comp[x]) {
		comp[y].push_back(it);
		change(it, y);
	}

	return res; 
}

void output() {
	printf("alive");
	for (auto it : alive)
		printf(" %d", it);
	puts("");

	printf("diff");
	for (auto it : diff)
		printf(" %d", it);
	puts("");

	puts("");
}

ll solve() {
	sort(a, a + N);
	sort(b, b + N, greater <pii> ());

	for (int i = 0; i < N; i++) {
		pos[a[i].second] = i;
		alive.insert(i);
	}

	for (int i = 1; i < N; i++)
		diff.insert(i);

	for (int i = 0; i < 2 * N; i++) {
		comp[i].push_back(i);
		dad[i] = i;
	}

	for (int i = 0; i < N; i++)
		join(pos[b[i].second] + N, i, false);

	ll sol = 0;
	for (int i = 0; i < N - 1; i++) 
		if (dad[i + N] != dad[*alive.begin()]) 
			sol += join(i + N, *alive.begin());
		else 
			sol += join(i + N, *diff.begin());	

	return sol + cost(2 * N - 1, *alive.begin());
}

int main() {
	load();
	printf("%lld\n", solve());
	return 0;
}

