class CMinCostCycle {
public:
    void solve(istream& cin, ostream& cout) {
      SPEED;
      int n; cin >> n;
      vector<ll> a(n), b(n);
      rep(i, n) {
        cin >> a[i] >> b[i];
      }

      vector<P> v;
      rep(i, n) {
        v.emplace_back(a[i], i);
        v.emplace_back(b[i], i+n);
      }
      sort(all(v));

      bool usedA = false;
      bool usedB = false;
      set<int> remaining;
      rep(i, n) {
        remaining.insert(i);
      }

      ll ret = 0;
      rep(i, n-1) {
        ret += v[i].first;
        if (v[i].second >= n) {
          usedB = true;
          v[i].second -= n;
        } else {
          usedA = true;
        }
        remaining.erase(v[i].second);
      }

      int idx = n-1;
      if (remaining.size() == 1) {
        while (remaining.find(v[idx].second%n) != remaining.end()) {
          if (!usedA && v[idx].second >= n) break;
          if (!usedB && v[idx].second < n) break;
          idx++;
        }
      }
      ret += v[idx].first;
      cout << ret << endl;
    }
};

signed main() {
  CMinCostCycle solver;
  std::istream& in(std::cin);
  std::ostream& out(std::cout);
  solver.solve(in, out);
  return 0;
}

