#define rep(i, n) for(UL i = 0; i < (n); i++)


struct Problem {

	void Solve() {
		UL N; cin >> N;
		vector<pair<ULL, int>> V(N * 2);
		ULL ansL = 0, ansR = 0;
		rep(i, N) {
			cin >> V[i * 2].first >> V[i * 2 + 1].first;
			ansL += V[i * 2].first;
			ansR += V[i * 2 + 1].first;
		}
		rep(i, N) { V[i * 2].second = V[i * 2 + 1].second = i; }
		sort(V.begin(), V.end());
		vector<UL> F(N);
		ULL ans = 0;
		rep(i, N - 1) {
			ans += V[i].first;
			F[V[i].second]++;
		}
		bool ok = false;
		rep(i, N) if (F[i] == 2) ok = true;
		for (UL i = N - 1; i < 2 * N; i++) {
			if (F[V[i].second] == 1) ok = true;
			if (ok) { ans += V[i].first; break; }
		}
		ans = min(ans, min(ansL, ansR));
		cout << ans << endl;
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
Problem::Problem() {
	cout << fixed << setprecision(10);
}

