struct A
{
  A(int a = 0, int b = 0, int i = 0)
    : a(a), b(b), i(i)
  {}
  int a, b, i;
};

int main() {
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);
  int n;
  std::cin >> n;
  auto f1 = [](const A& x, const A &y) {
    if (x.a == y.a)
      return x.i < y.i;
    return x.a < y.a;
  };
  auto f2 = [](const A& x, const A &y) {
    if (x.b == y.b)
      return x.i > y.i;
    return x.b > y.b;
  };
  std::set<A, decltype(f1)> aa(f1);
  std::set<A, decltype(f2)> bb(f2);
  for (int i = 0; i < n; i++) {
    int a, b;
    std::cin >> a >> b;
    A x(a, b, i);
    aa.insert(x);
    bb.insert(x);
  }
  long long sum = 0;
  int idxs = n;
  for (int i = 0; i < n - 1; i++) {
    auto ita = aa.begin();
    A x = *ita;
    auto itb = bb.begin();
    A y = *itb;
    if (x.i == y.i) {
      auto nita = ita;
      auto nitb = itb;
      nita++; nitb++;
      if (nitb->b - ita->a < itb->b - nita->a) {
        itb = nitb;
      } else {
        ita = nita;
      }
    }
    x = *ita;
    y = *itb;
    if (x.i != y.i) {
      aa.erase(ita);
      aa.erase(y);
      bb.erase(itb);
      bb.erase(x);
      sum += std::min(x.a, y.b);
      A xy = A(y.a, x.b, idxs++);
      aa.insert(xy);
      bb.insert(xy);
    }
    else {
      throw 1;
    }
  }
  std::cout << sum + std::min(aa.begin()->a, aa.begin()->b) << std::endl;
}

