void upd_set(set<pii> &sta, set<pii> &stb) {
	it = stb.end();
	it--;
	if (get_par(sta.begin()->_2) == get_par(it->_2)) {
		it--;
	}
	stb.erase(it);
	sta.erase(sta.begin());
