{
	ll a,b,id;
	bool operator<(const ob1&y)const{return b>y.b||(b==y.b&&a>y.a);}
}h;
struct ob2
{
	ll a,b,id;
	bool operator<(const ob2&y)const{return a<y.a||(a==y.a&&b<y.b);}
}hh,hhh;
ll n,i,ans=0,cnt,vis[200005],x,y;
priority_queue<ob1> q1;
priority_queue<ob2> q2;
int main()
{
	scanf("%lld",&n);cnt=n;
	for(i=1;i<=n;i++)
	{
		scanf("%lld%lld",&x,&y);
		q1.push((ob1){x,y,i});
		q2.push((ob2){x,y,i});
	}
	for(i=1;i<=n;i++)
	{
		while(vis[q1.top().id])q1.pop();
		h=q1.top();
		q1.pop();
		while(vis[q2.top().id])q2.pop();
		hh=q2.top();
		q2.pop();
		if(i<n&&hh.id==h.id)
		{
			while(vis[q2.top().id])q2.pop();
			hhh=q2.top();
			q2.pop();
			q2.push(hh);
