void link(int i, int j) {
  p[i] = j;
  s += min(a[i], b[j]);
}

void cut(int i, int j) {
  s -= min(a[i], b[j]);
}

unsigned xor64(void) {
  static unsigned long long x = 88172645463325252ULL;
  x = x ^ (x << 13); x = x ^ (x >> 7);
  return x = x ^ (x << 17);
}

void exec() {
  for (int ii = 0; ii < 10000000; ii++) {
    int i = xor64() % n;
    int j = xor64() % n;
    if (i == j) continue;
    int x = p[i];
    int y = p[j];
    cut(i, x);
    cut(j, y);
    link(i, y);
    link(j, x);
    if (ans < s) {
      cut(i, y);
      cut(j, x);
      link(i, x);
      link(j, y);
    } else if (ans > s) {
      ans = s;
    }
  }
}

