struct DSU
{
    int N,p[maxn];

    void init(int _n)
    {
        N=_n;
        for (int i=1;i<=N;i++) p[i]=i;
    }

    int Find(int x)
    {
        return p[x]==x ? x :p[x]=Find(p[x]);
    }

    void Union(int x,int y)
    {
        assert(Find(x)!=Find(y));
        p[Find(x)]=Find(y);
    }
}dsu;

int32_t main()
{
