        pii tmp2=mkp(dqB.front().F,
                     -(dsu.Find(dqB.front().S)==dsu.Find(dqA.back().S)
                       ? dqA[sz(dqA)-2].F : dqB[sz(dqA)-1].F));

        if (tmp1<tmp2)
        {
            pii now=dqA.front();
            dqA.pop_front();

            if (dsu.Find(now.S)==dsu.Find(dqB.back().S))
            {
                pii tmp=dqB.back();
                dqB.pop_back();
                ans+=now.F;
                dsu.Union(now.S,dqB.back().S);
                dqB.pop_back();
                dqB.push_back(tmp);
            }
            else
            {
                ans+=now.F;
                dsu.Union(now.S,dqB.back().S);
                dqB.pop_back();
            }
        }
        else
        {
            pii now=dqB.front();
            dqB.pop_front();

            if (dsu.Find(now.S)==dsu.Find(dqA.back().S))
            {
                pii tmp=dqA.back();
                dqA.pop_back();
                ans+=now.F;
                dsu.Union(now.S,dqA.back().S);
