            else
            {
                ans+=now.F;
                dsu.Union(now.S,dqA.back().S);
                dqA.pop_back();
            }
        }
    }
    ans+=min(dqA.front().F,dqB.front().F);
    cout<<min({ans,ans1,ans2})<<endl;
}

