LL solve() {
	while(!A.empty()) A.pop();
	while(!B.empty()) B.pop();
	int cnt = n;
	memset(vis, 0, sizeof(vis));

	for(int i = 1; i <= n; ++i) A.push(pii(-a[i], i)), B.push(pii(b[i], i));
  LL ans = 0;
  for(int qwq = 1; qwq <= n - 1; ++qwq) {
    while(vis[A.top().second]) A.pop();
    int u = A.top().second; A.pop(); vis[u] = true;
    while(vis[B.top().second]) B.pop();
    int v = B.top().second; B.pop(); vis[v] = true;
    ans += std::min(a[u], b[v]);
    ++cnt; a[cnt] = a[v]; b[cnt] = b[u];
    A.push(pii(-a[cnt], cnt)); B.push(pii(b[cnt], cnt));
