	int x, y, z;
	P(int _x = 0, int _y = 0, int _z = 0) {
		x = _x, y = _y, z = _z;
	}
} a[N]; int a0;

int cmpa(P a, P b) {
	return a.x < b.x;
}

ll s[N];
ll ans;

