LL N;
LL A[100000], B[100000];
bool usedA[100000], usedB[100000];

LL cat() {
	vector<PP> q;
	vector<PP> w;
	REP(i, 0, N) {
		(usedA[i] ? q : w).push_back(PP(A[i], i));
		(usedB[i] ? q : w).push_back(PP(B[i], i));
	}
	sort(q.begin(), q.end(), greater<PP>());
	sort(w.begin(), w.end());

	if (q[0].second != w[0].second) return w[0].first - q[0].first;
	return min(w[0].first - q[1].first, w[1].first - q[0].first);
}

LL sub() {
	vector<PP> v;
	REP(i, 0, N) {
		v.push_back(PP(A[i], i));
		v.push_back(PP(B[i], i + N));
	}
	sort(v.begin(), v.end());

	REP(i, 0, N) {
		int idx = v[i].second;
		if (idx < N) {
			usedA[idx] = true;
		} else {
			usedB[idx - N] = true;
		}
	}

	bool ok = false;
	int cntA = 0;
	int cntB = 0;
	REP(i, 0, N) {
		if (usedA[i] && usedB[i]) ok = true;
		if (usedA[i] && !usedB[i]) ++cntA;
		if (!usedA[i] && usedB[i]) ++cntB;
	}

	if (cntA == 0 || cntB == 0) ok = true;

	LL sum = 0;
	REP(i, 0, N) {
		sum += v[i].first;
	}
	if (ok) return sum;

	return sum + cat();
}

int main() {
	cin >> N;
	REP(i, 0, N) {
		cin >> A[i] >> B[i];
	}
	cout << sub() << endl;

	return 0;
}

