signed main() {
	INIT;

	VAR(int, n);
	VEC_ROW(int, n, a, b);

	std::priority_queue<PAIR, std::vector<PAIR>, std::greater<PAIR>> pq;
	REP(i, n) pq.push(PAIR(a[i], -i - 1));
	REP(i, n) pq.push(PAIR(b[i], +i + 1));

	int ans = 0;
	std::vector<int> e;
	int cnt[2] = {};
	std::set<int> set;
	REP(i, n) {
		PAIR p = pq.top(); pq.pop();
		if (e.size() == n + 1) {
			int ans2 = ans;
			ans2 -= e[n - 2];
			ans2 += e[n - 1];
			ans2 += e[n - 0];
			ans += p.first;
			CHMIN(ans, ans2);
			break;
		}
		e.emplace_back(p.first);
		if (i == n - 1) {
			++cnt[p.second < 0];
			int f = set.count(std::abs(p.second));
			set.insert(std::abs(p.second));
			if ((cnt[0] != 0 && cnt[1] != 0) && set.size() == n) {
				--cnt[p.second < 0];
				if (f == 0) set.erase(std::abs(p.second));
				--i;
				continue;
			}
		}
		ans += p.first;
		++cnt[p.second < 0];
		set.insert(std::abs(p.second));
	}
	OUT(ans)BR;
	return 0;
}

