LL N;
LL A[100000], B[100000];
bool usedA[100000], usedB[100000];

LL sum = 0;
LL cat() {
	LL mxA = 0;
	LL mxB = 0;
	LL mnA = INFLL;
	LL mnB = INFLL;
	REP(i, 0, N) {
		if (usedA[i]) mxA = max(mxA, A[i]);
		if (usedB[i]) mxB = max(mxB, B[i]);
		if (!usedA[i]) mnA = min(mnA, A[i]);
		if (!usedB[i]) mnB = min(mnB, B[i]);
	}
	return sum - max(mxA, mxB) + min(mnA, mnB);
}

LL sub() {
	vector<PP> v;
	REP(i, 0, N) {
		v.push_back(PP(A[i], i));
		v.push_back(PP(B[i], i + N));
	}
	sort(v.begin(), v.end());

	REP(i, 0, N) {
		int idx = v[i].second;
		if (idx < N) {
			usedA[idx] = true;
		} else {
			usedB[idx - N] = true;
		}
	}

	int cntA = 0;
	int cntB = 0;
	REP(i, 0, N) {
		if (usedA[i] && !usedB[i]) ++cntA;
		if (!usedA[i] && usedB[i]) ++cntB;
	}

	REP(i, 0, N) {
		sum += v[i].first;
	}
	if (cntA == 0 || cntB == 0) return sum;

	LL mn = INFLL;
	mn = min(mn, cat());
	REP(i, 0, N) {
		swap(A[i], B[i]);
		swap(usedA[i], usedB[i]);
	}
	mn = min(mn, cat());
	return mn;
}

int main() {
	cin >> N;
	REP(i, 0, N) {
		cin >> A[i] >> B[i];
	}
	cout << sub() << endl;

	return 0;
}

