        while(f&&!q.empty()){
            P p=q.top();
            q.pop();
            if(k!=p.second&&(i==n-1||!u.same(k, p.second))){
                if(p.first<a)s+=p.first-a;
                u.unite(k, p.second);
                f=false;
            }else{
                t.push_back(p);
            }
        }
        for(int j=0;j<t.size();j++){
            q.push(t[j]);
        }
    }
    cout << s << endl;
}

