		else if(a[i].id<=n-1&&b[i].id>n)x=sum[n-1]+c[b[i].id].val;
		else if(b[i].id<=n-1&&a[i].id>n)x=sum[n-1]+c[a[i].id].val;
		else x=sum[n-2]+c[a[i].id].val+c[b[i].id].val;
		ans=min(ans,x);
	}
	printf("%d\n",ans);
}

