using namespace std;
using ll = long long;

int main() {
    int N;
    cin >> N;
    vector<int>A(N+1);
    vector<int>B(N+1);
    for (int i = 1; i <= N; ++i) {
        cin >> A[i] >> B[i];
    }

    vector<pair<int, int>>cost;
    cost.reserve(2*N);
    for (int i = 1; i <= N; ++i) {
        cost.push_back({A[i], i});
        cost.push_back({B[i], -i});
    }
    sort(cost.begin(), cost.end());

    vector<int>flag(N+1, 0);
    ll ans = 0;
    int A_max = INT_MIN;
    int A_min = INT_MAX;
    int B_max = INT_MIN;
    int B_min = INT_MAX;
    for (int i = 0; i < N; ++i) {
        int c = cost[i].first;
        int f = cost[i].second;
        ans += c;
        if(f > 0){
            flag[f] += 1;
            A_max = max(A_max, c);
        } else{
            flag[-f] += 2;
            B_max = max(B_max, c);
        }
    }
    for (int i = N; i < 2 * N; ++i) {
        int c = cost[i].first;
        int f = cost[i].second;
        if(f > 0){
            A_min = min(A_min, c);
        } else{
            B_min = min(B_min, c);
        }
    }

    if(cost[N].first == cost[N-1].first){
        cout << ans << "\n";
        return 0;
    }

    int flagA = 1;
    int flagB = 1;
    for (int i = 1; i <= N; ++i) {
        if(flag[i] == 2){
            flagA = 0;
        } else if(flag[i] == 1){
            flagB = 0;
        } else{
            cout << ans << "\n";
            return 0;
        }
    }
    if(flagA || flagB){
        cout << ans << "\n";
        return 0;
    }

    int temp = min(B_min - A_max, A_min - B_max);
    ans += temp;
    cout << ans << "\n";
    return 0;
}

