		else s[a[n+1].d^1]--;
		if (s[0] && s[1] && s[0]+s[1]==n); else {Ans=min(Ans,res); continue;}

		res=res-a[n+1].num+a[n+2].num;
		v[a[n+1].id][a[n+1].d]=0,s[a[n+1].d]--;
		v[a[n+2].id][a[n+2].d]=1;
		if (v[a[n+2].id][0]+v[a[n+2].id][1]==1) s[a[n+2].d]++;
		else s[a[n+2].d^1]--;
		if (s[0] && s[1] && s[0]+s[1]==n); else Ans=min(Ans,res);
	}
	printf("%lld\n",Ans);
	return 0;
}

