int n, vis[MAXN];
pii a[MAXN];

void init() {
	read(n);
	for (int i = 1; i <= n; ++i) {
		read(a[i * 2 - 1].fi);
		a[i * 2 - 1].se = i;
		read(a[i * 2].fi);
		a[i * 2].se = -i;
	}
	sort(a + 1, a + n * 2 + 1);
}

void solve() {
	LL ans = 0;
	int cnt1 = 0, cnt2 = 0, cnt3 = 0;
	for (int i = 1; i <= n; ++i) {
		ans += a[i].fi;
		int j = a[i].se;
		if (j > 0) {
			++cnt1;
			cnt3 += (++vis[j] == 2);
		} else {
			++cnt2;
			cnt3 += (++vis[-j] == 2);
		}
	}
	if (cnt3 || (cnt1 == n || cnt2 == n)) {
//printf("type 1\n");
		printf("%lld\n", ans); return;
	}
	ans += a[n + 1].fi - a[n].fi;
	(a[n].se > 0)? --cnt1 : --cnt2;
	(a[n + 1].se > 0)? ++cnt1 : ++cnt2;
	if (abs(a[n].se) != abs(a[n + 1].se) || cnt1 == n || cnt2 == n) {
//printf("type 2\n");
		printf("%lld\n", ans); return;
	}
	printf("%lld\n", min(ans - a[n - 1].fi + a[n].fi, ans - a[n + 1].fi + a[n + 2].fi));
}

int main() {
