int s_gcd(int a, int b) {
	if (b == 0) { return a; }
	return s_gcd(b, a%b);
}
int gcd(int a, int b) {
	if (a < b) { swap(a, b); }
	return s_gcd(a, b);
}
int solve(V<pin> &lis, vel &xx,int sum1) {
	int n = xx.size();
	bool fla=true;
	bool flb=true;
	veb used(n, false);
	int sum = 0;
	bool fl = false;
	for (auto x : xx) {
		pin smt = lis[x];
		int num = smt.second%n;
		fl =fl or used[num];
		used[num] = true;
		sum += smt.first;
		if (smt.second < n) { flb = false; }
		else { fla = false; }
	}
	if (fla || flb || fl) { return sum; }
	return sum1;
}
