namespace Subtask2 {

	/*
		Éè f[i][S] ±íÊ¾µ±Ç°ÔÚ i µã¼¯×´Ì¬Îª S µÄ×îÐ¡»·¡£ 
	*/

	const ll N = 17;

	ll f[N][(1 << 15) + 3];

	inline void Cmin ( ll &a, ll b ) { (a > b) && (a = b); }

	inline void Solve() {
		ll Ans = INF;
		ll Max = (1 << n) - 1;
		For ( i, 1, n ) {
			Set (f, 0x3f);
			f[i][1 << i - 1] = 0;
			For ( S, 0, Max ) For ( j, 1, n ) 
				if (S & (1 << j - 1)) For ( k, 1, n ) 
					if (!(S & (1 << k - 1))) 
						Cmin(f[k][S | (1 << k - 1)], f[j][S] + min(a[j], b[k]));
			For ( j, 1, n ) if (j != i) 
				Cmin(Ans, f[j][Max] + min(a[j], b[i]));
		} wln(Ans), exit(0);
	}

}

