	}

	inline void Solve() {
		For ( i, 1, n ) 
			Ansa += a[i], Ansb += b[i], 
			K[++cc] = (Node) {a[i], i, 0},
			K[++cc] = (Node) {b[i], i, 1}; 
		sort(K + 1, K + 2 * n + 1, cmp);
		For ( i, 1, n ) {
			Ans += K[i].x;
