#include <cstdio>
#include <algorithm>

typedef long long LL;
const int MN = 100005;

int N, A[MN], B[MN];
int Apos[MN], Bpos[MN];
LL Ans, Sum;

struct dat {
	int val, pos, typ;
	dat() {}
	dat(int v, int p, int t)
		: val(v), pos(p), typ(t) {}
	inline friend bool operator < (dat i, dat j) {
		return i.val < j.val;
	}
} D[MN * 2];
int C;

int main() {
	Ans = 0x3f3f3f3f3f3f3f3f;
	scanf("%d", &N);
	for (int i = 1; i <= N; ++i) scanf("%d%d", &A[i], &B[i]);
	for (int i = 1; i <= N; ++i) Sum += A[i];
	Ans = std::min(Ans, Sum), Sum = 0;
	for (int i = 1; i <= N; ++i) Sum += B[i];
	Ans = std::min(Ans, Sum), Sum = 0;
	for (int i = 1; i <= N; ++i)
		D[++C] = dat(A[i], i, 1),
		D[++C] = dat(B[i], i, 0);
	std::sort(D + 1, D + C + 1);
	for (int i = 1; i <= 2 * N; ++i) {
		if (D[i].typ) Apos[D[i].pos] = i;
		else Bpos[D[i].pos] = i;
	}
	for (int i = 1; i <= N; ++i) Sum += D[i].val;
	int ok = 0;
	for (int i = 1; i <= N; ++i)
		if (Apos[i] <= N && Bpos[i] <= N)
			{ ok = 1; break; }
	if (ok) return printf("%lld\n", Sum), 0;
	for (int i = 1; i <= N; ++i) {
		int pos1 = Apos[i], pos2 = Bpos[i];
		if (pos1 > pos2) std::swap(pos1, pos2);
		if (pos1 == N) Ans = std::min(Ans, Sum - D[N - 1].val + D[pos2].val);
		else Ans = std::min(Ans, Sum - D[N].val + D[pos2].val);
	}
	printf("%lld\n", Ans);
	return 0;
}

