struct splitted {
	multiset<int> p0, p1;
	long long cs;
	int sz;
	splitted(int n){
		sz = n;
		cs = 0;
	}
	void add(int x){
		p0.insert(x);
		cs += x;
		if(p0.size() > sz){
			int bad = *(--p0.end());
			p0.erase(--p0.end());
			cs -= bad;
			p1.insert(bad);
		}
	}
	void del(int x){
		if(p1.find(x) != p1.end()){
			p1.erase(p1.find(x));
		} else {
			p0.erase(p0.find(x));
			cs -= x;
			if(!p1.empty()){
				int good = *p1.begin();
				p1.erase(p1.begin());
				cs += good;
				p0.insert(good);
			}
		}
	}
};
