bool check() {
  ll num = pq.top().second;
  if (num < n) {
    if (ac == n-1) return true;
    used_a[num] = true;
  } else {
    if (ac == 0) return true;
    used_b[num-n] = true;
  }
  for (ll i = 0; i < n; i++) if (used_a[i] && used_b[i]) return true;
  if (num < n) {
    used_a[num] = false;
  } else {
    used_b[num-n] = false;
  }
  return false;
}

