int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);
    cout << fixed << setprecision(15);

    int N;
    cin >> N;

    vi A(N), B(N);
    ll as = 0, bs = 0;
    for (int i = 0; i < N; i++) {
        cin >> A[i] >> B[i];
        as += A[i];
        bs += B[i];
    }

    ll ans = min(as, bs);

    vector<array<int, 2>> vals(2 * N);
    for (int i = 0; i < N; i++) {
        vals[2 * i] = { i, 0 };
        vals[2 * i + 1] = { i, 1 };
    }
    sort(all(vals), [&](auto v1, auto v2) {
        int val1 = v1[1] ? B[v1[0]] : A[v1[0]];
        int val2 = v2[1] ? B[v2[0]] : A[v2[0]];
        return val1 < val2;
    });

    vi aloc(N), bloc(N);
    vll psum(2 * N);
    for (int i = 0; i < vals.size(); i++) {
        if (vals[i][1]) {
            bloc[vals[i][0]] = i;
            psum[i] = B[vals[i][0]];
        } else {
            aloc[vals[i][0]] = i;
            psum[i] = A[vals[i][0]];
        }
        if (i) psum[i] += psum[i-1];
    }

    for (int ut = 0; ut < N; ut++) {
        int pi = N - 2;
        while (true) {
            int elt = pi;
            if (aloc[ut] < pi) elt--;
            if (bloc[ut] < pi) elt--;
            if (elt < N - 2) {
                pi++;
            } else break;
        }

        ll cand = pi ? psum[pi - 1] : 0;
        if (aloc[ut] >= pi)
            cand += A[ut];
        if (bloc[ut] >= pi)
            cand += B[ut];
        ans = min(ans, cand);
    }

    cout << ans << endl;
    return 0;
}

