        pq.push(P(ta, i));
        pq.push(P(tb, i+n));
        a[i] = ta;
        b[i] = tb;
        sa[i] = P(ta, i);
        sb[i] = P(tb, i);
    }
    SORT(sa);
    SORT(sb);
    int acnt = 0;
    int bcnt = 0;
    ll ans = 0;
    REP(i, n - 2){
        P tmp = pq.top(); pq.pop();
        if(tmp.second < n){
            int nb;
            FOR(j, bcnt, n){
                if(ub[tmp.second] == sb[j].second || tmp.second == sb[j].second || ub[sb[j].second] != -1){

                }else{
                    nb = j;
                    break;
                }
            }
            ans += sb[nb].first;
            ua[tmp.second] = sb[nb].second;
            ub[sb[nb].second] = tmp.second;
            uf.unite(tmp.second, sb[nb].second);
            if(nb == bcnt) bcnt++;
        }else{
            tmp.second -= n;
            int na;
            FOR(j, acnt, n){
                if(ua[tmp.second] == sa[j].second || tmp.second == sa[j].second || ua[sa[j].second] != -1){

                }else{
                    na = j;
                    break;
                }
            }
            ans += sa[na].first;
            ub[tmp.second] = sa[na].second;
            ua[sa[na].second] = tmp.second;
            uf.unite(tmp.second, sa[na].second);
            if(na == acnt) acnt++;
        }
    }
