void smain() {
    int n;
    cin >> n;

    ll f = 0, s = 0;
    vi a;
    vector<pii> qrs(n);
    fori (i, n) {
        int x, y;
        cin >> x >> y;
        f += x;
        s += y;
        a.push_back(x);
        a.push_back(y);
        qrs[i] = {x, y};
    }

    sort(ALL(a));

    multiset<int> h1, h2;
    ll cur = 0;
    fori (i, n) {
        h1.insert(a[i]);
        cur += a[i];
        h2.insert(a[i + n]);
    }

    auto erase = [&] (int x) -> void {
        if (h2.count(x)) {
            h2.erase(h2.find(x));
        } else {
            cur -= x;
            h1.erase(h1.find(x));
        }
    };
    auto insert = [&] (int x) -> void {
        h2.insert(x);
    };

    auto norm = [&] () -> void {
        while (SZ(h2) > n) {
            auto it = h2.begin();
            h1.insert(*it);
            cur += *it;
            h2.erase(it);
        }
        while (SZ(h1) > n - 2) {
            auto it = prev(h1.end());
            h2.insert(*it);
            cur -= *it;
            h1.erase(it);
        }
    };
    ll ans = min(f, s);
    fori (i, n) {
        int x = qrs[i].first, y = qrs[i].second;

        erase(x);
        erase(y);

        norm();
        inmin(ans, cur + x + y);
        insert(x);
        insert(y);
    }

    cout << ans;
}

