using i64 = long long;

const int N = 400000 + 7;

int n;
int a[N], e[N];
int del[N];
std::set<std::pair<int, int>> q, p;
i64 ans, tmp;

int main() {
//	freopen("code.in", "r", stdin);
//	freopen("code.out", "w", stdout);

	scanf("%d", &n);
	for (int i = 1; i <= n; ++i)
		scanf("%d%d", a + i, a + n + i),
		q.insert(std::pair<int, int>(a[i], e[i] = i)),
		p.insert(std::pair<int, int>(a[i + n], e[i + n] = i + n));
	std::sort(e + 1, e + n * 2 + 1, [](int x, int y) {
		return a[x] < a[y];
	});
	int m = 0;
	for (int i = 1, x, y; m < n - 2; ++i) {
		if (del[e[i]]) continue;
		x = e[i];
		auto j = x <= n ? p.end() : q.end();
		if (((--j)->second - x) % n == 0) --j;
		y = j->second;
		if (x > y) std::swap(x, y);
		ans += std::min(a[x], a[y]);
		del[x] = del[y] = 1;
		q.erase(std::pair<int, int>(a[x], x));
		p.erase(std::pair<int, int>(a[y], y));
		++m;
	}
	auto x1 = *q.begin();
	q.erase(q.begin());
	auto x2 = *q.begin();
	auto y1 = *p.begin();
	p.erase(p.begin());
	auto y2 = *p.begin();
	if (x2.second + n == y1.second || x2.second + n == y2.second) std::swap(x1, x2);
	if (x1.second + n == y2.second) std::swap(y1, y2);
	tmp = std::min(x1.first, y2.first) + std::min(x2.first, y1.first);
	if (x1.second + n == y1.second)
		ans += tmp;
	else
		ans += std::min(tmp, 0ll + std::min(x1.first, y1.first) + std::min(x2.first, y2.first));
	printf("%lld", ans);
	return 0;
}

