    scanf("%d %d", a + i, b + i);
    sa += a[i];
    sb += b[i];
    ab[i] = a[i] + b[i];
  }
  long long ans = min(sa, sb);
  if (n % 2 == 0) {
    sort(ab, ab + n);
    long long cur = 0;
    for (int i = 0; i < n / 2; ++i) {
      cur += ab[i];
    }
    ans = min(ans, cur);
  }
  auto cmp_mn = [](int i, int j) {
    int mni = min(a[i], b[i]);
    int mnj = min(a[j], b[j]);
    int mxi = max(a[i], b[i]);
    int mxj = max(a[j], b[j]);
    if (mni != mnj) {
      return mni > mnj;
    }
    if (mxi != mxj) {
      return mxi > mxj;
    }
    return i < j;
  };
  auto cmp_mx = [](int i, int j) {
    int mni = min(a[i], b[i]);
    int mnj = min(a[j], b[j]);
    int mxi = max(a[i], b[i]);
    int mxj = max(a[j], b[j]);
    if (mxi != mxj) {
      return mxi < mxj;
    }
    if (mni != mnj) {
      return mni > mnj;
    }
    return i < j;
  };
  set<int, decltype(cmp_mn)> mn(cmp_mn);
  set<int, decltype(cmp_mx)> mx(cmp_mx);
  long long cur = 0;
  for (int i = 0; i < n; ++i) {
    cur += min(a[i], b[i]);
    mn.insert(i);
    mx.insert(i);
  }
  while ((int)mn.size() >= 3) {
    int i = *mn.begin();
    int j = *mx.begin();
    if (i != j) {
      cur -= min(a[i], b[i]);
      cur += max(a[j], b[j]);
      mn.erase(i);
      mn.erase(j);
      mx.erase(i);
      mx.erase(j);
    } else {
      long long tmp_mn = cur;
      tmp_mn -= min(a[i], b[i]);
      mx.erase(i);
      int k_mn = *mx.begin();
      tmp_mn += max(a[k_mn], b[k_mn]);
      mx.insert(i);
      long long tmp_mx = cur;
      tmp_mx += max(a[i], b[i]);
      mn.erase(i);
      int k_mx = *mn.begin();
      tmp_mx -= min(a[k_mx], b[k_mx]);
      mn.insert(i);
      mn.erase(i);
      mx.erase(i);
      if (tmp_mn < tmp_mx) {
        cur = tmp_mn;
        mn.erase(k_mn);
        mx.erase(k_mn);
      } else {
        cur = tmp_mx;
        mn.erase(k_mx);
        mx.erase(k_mx);
      }
    }
    ans = min(ans, cur);
  }
  printf("%lld\n", ans);
}

