using namespace std;
struct firstcmp
{
    int x,y,i;
    bool operator<(firstcmp b)const
    {
        if (x!=b.x)
            return x<b.x;
        if (y!=b.y)
            return y<b.y;
        return i<b.i;
    }
};
struct secondcmp
{
    int x,y,i;
    bool operator<(secondcmp b)const
    {
        if (y!=b.y)
            return y<b.y;
        if (x!=b.x)
            return x<b.x;
        return i<b.i;
    }
};
int X[200001],Y[200001];
int main()
{
    int n;
    scanf("%d",&n);
    set<firstcmp> a;
    set<secondcmp> b;
    for (int i=1;i<=n;++i)
    {
        int x,y;
        scanf("%d%d",&x,&y);
        a.insert((firstcmp){y,x,i});
        b.insert((secondcmp){y,x,i});
        Y[i]=x;
        X[i]=y;
    }
    long long ans=0;
    for (int i=1;i<n;++i)
    {
        pair<int,int> ra(a.begin()->x,b.rbegin()->i==a.begin()->i?(++b.rbegin())->y:b.rbegin()->y),
            rb(b.begin()->y,a.rbegin()->i==b.begin()->i?(++a.rbegin())->x:a.rbegin()->x);
        int nwleft,nwright,leftidx,rightidx;
        if (ra.first<rb.first||(ra.first==rb.first&&ra.second>rb.second))
        {
            auto it=--b.end();
            if (it->i==a.begin()->i)
                --it;
            nwleft=it->x,nwright=a.begin()->y,leftidx=it->i,rightidx=a.begin()->i;
            ans+=a.begin()->x;
            a.erase(a.begin());
            b.erase(it);
        }
        else
        {
            auto it=--a.end();
            if (it->i==b.begin()->i)
                --it;
            nwleft=b.begin()->x,nwright=it->y,leftidx=b.begin()->i,rightidx=it->i;
            ans+=b.begin()->y;
            a.erase(it);
            b.erase(b.begin());
        }
        X[n+i]=nwleft;
        Y[n+i]=nwright;
        a.erase((firstcmp){X[leftidx],Y[leftidx],leftidx});
        a.insert((firstcmp){nwleft,nwright,n+i});
        b.erase((secondcmp){X[rightidx],Y[rightidx],rightidx});
        b.insert((secondcmp){nwleft,nwright,n+i});
    }
    printf("%lld\n",ans+min(a.begin()->x,a.begin()->y));
    return 0;
}

