#define int long long

const int N = 2e5 + 233;

int n, A[N], B[N], C[N], vis[N];
long long sum, tmp1, tmp2, ans;
std::priority_queue<std::pair<int, int>> que;

signed main() {
  std::ios::sync_with_stdio(0);
  std::cin >> n;
  for (int i = 1; i <= n; ++i) {
    std::cin >> A[i] >> A[n + i];
    tmp1 += A[i], tmp2 += A[n + i];
  }
  for (int i = 1; i <= n * 2; ++i) {
    que.push({ A[i], i }), vis[i] = 1;
    if (que.size() > n)
      vis[que.top().second] = 0, que.pop();
  }
  for (int i = 1; i <= n; ++i) {
    B[i] = que.top().first;
    C[i] = que.top().second;
    if (C[i] > n) C[i] -= n;
    sum += B[i], que.pop();
  }
  ans = std::min(tmp1, tmp2);
  for (int i = 1; i <= n; ++i) {
    long long tmp = sum;
    if (!vis[i] && !vis[i + n])
      tmp += A[i] + A[n + i] - B[1] - B[2];
    else if (!vis[i] && vis[i + n])
      tmp += A[i] - (C[1] == i ? B[2] : B[1]);
    else if (!vis[n + i] && vis[i])
      tmp += A[n + i] - (C[1] == i ? B[2] : B[1]);
    ans = std::min(ans, tmp);
  }
  std::cout << ans << std::endl;
  return 0;
}

