#include <bits/stdc++.h>
using namespace std;

long long judge(vector<int> &v, int n, long long ans) {
    int acount = 0; int bcount = 0;
    for (int i = 0; i < n; i++) {
        if (v[i] && v[i+n]) {
            return ans;
        }
        if (v[i]) acount++;
        if (v[i+n]) bcount++;
    }
    if (!acount || !bcount) {
        return ans;
    }
    return 1e18;
}

int main() {
    int n; cin >> n;
    deque<pair<long long, int>> p;
    for (int i = 0; i < n; i++) {
        long long a, b; cin >> a >> b;
        p.emplace_back(a, i);
        p.emplace_back(b, i+n);
    }
    sort(p.begin(), p.end());
    vector<int> v(2*n, 0);
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        ans += p[i].first;
        v[p[i].second]++;
    }
    long long z[4];
    z[0] = judge(v, n, ans); // n-1, n
    v[p[n+1].second]++; v[p[n-1].second]--;
    ans += p[n+1].first - p[n-1].first;
    z[1] = judge(v, n, ans); // n-1, n+2
    v[p[n+1].second]--; v[p[n].second]++;
    ans += p[n].first - p[n+1].first;
    z[2] = judge(v, n, ans); // n-1, n+1
    v[p[n-2].second]--; v[p[n-1].second]++;
    ans += p[n-1].first - p[n-2].first;
    z[3] = judge(v, n, ans); // n, n+1
    sort(z, z+4);
    cout << z[0] << endl;
    return 0;
}

