{
	cin >> n;
	for (ll i = 1; i <= n; i++)
	{
		cin >> e[i].v >> e[i + n].v;
		a[i] = e[i].v, b[i] = e[i + n].v;
		e[i].id = i, e[i + n].id = i + n;
	}
	sort(e + 1, e + n * 2 + 1);
	for (ll i = 1; i <= n; i++) vis[e[i].id] = 1, ans += e[i].v;
	min1 = min2 = inf;
	max1 = max2 = -inf;
	for (ll i = 1; i <= n; i++)
	{
		if (vis[i] && vis[i + n])
		{
			cout << ans << endl;
			return 0;
		}
		if (vis[i])
		{
			cnt1++;
			mk1 = i;
			min2 = min(min2, b[i]);
			max2 = max(max2, b[i]);
		}
		if (vis[i + n])
		{
			cnt2++;
			mk2 = i;
			min1 = min(min1, a[i]);
			max1 = max(max1, a[i]);
		}
