	const u32 mid = c[c.size() / 2];
	const u64 sum =
		::std::accumulate(c.cbegin(), c.cbegin() + c.size() / 2, u64(0));

	::std::array<usize, 4> cnt = {};

	for (const auto i : rep<>(0, n)) {
		++cnt[(a[i] >= mid) << 1 | (b[i] >= mid)];
	}

	if (cnt[0] || !cnt[1] || !cnt[2])
		::std::cout << sum << ::std::endl;
	else
		::std::cout << sum + mid - c[c.size() / 2 - 1] << ::std::endl;

	return 0;
}

