int a[N], b[N];
int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  int n;
  cin >> n;
  int used[2][N] = {};
  vector<tuple<int, int, int>> v;
  for(int i = 0; i < n; i++) cin >> a[i] >> b[i], v.emplace_back(a[i], 0, i), v.emplace_back(b[i], 1, i);
  sort((v).begin(), (v).end());
  int x = 0, y = 0, z = 0, w = 0;
  ll ans = 0;
  for(int i = 0; i < n; i++) {
    int x, t, idx;
    tie(x, t, idx) = v[i];
    used[t][idx] = 1;
    ans += x;
  }
  ll goX0 = -1, goX1 = -1, x0, x1;
  ll goW0 = -1, goW1 = -1, w0, w1;
  for(int i = 0; i < n; i++) {
    if(used[0][i] && used[1][i]) x++;
    else if(used[0][i] && !used[1][i]) {
      y++;
      if(goX0 == -1 || (x0 > b[i])) goX1 = goX0, x1 = x0, goX0 = i, x0 = b[i];
      else if(goX1 == -1 || (x1 > b[i])) goX1 = i, x1 = b[i];
      if(goW0 == -1 || (w0 < a[i])) goW1 = goW0, w1 = w0, goW0 = i, w0 = a[i];
      else if(goW1 == -1 || (w1 < a[i])) goW1 = i, w1 = a[i];
    }
    else if(!used[0][i] && used[1][i]) {
      z++;
      if(goX0 == -1 || (x0 > a[i])) goX1 = goX0, x1 = x0, goX0 = i, x0 = a[i];
      else if(goX1 == -1 || (x1 > a[i])) goX1 = i, x1 = a[i];
      if(goW0 == -1 || (w0 < b[i])) goW1 = goW0, w1 = w0, goW0 = i, w0 = b[i];
      else if(goW1 == -1 || (w1 < b[i])) goW1 = i, w1 = b[i];
    }
    else if(!used[0][i] && !used[1][i]) w++;
  }
  if(y && z && !x && !w) {
    if(goW0 != goW1) {
      ans += x0 - w0;
    } else {
      if(x0 - w1 > x1 - w0) {
        ans += x1 - w0;
      } else{
        ans += x0 - w1;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

