        scanf("%d %d",&A[i],&B[i]);
    }
    ll ret = 0,a=0,b=0;
    for(int i=1;i<=n;++i) {
        a += A[i],b+=B[i];
    }
    ret = min(a,b);
    vector<pair<int,int> > in;
    for(int i=1;i<=n;++i) {
        int aid = i*2-1, bid = i*2;
        in.push_back(make_pair(A[i],aid));
