    for(int i=0;i<n-2;++i) {
        sum += in[i].first;
    }
    for(int i=1;i<=n;++i) {
        int aid = i*2-1,bid = i*2;
        int pos = n-2;
        ll cur = sum;
        if(ind[aid]<n-2) {
            --pos;
            cur -=A[i];
