typedef pair<int, int> pp;

int getBest(vector<pp> &p) {
    int n = p.size();


    vector<pp> v;

    for (int i = 0; i < p.size(); ++i) {
        v.emplace_back(p[i].first, i);
        v.emplace_back(p[i].second, i);
    }

    sort(v.begin(), v.end());

    vector<vector<int>> pos(n);
    for (int i = 0; i < v.size(); ++i) {
        pos[v[i].second].push_back(i);
    }

    int sum = 0;
    for (int i = 0; i < n - 2; ++i) {
        sum += v[i].first;
    }

    int best = numeric_limits<int>::max();
    for (int i = 0; i < p.size(); ++i) {
        int sum2 = sum;
        if (pos[i][0] < n - 2) {
            sum2 += v[n - 2].first;

            if (pos[i][1] < n - 1) {
                sum2 += v[n - 1].first;
            } else {
                sum2 += v[pos[i][1]].first;
            }
        } else {
            sum2 += v[pos[i][0]].first;
            sum2 += v[pos[i][1]].first;
        }

        best = min(best, sum2);
    }

    return best;
}

