    }

    ll ans = TEN(18);
    {
        ll sm = 0;
        for (int i = 0; i < n; i++) {
            sm += p[i].first;
        }
        ans = min(ans, sm);
    }
    {
        ll sm = 0;
        for (int i = 0; i < n; i++) {
            sm += p[i].second;
        }
        ans = min(ans, sm);
    }
    {
        ll sm = 0;
        priority_queue<ll, V<ll>, greater<ll>> que0, que1;
        for (int i = 0; i < n; i++) {
            if (p[i].first > p[i].second) swap(p[i].first, p[i].second);
            sm += p[i].first;
            que0.push(p[i].second);
            que1.push(-p[i].first);
        }
               ;
        bool first = true;
        while (que0.size()) {
            ll p0 = que0.top(); que0.pop();
            ll p1 = que1.top(); que1.pop();
                       ;
            if (first || p0 + p1 < 0) {
                first = false;
                sm += p0 + p1;
            }
        }
        ans = min(ans, sm);
    }
