        res = min(res, min(cur + x[0].first - y[n - 2].first, cur + x[1].first - y[n - 1].first));
    }
    else {
        res = min(res, cur + x[0].first - y[n - 1].first);
    }
    for (int k = 1; k <= n; ++k) {
        ll a1 = x[k - 1].first;
        ll a2 = y[n - k].first;
        if (a2 <= a1)
            break;
        cur = cur + a1 - a2;
        res = min(res, cur);
    }
    cout << res << endl;

}

