const int N = 2e5 + 5;

struct NODE {
  int val, who, id;
  friend bool operator < (NODE a, NODE b) {
    return a.val < b.val;
  }
}P[N];

int n, m, x, y, A[N][2], tot;

bool vis[N][2];

int main() {
  cin >> n;
  for(int i = 1; i <= n; ++ i) {
    scanf("%d%d", &A[i][0], &A[i][1]);
    P[++ tot] = (NODE){A[i][0], i, 0};
    P[++ tot] = (NODE){A[i][1], i, 1};
  }
  sort(P + 1, P + tot + 1);
  long long ans = 0;
  for(int i = 1; i <= n; ++ i) {
    vis[P[i].who][P[i].id] = 1;
    ans += P[i].val;
  }
  int l = 0, r = 0;
  for(int i = 1; i <= n; ++ i) {
    l += vis[i][0];
    r += vis[i][1];
    if(vis[i][0] == vis[i][1]) {
      printf("%lld\n", ans);
      return 0;
    }
  }
  if(l == n || r == n) {
    cout << ans << endl;
    return 0;
  }

  int res = 1e9;
  if(l == 1) {
    for(int i = 1; i <= n; ++ i) {
      if(vis[i][0]) res = min(res, A[i][1] - A[i][0]);
    }
  }
  if(r == 1) {
    for(int i = 1; i <= n; ++ i) {
      if(vis[i][1]) res = min(res, A[i][0] - A[i][1]);
    }
  }
  vis[P[n + 1].who][P[n + 1].id] = 1;
  for(int i = 1; i <= n; ++ i) {
    if(!vis[P[i].who][P[i].id ^ 1]) {
      res = min(res, P[n + 1].val - P[i].val);
    }
    else res = min(res, P[n + 2].val - P[i].val);
  }
  cout << ans + res << endl;
}

