void solve() {
    int n;
    cin >> n;
    vector<ll> a(n), b(n);
    ll res = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
    }
    for (int i = 0; i < n; ++i) {
        res += a[i];
    }
    ll cur = 0;
    for (int i = 0; i < n; ++i) {
        cur += b[i];
    }
    res = min(res, cur);
    vector<ll> x(n), y(n);
    cur = 0;
    for (int i = 0; i < n; ++i) {
        x[i] = max(a[i], b[i]);
        y[i] = min(a[i], b[i]);
        cur += y[i];
    }
    sort(x.begin(), x.end());
    sort(y.begin(), y.end());
    if (x[0] == y[n - 1]) {
        res = min(res, min(cur + x[0] - y[n - 2], cur + x[1] - y[n - 1]));
    }
    if (x[0] > y[n - 1]) {
        res = min(res, cur + x[0] - y[n - 1]);
    }
    for (int k = 1; k <= n; ++k) {
        ll a1 = x[k - 1];
        ll a2 = y[n - k];
        if (a2 <= a1)
            break;
        cur = cur + a1 - a2;
        res = min(res, cur);
    }
    cout << res << endl;

}

