		if (a > b)swap(a, b);
		C = scr[N - 1];
		if (a < C) {
			if (b > C)CR += b - C;
		}
		else {
			CR += a - C;
			C = scr[N - 2];
			if (b > C) {
				CR += b - C;
			}
		}
		ans = min(ans, CR);
		CR = CRR;
	}
	cout << ans << endl;
}

