		set_tree(i, B);
	}
	while (!Q.empty()) {
		int v, idx, temp;
		tie(v, idx) = Q.top();
		Q.pop();
		v = -v;
		temp = get_value(idx);
		set_tree(idx, 0);
		if (tree[1].first) {
			ans += min(tree[1].first, v);
		}
		else {
			ans += min(v, temp);
		}
		set_tree(tree[1].second, temp);
	}
	cout << ans << '\n';
	return 0;
}

