struct NODE
{
	int x, ida, idb;

	NODE (const int &x0 = 0, const int &ia = 0, const int &ib = 0) : x(x0), ida(ia), idb(ib) {}

	bool operator < (const NODE &t) const {return x<t.x;}
};

int n;
