	cmin(ans, calc(tmp));
	tmp.pop_back(), tmp.pop_back();
	tmp.push_back(*(seq.begin()+n)), tmp.push_back(*(seq.begin()+n-1));
	cmin(ans, calc(tmp));
	printf("%lld\n", ans);
}

