			ll cost1 = accumulate(C.begin(), C.begin() + N, 0LL);
			swap(B[N - 1], B[N + 1]);

			swap(B[N - 2], B[N]);
			C = proj<0>(B);
			ll cost2 = accumulate(C.begin(), C.begin() + N, 0LL);
			cost.push_back(min(cost1, cost2));
		}


	}
	cout << *min_element(all(cost));
	return 0;
}

