int main() {
	int n; reader(n);
	vector<Pll> v(n);
	FOR(i, n) reader(v[i].first, v[i].second);

	vector<pair<ll, int>> vp;
	FOR(i, n) {
		vp.emplace_back(v[i].first, 2 * i);
		vp.emplace_back(v[i].second, 2 * i + 1);
	}
	sort(vp.begin(), vp.end());


	ll ans2;
	{
		ll a = 0, b = 0;
		FOR(i, n) {
			a += v[i].first;
			b += v[i].second;
		}
		ans2 = min(a, b);
	}

	ll ans = 0;
	vector<int> nm(n);
	vector<int> cnt = {n,0,0,0};

	bool special = false;

	for (auto& kv : vp) {
		ll val = kv.first;
		int id = kv.second / 2;
		int lr = kv.second % 2;

		vector<int> ncnt = cnt;
		ncnt[nm[id]]--;
		int nnm = nm[id] | (1 << lr);
		ncnt[nnm]++;

		if (ncnt[0] == 0 && ncnt[3] == 0 && ncnt[1] != n && ncnt[2] != n) {
			special = true;
		}

		cnt = ncnt;
		nm[id] = nnm;
		ans += val;

		if (cnt[1] + cnt[2] + cnt[3] * 2 == n) break;
	}

	if (special) {
		ll ans3 = ll(1e15);
		vector<Pll> a, b;
		FOR(i, n) {
			ll val = vp[i].first;
			int id = vp[i].second / 2;
			int lr = vp[i].second % 2;
			if (lr == 0) a.emplace_back(val, id);
			else b.emplace_back(val, id);
		}
		sort(a.rbegin(), a.rend());
		sort(b.rbegin(), b.rend());

		//sz(a), sz(b) > 0
		FOR(i, n) {
			ll cans = ans - min(v[i].first, v[i].second) + v[i].first + vp[i].second;
			ll amax = a[0].first;
			if (a[0].first == v[i].first) {
				if (sz(a) == 1) continue;
				amax = a[1].first;
			}
			ll bmax = b[0].first;
			if (b[0].first == v[i].second) {
				if (sz(b) == 1) continue;
				bmax = b[1].second;
			}
			cans += min(amax, bmax);

			ans3 = min(ans3, cans);
		}

		ans = ans3;
	}

	writerLn(min(ans, ans2));

	return 0;
}

