struct UnionFind{
    vector<int> parent, rank;
    UnionFind(int n) : parent(n, -1), rank(n, 0) { }
    int find(int x){
        if(parent[x] == -1) return x;
        else return (parent[x] = find(parent[x]));
    }
    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(rank[x] < rank[y])
            parent[x] = y;
        else
            parent[y] = x;
        if(rank[x] == rank[y]) rank[x]++;
        return true;
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
};


ll solve(){
    ll res = 0;
    int N; cin >> N;
    vector<ll> A(N),B(N);
    for(int i = 0; i < N;i++) cin >> A[i] >> B[i];

    priority_queue<pll,vector<pll>,greater<pll>> pq1;
    priority_queue<pll> pq2;

    UnionFind UF(2*N);
    for(int i = 0; i < N;i++) UF.unite(i, i+N);
    for(int i = 0;i < N;i++){
        pq1.push({A[i],i});
        pq2.push({B[i],i});
    }
    while(pq1.size()!=1){
        auto q1 = pq1.top(); pq1.pop();
        auto q2 = pq2.top(); pq2.pop();


        ll Bid = q1.second + N;
        ll Aid = q2.second;
        vector<pll> in;
        while(UF.same(q2.second,Bid)){
            in.push_back(q2);
            q2 = pq2.top(); pq2.pop();
        }

        UF.unite(q2.second,Bid);
        res += min(q1.first,q2.first);
        for(const pll& q:in) pq2.push(q);
    }
    res += min(pq1.top().first,pq2.top().first);

    ll T = res;
    res = 0;
    UF = UnionFind(2*N);
    for(int i = 0; i < N;i++) UF.unite(i, i+N);
    for(int i = 0;i < N;i++){
        pq1.push({A[i],i});
        pq2.push({B[i],i});
    }
    while(pq1.size()!=1){
        auto q1 = pq1.top(); pq1.pop();
        auto q2 = pq2.top(); pq2.pop();


        ll Bid = q1.second + N;
        ll Aid = q2.second;
        vector<pll> in;
        while(UF.same(Aid,q1.second+N)){
            in.push_back(q1);
            q1 = pq1.top(); pq1.pop();
        }

        UF.unite(Aid,q1.second+N);
        res += min(q1.first,q2.first);
        for(const pll& q:in) pq1.push(q);
    }
    res += min(pq1.top().first,pq2.top().first);

    res = min(res,T);
    return res;
}
