  ll tmp = INF;
  for (ll i = 0; i < n; i++) {
    if (used_a[i]) {
      not_use_b.insert(P(b[i], i));
      if (!not_use_b.empty()) tmp = min(tmp, not_use_b.begin()->first - a[i]);
      not_use_b.erase(P(b[i], i));
