      not_use_a.erase(P(a[i], i));
      if (!not_use_a.empty()) tmp = min(tmp, not_use_a.begin()->first - b[i]);
      not_use_a.insert(P(a[i], i));
    }
  }
  ans += tmp;
  printf("%lld\n", ans);
}

