	for(int i = 0; i < N; ++i) for(int j = 0 ; j < 2; ++j) pq.push({-AB[i][j],{i,j}});
	V<V<int>> flg(N,V<int>(2,0));
	for(int n = 0; n < N; ++n){
		auto tmp = pq.top(); pq.pop();
		int i = tmp.second.first;
		int j = tmp.second.second;
		flg[i][j] = 1;
	}
