	for(int i = 0; i < N; ++i) if(flg[i][0] && !flg[i][1]) L++;
	for(int i = 0; i < N; ++i) if(!flg[i][0] && flg[i][1]) R++;
	ll ans = LLINF;
	if (L+R != N || L == N || R == N){
		ans = 0;
