struct QF {
  V<> par;
  V< set<int> > chi;

  QF(int n) : par(n), chi(n) {
    for (int i = 0; i < n; i++) {
      par[i] = i;
      chi[i].insert(i);
    }
  }

  bool same(int a, int b) { return par[a] == par[b]; }

  int size(int a) { return chi[par[a]].size(); }

  void unite(int a, int b) {
    if (same(a, b)) return;
    if (size(a) < size(b)) swap(a, b);
    a = par[a], b = par[b];
    for (int i : chi[b]) par[i] = a;
    chi[a].insert(chi[b].begin(), chi[b].end());
    chi[b].clear();
  }
};


int main() {
  cin.tie(NULL); ios::sync_with_stdio(false);
  int n; cin >> n;
  V<lint> a(n), b(n); for (int i = 0; i < n; i++) cin >> a[i] >> b[i];
  V< pair<lint, int> > ps(2 * n);
  for (int i = 0; i < n; i++) {
    ps[i] = {a[i], i};
    ps[i + n] = {b[i], i + n};
  }
  sort(ps.begin(), ps.end());
  QF qu(n);
  int p = 0;
  V<bool> used(2 * n);
  V< pair<lint, int> > ap(n), bp(n);
  for (int i = 0; i < n; i++) ap[i] = {a[i], i}, bp[i] = {b[i], i + n};
  sort(ap.rbegin(), ap.rend());
  sort(bp.rbegin(), bp.rend());
  int pa = 0, pb = 0;
  lint res = 0;
  for (int i = 0; i < n - 1; i++) {
    while (p < n - 1 and used[ps[p].second]) p++;
    while (pa < n - 1 and used[ap[pa].second]) pa++;
    while (pb < n - 1 and used[bp[pb].second]) pb++;
    res += ps[p].first;
    if (ps[p].second < n) {
      while (true) {
        if (!qu.same(ps[p].second, bp[pb].second - n)) break;
        pb++;
        while (pb < n - 1 and used[bp[pb].second]) pb++;
      }
      qu.unite(ps[p].second, bp[pb].second - n);
      used[ps[p++].second] = true;
      used[bp[pb++].second] = true;
    } else {
      while (true) {
        if (!qu.same(ps[p].second - n, ap[pa].second)) break;
        pa++;
        while (pa < n - 1 and used[ap[pa].second]) pa++;
      }
      qu.unite(ps[p].second - n, ap[pa].second);
      used[ps[p++].second] = true;
      used[ap[pa++].second] = true;
    }
  }
  return 0;
  lint mn = 2e9;
  for (int i = 0; i < 2 * n; i++) if (!used[ps[i].second]) mn = min(mn, ps[i].first);
  cout << res + mn << '\n';
}

