using namespace std;
using ll = long long;
using P = pair<ll, ll>;

ll N;
vector<P> AB;

void input() {
    cin >> N;
    AB.resize(N);

    for (auto& v : AB) {
        cin >> v.first >> v.second;
    }
}

ll weight(ll a, ll b) {
    return min(AB[a].first, AB[b].second);
}

ll solve() {
    struct RW {
        ll f, t;
        ll w() {
            return weight(f, t);
        }
    };
    vector<RW> roots = {RW{0, 0}};
    roots.reserve(N);
    for (ll i = 1; i < N; i++) {
        ll minW = 0, minWI = 0;
        for (ll j = 0; j < roots.size() + 1; j++) {
            auto &prev = j == 0 ? roots.back() : roots[j - 1];
            auto &next = j == roots.size() ? roots.front() : roots[j];
            ll w = weight(prev.f, i) + weight(i, next.f) - prev.w();
            if (j == 0)
                minW = w;
            else {
                if (minW > w) {
                    minW = w;
                    minWI = j;
                }
            }
        }
        roots[(minWI + roots.size() - 1) % roots.size()].t = i;
        roots.insert(roots.begin() + minWI, RW{i, roots[minWI].f});
    }
    ll ans = 0;
    for (auto &ro : roots)
        ans += ro.w();
    return ans;
}

int main() {
    input();

    cout << solve() << endl;


    return 0;
}

