//min(A,B)については，どっちを選んでもいいとする（どうせ最適解ではminになっているので）．
//全てAまたは全てBなら閉路は作れる．
//それ以外の場合，sort(A_1,...,A_n,B_1,...,B_n)をして，前半N項の中に同じ添字のものがあれば，閉路を作れる．
//無ければ，全てのiについて，i番目をO型にしたときのコストと今のコストを比較．

int main(void){
	bool is_double=false;
	ll n,visited[100010]={},ans,sum_a=0,sum_b=0,sum=0;
	mp x[200010];
	cin>>n;
	rep(i,n){
		ll a,b;
		cin>>a>>b;
		x[2*i]=make_pair(a,i);
		x[2*i+1]=make_pair(b,i);
		sum_a+=a;
		sum_b+=b;
	}
	ans=min(sum_a,sum_b);//全てAまたは全てBでも閉路は作れる．
	sort(x,x+2*n);
	rep(i,n){
		mp a=x[i];
		// printf("%lld:%lld\n",a.second,a.first);
		sum+=a.first;
		if(visited[a.second]==0){
			visited[a.second]=1;
		}else{//２回通った
			is_double=true;
		}
	}
	if(is_double){
		ans=sum;
	}else{
		rep(i,n){//x[i]番目をO型にする
			ll tmp=sum-x[i].first;
			if(x[n].second!=x[i].second){
				tmp+=x[n].first;
			}else{
				tmp+=x[n+1].first;
			}
			ans=min(ans,tmp);
		}
	}
	cout<<ans<<endl;
	return 0;
}

