int main() {
    int n; cin >> n;
    vector<int> a(n * 2), b(n * 2);
    priority_queue<pii, vector<pii>, greater<>> que1, que12;
    priority_queue<pii> que2, que22;
    for(int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
        que1.emplace(a[i], i); que12.emplace(b[i], i);
        que2.emplace(b[i], i); que22.emplace(a[i], i);
    }
    int iter = n;
    ll ans = 0;
    vector<bool> used(2 * n);

    auto get_unused = [&] (auto& que) {
        assert(!que.empty());
        auto res = que.top(); que.pop();
        while(used[res.second]) {
            assert(!que.empty());
            res = que.top(); que.pop();
        }
        return res;
    };
    while(iter < 2 * n - 1) {
        auto p = get_unused(que1);
        used[p.second] = true;
        if(que2.top().second == p.second) {
            auto tp = que2.top(); que2.pop();
            auto p2 = get_unused(que2);
            a[iter] = a[p2.second], b[iter] = b[p.second];
            que2.push(tp);
            used[p.second] = used[p2.second] = true;
            que1.emplace(a[iter], iter);
            que2.emplace(b[iter], iter);
            ans += min(p.first, p2.first);
            iter++;
        } else {
            auto p2 = get_unused(que2);
            if(p2.second == p.second) {
                auto tp = p2;
                p2 = get_unused(que2);
                ans += min(p.first, p2.first);
                a[iter] = a[p2.second], b[iter] = b[p.second];
                que2.push(tp);
                used[p.second] = used[p2.second] = true;
                que1.emplace(a[iter], iter);
                que2.emplace(b[iter], iter);
                iter++;
            } else {
                ans += min(p.first, p2.first);
                a[iter] = a[p2.second], b[iter] = b[p.second];
                used[p.second] = used[p2.second] = true;
                que1.emplace(a[iter], iter);
                que2.emplace(b[iter], iter);
                iter++;
            }
        }
    }
    while(used[que1.top().second]) que1.pop();
    while(used[que2.top().second]) que2.pop();
    ans += min(que1.top().first, que2.top().first);

    // uso ha kanasii
    iter = n;
    fill(begin(used), end(used), false);
    ll ans2 = 0;
    while(iter < 2 * n - 1) {
        auto p = get_unused(que12);
        used[p.second] = true;
        if(que22.top().second == p.second) {
            auto tp = que22.top(); que22.pop();
            auto p2 = get_unused(que22);
            a[iter] = a[p.second], b[iter] = b[p2.second];
            que22.push(tp);
            used[p.second] = used[p2.second] = true;
            que12.emplace(b[iter], iter);
            que22.emplace(a[iter], iter);
            ans2 += min(p.first, p2.first);
            iter++;
        } else {
            auto p2 = get_unused(que22);
            if(p2.second == p.second) {
                auto tp = p2;
                p2 = get_unused(que22);
                ans2 += min(p.first, p2.first);
                a[iter] = a[p.second], b[iter] = b[p2.second];
                que22.push(tp);
                used[p.second] = used[p2.second] = true;
                que12.emplace(b[iter], iter);
                que22.emplace(a[iter], iter);
                iter++;
            } else {
                ans2 += min(p.first, p2.first);
                a[iter] = a[p.second], b[iter] = b[p2.second];
                used[p.second] = used[p2.second] = true;
                que12.emplace(b[iter], iter);
                que22.emplace(a[iter], iter);
                iter++;
            }
        }
    }
    while(used[que12.top().second]) que12.pop();
    while(used[que22.top().second]) que22.pop();
