ll solve() {
    ll N, a, b, sa = 0, sb = 0;
    cin >> N;
    vector<pii> C;
    for ( int i = 0; i < N; i++ ) {
        cin >> a >> b;
        C.push_back(pii(a, i));
        C.push_back(pii(b, i));
        sa += a;
        sb += b;
    }
    sort(C.begin(), C.end());
    ll ans = min(sa,sb);
    ll s = 0;
    vector<int> cc(N);
    for ( int i = 0; i < N; i++ ) {
        s += C[i].first;
        cc[C[i].second]++;
    }
    bool con = false;
    for ( int i = 0; i < N; i++ ) {
        if ( cc[i] != 1 ) {
            con = true;
        }
    }
    if ( !con ) {
        if ( C[N-1].second != C[N].second ) {
            s += C[N].first - C[N-1].first;
        } else {
            s += min( C[N+1].first - C[N-1].first, C[N].first - C[N-2].first);
        }
    }
    ans = min(ans, s);
    return ans;
}

