		R[i]=R[i+1]+min(a[i].v,b[i].v);
	int m=1;
	while (m<=n&&a[m].v<b[m].v)
		m++;
	int t=m;
	while (t<=n&&a[t].v==b[t].v)
		t++;
	if (m==1||t>n)
		solve();
	m--,t--;
	memset(tax,0,sizeof tax);
	for (int i=1;i<=m;i++)
		ins(a[i].id,1);
	for (int i=1;i<=m;i++)
		ins(b[i].id,-1);
	if (tot)
		solve();
	for (int i=m+1;i<=t;i++){
		ins(a[i].id,1);
		ins(b[i].id,-1);
		if (tot)
			solve();
	}
	LL ans=1LL<<60;
	for (int i=m+1;i<=t+1;i++)
		ans=min(ans,L[i-2]+R[i+1]+min(a[i].v,b[i-1].v)
								 +min(a[i-1].v,b[i].v));
	ans=min(ans,L[m]+R[t+1]+1LL*a[t].v*(t-m));
	cout << ans << endl;
	return 0;
}

