using namespace std;
const long long inf = 1LL << 62;
int main() {
	int N;
	cin >> N;
	vector<int> A(N), B(N);
	for (int i = 0; i < N; ++i) {
		cin >> A[i] >> B[i];
	}
	vector<int> rank(2 * N);
	for (int i = 0; i < 2 * N; ++i) rank[i] = i;
	sort(rank.begin(), rank.end(), [&](int i, int j) {
		int v1 = (i < N ? A[i] : B[i - N]);
		int v2 = (j < N ? A[j] : B[j - N]);
		return v1 < v2;
	});
	vector<int> bit(N);
	long long sum = 0;
	for (int i = 0; i < N; ++i) {
		bit[rank[i] % N] |= 1 << (rank[i] / N);
		sum += (rank[i] < N ? A[rank[i]] : B[rank[i] - N]);
	}
	vector<int> c(4);
	for (int i = 0; i < N; ++i) {
		++c[bit[i]];
	}
	if (c[0] >= 1 || c[1] == 0 || c[2] == 0) {
		cout << sum << endl;
	}
	else {
		vector<int> irank(2 * N);
		for (int i = 0; i < 2 * N; ++i) irank[rank[i]] = i;
		long long delta = inf;
		for (int i = 0; i < 2 * N; ++i) {
			if (irank[i] >= N) {
				int tar = rank[N - 1];
				if (abs(i - tar) == N) {
					tar = (N == 1 ? -1 : rank[N - 2]);
				}
				if (tar != -1) {
					delta = min(delta, (long long)(i < N ? A[i] : B[i - N]) - (long long)(tar < N ? A[tar] : B[tar - N]));
				}
			}
		}
		if (c[1] == 1) {
			int ptr = find(bit.begin(), bit.end(), 1) - bit.begin();
			delta = min(delta, (long long)(B[ptr] - A[ptr]));
		}
		if (c[2] == 1) {
			int ptr = find(bit.begin(), bit.end(), 2) - bit.begin();
			delta = min(delta, (long long)(A[ptr] - B[ptr]));
		}
		cout << sum + delta << endl;
	}
	return 0;
}

