int main() {
    int n; scanf("%d", &n);
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) scanf("%d%d", &a[i], &b[i]);
    long long ans = min(accumulate(a.begin(), a.end(), 0LL), accumulate(b.begin(), b.end(), 0LL));
    long long res = 0;
    for (int i = 0; i < n; ++i) res += min(a[i], b[i]);
    vector<int> od(n);
    iota(od.begin(), od.end(), 0);
    sort(od.begin(), od.end(), [&](int i, int j) { return a[i] + b[i] - min(a[i], b[i]) < a[j] + b[j] - min(a[j], b[j]); });
    vector<int> pos(n, 0);
    set<pair<int, int>> l, r;
    for (int i = 0; i < n; ++i) l.insert(make_pair(min(a[i], b[i]), i));
    long long rsum = 0;
    for (int i = 0; i < n; ++i) {
        int j = od[j];
        if (pos[j] == 0) l.erase(make_pair(min(a[j], b[j]), j));
        else r.erase(make_pair(min(a[j], b[j]), j)), rsum -= min(a[j], b[j]);
        while (r.size() < i + 1) {
            if (l.empty()) break;
            auto p = *l.rbegin();
            l.erase(p);
            r.insert(p);
            rsum += p.first;
        }
        if (r.size() != i + 1) break;
        res += a[j] + b[j] - min(a[j], b[j]);
        ans = min(ans, res - rsum);
    }
    printf("%lld\n", ans);
    return 0;
}

