    ll s[200002];
    P pa[100002], pb[100002];
    for(int i = 0; i < n; i++){
        cin >> a[i] >> b[i];
        s[i * 2] = a[i];
        s[i * 2 + 1] = b[i];
        pa[i] = P(a[i], i);
        pb[i] = P(b[i], i);
    }
    sort(pa, pa + n);
    sort(pb, pb + n);
    sort(s, s + n * 2);
    bool used[100002];
    fill(used, used + n, false);
    int na = 0, nb = 0;
    ll ans = 0;
    int last;
    for(int i = 0; i < n; i++){
        if(pa[na] < pb[nb]){
            ans += pa[na].first;
            used[pa[na].second] = true;
            last = pa[na].second;
            na++;
        }
        else{
            ans += pb[nb].first;
            used[pb[nb].second] = true;
            last = pb[nb].second;
            nb++;
        }
    }
    if(na == 0 || nb == 0){
        cout << ans << endl;
        return 0;
    }
    bool dbl = false;
    for(int i = 0; i < n; i++) dbl |= !used[i];
    if(dbl){
        cout << ans << endl;
        return 0;
    }
