    if(pa[na].first < pb[nb].first){
        r = pa[na].second;
        na++;
    }
    else{
        r = pb[nb].second;
        nb++;
    }
    if(last != r){
        cout << ans - s[n - 1] + s[n] << endl;
    }
    else{
        cout << ans + min(s[n + 1] - s[n - 1], s[n] - s[n - 2]) << endl;
    }
