#include <bits/stdc++.h>

struct Cost {
	int cost, index;
	bool is_a{};
};

std::vector<Cost> costs;
int n;

bool connected();
bool divided();

int main()
{
	scanf("%d", &n);
	costs.resize(2 * n);
	for (int i{}; i < n; i++)
	{
		scanf("%d%d", &costs[2 * i].cost, &costs[2 * i + 1].cost);
		costs[2 * i].index = costs[2 * i + 1].index = i;
		costs[2 * i].is_a = true;
	}
	std::sort(costs.begin(), costs.end(),
		[](const auto& a, const auto& b) { return a.cost < b.cost; }
	);
	if (!connected())
	{
		if (costs[n - 1].index != costs[n].index)
			std::swap(costs[n - 1], costs[n]);
		else if (costs[n].cost - costs[n - 2].cost < costs[n + 1].cost - costs[n - 1].cost)
			std::swap(costs[n], costs[n - 2]);
		else
			std::swap(costs[n + 1], costs[n - 1]);
	}
	long long sum{};
	for (int i{}; i < n; i++)
		sum += costs[i].cost;

	printf("%lld\n", sum);

	return 0;
}

bool connected()
{
	if (divided()) return true;
	std::vector<bool> used(n);
	for (int i{}; i < n; i++)
		if (used[costs[i].index])
			return true;
		else
			used[costs[i].index] = true;
	return false;
}

bool divided()
{
	for (int i{1}; i < n; i++)
		if (costs[0].is_a ^ costs[i].is_a)
			return false;
	return true;
}

