int main() {
    int n;
    cin >> n;

    vector<P> a(n), b(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i].first >> b[i].first;
        a[i].second = i;
        b[i].second = i;
    }
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    reverse(b.begin(), b.end());
    int d = n;
    for (int i = 0; i < n; ++i) {
        if (a[i].first > b[i].first) {
            d = i;
            break;
        }
    }
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        ans += min(a[i].first, b[i].first);
    }
    if (d == n || d == 0) {
        cout << ans << "\n";
        return 0;
    }
    vector<int> cnt(n);
    for (int i = 0; i < d; ++i) {
        ++cnt[a[i].second];
        ++cnt[b[i].second];
    }
    for (int i = 0; i < n; ++i) {
        if (cnt[i] == 1) {
            cout << ans << "\n";
            return 0;
        }
    }
    ans = 0;
    if (d == 1 || a[d - 1].second != b[d - 1].second || d == n - 1 || a[d].second != b[d].second) {
        for (int i = 0; i < d - 1; ++i) {
            ans += a[i].first;
        }
        ans += min(a[d - 1].first, b[d].first);
        ans += min(a[d].first, b[d - 1].first);
        for (int i = d + 1; i < n; ++i) {
            ans += b[i].first;
        }
    }
    else {
        long long ans1 = 0, ans2 = 0, ans3 = 1e18;
        for (int i = 0; i < d - 2; ++i) {
            ans1 += a[i].first;
        }
        ans1 += min(a[d - 2].first, b[d].first);
        ans1 += a[d - 1].first;
        ans1 += min(a[d + 1].first, b[d - 1].first);
        for (int i = d + 1; i < n; ++i) {
            ans1 += b[i].first;
        }

        for (int i = 0; i < d - 1; ++i) {
            ans2 += a[i].first;
        }
        ans2 += min(a[d - 1].first, b[d + 1].first);
        ans2 += b[d].first;
        ans2 += min(a[d].first, b[d - 2].first);
        for (int i = d + 2; i < n; ++i) {
            ans2 += b[i].first;
        }
        int ad = d - 2, bd = d + 1;
        while (ad >= 0) {
            if (a[ad].second != b[ad].second) break;
            --ad;
        }
        while (bd < n) {
            if (a[bd].second != b[bd].second) break;
            ++bd;
        }
        if (ad >= 0 && bd < n) {
            ans3 = 0;
            for (int i = 0; i < d; ++i) {
                if (i == ad) continue;
                ans3 += a[i].first;
            }
            ans3 += min(a[ad].first, b[bd].first);
            ans3 += min(a[bd].first, b[ad].first);
            for (int i = d; i < n; ++i) {
                if (i == bd) continue;
                ans3 += b[i].first;
            }
        }

        ans = min({ans1, ans2, ans3});
    }
    cout << ans << "\n";
    return 0;
}

