#define ford(i, ini, lim) for(int i = int(ini); i >= int(lim); i--)

using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int, int> ii;

const int MAX = 1e5 + 5;
int pset[MAX];

int find_set(int i) {
    return pset[i] == i ? i : pset[i] = find_set(pset[i]);
}

inline bool same_set(int a, int b) {
    return find_set(a) == find_set(b);
}

inline void union_sets(int a, int b) {
    pset[find_set(a)] = find_set(b);
}

int main() {
    int n;
    scanf("%d", &n);
    vector<int> A(n), B(n);
    set<ii> sA, sB;
    fori(i, 0, n) {
        scanf("%d %d", &A[i], &B[i]);
        sA.emplace(A[i], i);
        sB.emplace(B[i], i);
    }
    fori(i, 0, n) {
        pset[i] = i;
    }
    ll ans = 0;
    while((int) sA.size() > 1) {
        ii pA = *sA.begin();
        ii pB = *sB.begin();
        if(pA.first < pB.first) { // choose an A
            ans += pA.first;
            auto itB = prev(sB.end());
            if(same_set(pA.second, itB->second)) {
                itB = prev(itB);
            }
            union_sets(pA.second, itB->second);
            sB.erase(itB);
            sA.erase(sA.begin());
        }
        else { // choosen a B
            ans += pB.first;
            auto itA = prev(sA.end());
            if(same_set(pB.second, itA->second)) {
                itA = prev(itA);
            }
            union_sets(pB.second, itA->second);
            sA.erase(itA);
            sB.erase(sB.begin());
        }
    }
    ans += min(sA.begin()->first, sB.begin()->first);
    printf("%lld\n", ans);
    return 0;
}

