		a[i].second = b[i].second = i;
	}
}

inline int cost(int x, int y) {
	return min(a[x - N].first, b[y].first);
}

int find(int x) {
	return dad[x] == x ? x : dad[x] = find(dad[x]);
}

int join(int x, int y, bool f = true) {
	int res = cost(x, y);
	if (f)
		alive.erase(y);
	x = dad[x];
	y = dad[y];	
	if (rnk[x] > rnk[y])
		swap(x, y);
	dad[x] = y;
	rnk[y] += rnk[x] == rnk[y];
	return res; 
}

ll solve() {
	sort(a, a + N);
	sort(b, b + N, greater <pii> ());

	for (int i = 0; i < N; i++) {
		pos[a[i].second] = i;
		alive.insert(i);
	}

	for (int i = 0; i < 2 * N; i++) 
		dad[i] = i;

	for (int i = 0; i < N; i++)
		join(pos[b[i].second] + N, i, false);

	ll sol = 0;
	for (int i = 0; i < N - 1; i++) 
		for (auto it : alive)
			if (find(i + N) != find(it)) {
				sol += join(i + N, it);
				break;
			}

	return sol + cost(2 * N - 1, *alive.begin());
}

