void solve() {
	int n;
	cin >> n;
	vector<pii> inp;
	vector<pii> real_inp;
	for (int i = 0; i < n; ++i) {
		int a, b;
		cin >> a >> b;
		real_inp.push_back({a, b});
		if (a > b) {
			swap(a, b);
		}
		inp.push_back({a, b});
	}

	vector<pii> all;
	for (int i = 0; i < n; ++i) {
		all.push_back({inp[i].ff + inp[i].ss, i});
	}

	sort(all.begin(), all.end());

	set<pii> have_diff;
	set<pii> have_val, rest_val;
	ll sum = 0;

	function<void()> add = [&]() {
		auto it = rest_val.begin();
		sum += it->ff;
		rest_val.erase(it);
	};

	function<void()> change = [&]() {
		auto it = have_diff.begin();
		int val1 = it->ff;
		it = have_val.end();
		--it;
		int val2 = -it->ff;
		if (szof(rest_val)) {
			it = rest_val.begin();
			val2 += it->ff;
		}
		if (!szof(rest_val) || val1 < val2) {
			sum += val1;
			int ind = have_diff.begin()->ss;
			have_diff.erase({-inp[ind].ss, ind});
			have_val.erase({inp[ind].ff + inp[ind].ss, ind});
		} else {
			sum += val2;
			rest_val.erase(rest_val.begin());
			it = have_val.end();
			--it;
			int ind = it->ss;
			have_diff.erase({-inp[ind].ss, ind});
			have_val.erase({inp[ind].ff + inp[ind].ss, ind});
			rest_val.insert({inp[ind].ff, ind});
		}
	};

	if (n % 2 == 0) {
		for (int i = 0; i < n / 2; ++i) {
			int ind = all[i].ss;
			have_diff.insert({-inp[ind].ss, ind});
			have_val.insert({inp[ind].ff + inp[ind].ss, ind});
			sum += inp[ind].ff + inp[ind].ss;
		}
		for (int i = n / 2; i < n; ++i) {
			int ind = all[i].ss;
			rest_val.insert({inp[ind].ff, ind});
		}
	} else {
		for (int i = 0; i <= n / 2; ++i) {
			int ind = all[i].ss;
			have_diff.insert({-inp[ind].ss, ind});
			have_val.insert({inp[ind].ff + inp[ind].ss, ind});
			sum += inp[ind].ff + inp[ind].ss;
		}
		for (int i = n / 2 + 1; i < n; ++i) {
			int ind = all[i].ss;
			rest_val.insert({inp[ind].ff, ind});
		}

		change();
	}

	ll ans = sum;
	while (szof(have_diff) > 1) {
		add();
		change();
		ans = min(ans, sum);
	}

	ll sum1 = 0, sum2 = 0;
	for (int i = 0; i < n; ++i) {
		sum1 += real_inp[i].ff;
		sum2 += real_inp[i].ss;
	}

	ans = min(ans, min(sum1, sum2));

	cout << ans << "\n";
}


