  std::vector<int> A(N), B(N);
  for (int i: range(0, N)) {
    std::cin >> A[i] >> B[i];
  }
  long long ans = inf;
  chmin(ans, std::accumulate(A.begin(), A.end(), 0ll));
  chmin(ans, std::accumulate(B.begin(), B.end(), 0ll));
  std::vector<std::pair<int, int>> vec;
  vec.reserve(2 * N);
  for (int i: range(0, N)) {
    vec.emplace_back(A[i], i);
    vec.emplace_back(B[i], N + i);
  }
  std::sort(vec.begin(), vec.end());
  std::vector<int> order(2 * N);
  for (int i: range(0, 2 * N)) {
    order[vec[i].second] = i;
  }
  long long sum = 0;
  for (int i: range(0, N)) {
    sum += vec[i].first;
  }
  for (int i: range(0, N)) {
    if (order[i] >= N && order[N + i] >= N) {
      chmin(ans, sum);
    }
    else if (order[i] >= N) {
      int idx = N;
      if (order[i] == N) ++idx;
      chmin(ans, sum - B[i] + vec[idx].first);
    }
    else if (order[N + i] >= N) {
      int idx = N;
      if (order[N + i] == N) ++idx;
      chmin(ans, sum - A[i] + vec[idx].first);
    }
    else {
      chmin(ans, sum - A[i] - B[i] + vec[N].first + vec[N + 1].first);
    }
  }
  std::cout << ans << '\n';
  return 0;
}

