    int mni = min(a[i], b[i]);
    int mnj = min(a[j], b[j]);
    if (mni != mnj) {
      return mni > mnj;
    }
    return i < j;
  };
  auto cmp_mx = [](int i, int j) {
    int mxi = max(a[i], b[i]);
    int mxj = max(a[j], b[j]);
    if (mxi != mxj) {
      return mxi < mxj;
    }
    return i < j;
  };
