int main() {
	ll N, a, b;
	cin >> N;

	vector<pair<ll, ll>> VP(N);
	vector<ll> scr(2 * N);
	ll LS = 0, RS = 0;
	for (int i = 0;i < N;i++) {
		cin >> a >> b;
		LS += a;
		RS += b;
		VP[i] = { a,b };
		scr[i * 2] = a;
		scr[i * 2 + 1] = b;
	}
	sort(all(scr));

	ll C, CR = 0, CRR, ans = min(LS, RS);
	for (int i = 0;i < N;i++)CR += scr[i];
	CRR = CR;
	for (int i = 0;i < N;i++) {
		tie(a, b) = VP[i];
		if (a > b)swap(a, b);
		C = scr[N - 1];
		if (a < C) {
			if (b > C)CR += b - C;
		}
		else if (a == C) {
			C = scr[N - 2];
			if (b > C) {
				CR += b - C;
			}
		}
		else {
			CR += a - C;
			C = scr[N - 2];
			CR += b - C;
		}
		ans = min(ans, CR);
		CR = CRR;
	}
	cout << ans << endl;
}

