    X.pb({AB[i].s, -(i+1)});
    left += AB[i].f;
    right += AB[i].s;
  }
  sort(X.begin(), X.end());
  ll ans = min(left, right);
  ll sum = 0;
  set<ll> used;
  bool ok = 0;
  ll lastL = -1, lastR = -1;
  rep(i, N){
    sum += X[i].f;
    if(used.count(X[i].s) || used.count(-X[i].s)) ok = 1;
    used.insert(X[i].s);
    if(X[i].s > 0) lastL = i;
    else lastR = i;
  }
  if(ok == 0 && lastL != -1 && lastR != -1){
    //lastLを諦める
    ll res1 = sum;
    res1 -= X[lastL].f;
    if(X[lastL].s == -X[N].s){
      res1 += X[N+1].f;
    }else{
      res1 += X[N].f;
    }
    //lasrRを諦める
    ll res2 = sum;
    res2 -= X[lastR].f;
    if(X[lastR].s == -X[N].s){
      res2 += X[N+1].f;
    }else{
      res2 += X[N].f;
    }

    chmin(ans, res1);
    chmin(ans, res2);
  }else{
    chmin(ans, sum);
  }
  cout << ans << endl;
}
int main(){
  cin >> N;
  AB.resize(N);
  rep(i, N) cin >> AB[i].f >> AB[i].s;
  solve();
}

