auto solve(ll n, const V<PAIR>& v) {

	set<pair<PAIR, PAIR>> s;
	REP(i, n) {
		s.emplace(PAIR{v[i].first,v[i].second}, PAIR{i,1});
		s.emplace(PAIR{v[i].second,v[i].first}, PAIR{i,2});
	}

	VL state(n); ll cnt = 0;
	ll ans = 0;
	ll flg = 0;
	REPC(p, s) {
		state[p.second.first] += p.second.second;
		ans += p.first.first;
		flg |= p.second.second;
		++cnt;
		if (cnt == n) { break; }
	}
	if (flg != 3) {
		dump("all");
		return ans;
	}
	REPC(k, state)if (!(k ^ 3)) {
		dump("comp");
		return ans;
	}

	dump(ans);
	VL t_out; t_out.reserve(n);
	VL t_ok; t_ok.reserve(n);
	REP(i, n) {
		t_out.emplace_back((!(state[i] ^ 1)) ? v[i].second : v[i].first);
		t_ok.emplace_back((!(state[i] ^ 1)) ? v[i].first : v[i].second);
	}
	ll mx_i = std::max_element(ALL(t_ok)) - t_ok.begin();
	ll mn_i = std::min_element(ALL(t_out)) - t_out.begin();
	ll mx = t_ok[mx_i];
	ll mn = t_out[mn_i];
	if (mx_i != mn_i) {
		return ans - mx + mn;
	}
	ll mx2 = -1, mn2 = 1e10;
	REP(i, n) if (i != mx_i) {
		chmax(mx2, t_ok[i]);
		chmin(mn2, t_out[i]);
	}
	dump(mx, mx2, mn, mn2);
	ans = std::min(ans - mx + mn2, ans - mx2 + mn);
	return ans;
}

