            posa[cur] = posa[v];
            posb[cur] = posa[u];
            aa.pop_back();
            bb.pop_back();
        }
        else {
            pii bn1 = bb[ SZ(bb) - 1 ];
            pii bn2 = bb[ SZ(bb) - 2 ];
            ans += min(aa.back().first, bn2.first);
            int u = aa.back().second;
