	cin >> N;
	for (int i = 1; i <= N; i++) {
		int A, B;
		cin >> A >> B;
		Q.push(make_tuple(-A, -B, i));
		set_tree(i, B);
	}
	while (!Q.empty()) {
		int v, idx, temp;
		tie(v, temp, idx) = Q.top();
		Q.pop();
		v = -v;
		if (temp = get_value(idx)) {
			set_tree(idx, 0);
			if (tree[1].first) {
				ans += min(tree[1].first, v);
				set_tree(tree[1].second, temp);
				Q.push(make_tuple(-v, -temp, idx));
			}
			else {
				ans += min(v, temp);
			}
		}
	}
	cout << ans << '\n';
	return 0;
}

