struct node
	{
		ll minv,pos;
		node(){minv=INF,pos=0;}
		node operator +(const node t)
		{
			node res;
			if(minv<t.minv)res=*this;
			else res=t;
			return res;
		}
	};
struct Segment_Tree
{
	node t[MAXN<<2|1];
	#define rt t[num]
	void modify(un pos,ll k,un l=1,un r=n,un num=1)
	{
		if(l==r){rt.minv=k,rt.pos=l;return;}
		un mid=(l+r)>>1;
		if(pos<=mid)modify(pos,k,l,mid,num<<1);
		else modify(pos,k,mid+1,r,num<<1|1);
		rt=t[num<<1]+t[num<<1|1];
	}
	node Qmin(un ql,un qr,un l=1,un r=n,un num=1)
	{
		if(ql>qr)return node();
		if(ql<=l&&r<=qr)return rt;
		un mid=(l+r)>>1;node res;
		if(ql<=mid)res=res+Qmin(ql,qr,l,mid,num<<1);
		if(qr>mid)res=res+Qmin(ql,qr,mid+1,r,num<<1|1);
		return res;
	}
}sgt;
