#include <bits/stdc++.h>
using namespace std;

int main() {
    int n; scanf("%d", &n);
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) scanf("%d%d", &a[i], &b[i]);
    long long ans = min(accumulate(a.begin(), a.end(), 0LL), accumulate(b.begin(), b.end(), 0LL));
    vector<pair<int, int>> v;
    for (int i = 0; i < n; ++i) {
        v.emplace_back(a[i], i);
        v.emplace_back(b[i], i);
    }
    sort(v.begin(), v.end());
    vector<vector<int>> pos(n);
    for (int i = 0; i < n + n; ++i) pos[v[i].second].push_back(i);
    vector<long long> pref(n + n + 1, 0);
    for (int i = 0; i < n + n; ++i) pref[i + 1] = pref[i] + v[i].first;
    for (int i = 0; i < n; ++i) {
        assert(pos[i].size() == 2);
        int l = pos[i][0], r = pos[i][1];
        long long res = a[i] + b[i];
        if (l >= n - 2) {
            res += pref[n - 2];
        } else {
            if (r - 1 >= n - 2) res += pref[n - 1] - v[l].first;
            else res = pref[n];
        }
        ans = min(ans, res);
    }
    printf("%lld\n", ans);
    return 0;
}

