		int ax=lower_bound(q+1,q+n*2+1,x)-q,ay=lower_bound(q+ax+1,q+n*2+1,y)-q;
		chmin(ans,x+y+(ax>n-2?s[n-2]:(ay>n-1?s[n-1]-x:s[n]-x-y)));
	}
	cout<<ans;
}

