int ind[N][2],sz[N];
ll pre[N];
void solve() {
    int n;
    scanf("%d",&n);
    ll Asum = 0,Bsum = 0;
    ll ret = 1e18;
    vector<pair<int,int> > v;
    for(int i=0;i<n;++i) {
        scanf("%d %d",&A[i],&B[i]);
        Asum += A[i];
        Bsum += B[i];
        v.push_back(make_pair(A[i],i));
        v.push_back(make_pair(B[i],i));
    }
    sort(v.begin(),v.end());
    ret = min(Asum,Bsum);
    for(int i=0;i<v.size();++i) {
        int id = v[i].second;
        ind[id][sz[id]++] = i+1;
        pre[i+1] = pre[i] + v[i].first;
    }

    for(int i=0;i<n;++i) {
        ll tmp = A[i] + B[i];
        vector<int> pos;
        for(int j=0;j<2;++j) {
            pos.push_back(ind[i][j]);
        }
        assert(pos.size()==2);
        if(pos[0]>pos[1]) {
            swap(pos[0],pos[1]);
        }
        int pp = -1;
        for(int j = n-2;j<=n;++j) {
            int cc = j;
            for(int k = 0;k<2;++k) {
                if(pos[k]<=j) {
                    --cc;
                }
            }
            if(cc==n-2) {
                pp = j;
                break;
            }
        }
        int rem = pp - (n-2);
        ll sum = pre[pp];
        for(int j = 0;j<rem;++j) {
            sum -= v[pos[j]-1].first;
        }
        tmp += sum;
        ret = min(ret,tmp);
    }
    printf("%lld\n", ret);
}
