        SB.insert(pll(B[i], i));
    }
    vi id(n), sz(n);
    forn(i, n) id[i]=i, sz[i]=1;
    auto lookup=[&](int i) -> int {
        while (id[i]!=i) i=id[i];
        return i;
    };
    auto merge=[&](int i, int j) {
        i=lookup(i);
        j=lookup(j);
        if (i==j) return;
        if (sz[i]<sz[j]) swap(i, j);
        sz[i]+=sz[j];
        id[j]=i;
    };
    ll ans=0;
    while (SA.size()>1) {
        if (*SA.begin() > *SB.begin()) swap(A, B), swap(SA, SB);
        pll a=*SA.begin();
        SA.erase(a);
        auto bit=SB.rbegin();
        while (lookup(bit->ss) == lookup(a.ss)) bit++;
        ans += a.ff;
        merge(a.ss, bit->ss);
        SB.erase(*bit);
    }
    ans += min(SA.begin()->ff, SB.begin()->ff);
    cout << ans << '\n';
}

