int main() {
    ios_base::sync_with_stdio(0);
    cin >> n;
    cont (i, n) {
        cin >> a[i][0] >> a[i][1];
        dat[i << 1] = make_pair(a[i][0], i << 1);
        dat[i << 1 | 1] = make_pair(a[i][1], i << 1 | 1);
    }
    sort(dat + 2, dat + 2 * n + 1);
    circ (i, 2, n + 1) {
        int id = dat[i].second >> 1, at = dat[i].second & 1;
        b[id][at] = 1;
    }
    bool flag = 0;
    cont (i, n) {
        if (b[i][0] && b[i][1]) {
            flag = 1;
        } else {
            if (b[i][0]) {
                s0 += a[i][0];
                rs0 += a[i][1] - a[i][0];
                md0 = min(md0, a[i][1] - a[i][0]);
