long long solve(int n, vector<long long>& a, vector<long long>& b){
  using tt = tuple<long long, int, int>;
  vector<tt> c;
  for(int i=0; i<n; i++){
    c.emplace_back(a[i], a[i]==b[i]?0:1, i);
    c.emplace_back(b[i], a[i]==b[i]?0:1, i);
  }
  sort(c.begin(), c.end());

  vector<int> cnt(n);
  for(int i=0; i<n; i++){
    cnt[ get<2>(c[i]) ]++;
  }

  long long ans = min( accumulate(a.begin(), a.end(), 0ll) , accumulate(b.begin(), b.end(), 0ll) );
  if( count(cnt.begin(), cnt.end(), 2) ){
    long long tmp = 0;
    for(int i=0; i<n; i++){
      tmp += get<0>(c[i]);
    }
    ans = min(ans, tmp);
  }else{
    if( get<2>(c[n]) == get<2>(c[n-1]) ){
      {
        long long tmp = get<0>(c[n]);
        for(int i=0; i<n; i++){
          if(i==n-2) continue;
          tmp += get<0>(c[i]);
        }
        ans = min(ans, tmp);
      }
      {
        long long tmp = get<0>(c[n+1]);
        for(int i=0; i<n; i++){
          if(i==n-1) continue;
          tmp += get<0>(c[i]);
        }
        ans = min(ans, tmp);
      }
    }else{
      long long tmp = get<0>(c[n]);
      for(int i=0; i<n-1; i++){
        tmp += get<0>(c[i]);
      }
      ans = min(ans, tmp);
    }

  }
  return ans;
}

