int used[100010];


long long calc(int N,vector<pair<int,int>> &v,int skip1 = -1,int skip2 = -1){
    for(int i=1;i<=N;i++) used[i] = false;
    long long total = 0;
    int pos = 0,neg = 0;
    for(int i=0,j=0;j<N;i++,j++){
        if(i == skip1 || i == skip2){
            j -= 1;
            continue;
        }
        total += v[i].first;
        if(v[i].second > 0){
            pos += 1;
            used[v[i].second] = true;
        }else{
            neg += 1;
            used[-v[i].second] = true;
        }
    }
    bool allUsed = true;
    for(int i=1;i<=N;i++) allUsed &= used[i];
    if(allUsed == false || pos == N || neg == N) return total;
    else return INF;
}
