    }
    sort(v.begin(),v.end());
    long long ans = calc(N,v);
    ans = min(ans,calc(N,v,N-1));
    ans = min(ans,calc(N,v,N-2));
    ans = min(ans,calc(N,v,N-1,N));
    cout<<ans<<endl;
