template<class T> void assign(V<T>& v, int n, const T& a = T()) { v.assign(n, a); }
template<class T, class... Args> void assign(V<T>& v, int n, const Args&... args) { v.resize(n); for (auto&& e : v) assign(e, args...); }


struct QU {
  V<> par, rank, _size;

  QU(int n) : par(n), rank(n), _size(n, 1) { 
    iota(par.begin(), par.end(), 0);
  }

  int find(int a) {
    if (par[a] == a) return a;
    return par[a] = find(par[a]);
  }

  bool same(int a, int b) { return find(a) == find(b); }

  int size(int a) { return _size[find(a)]; }

  void unite(int a, int b) {
    a = find(a), b = find(b);
    if (a == b) return;
    if (rank[a] < rank[b]) {
      par[a] = b;
      _size[b] += _size[a];
    } else {
      par[b] = a;
      _size[a] += _size[b];
    }
    if (rank[a] == rank[b]) rank[a]++;
  }
};

int main() {
  cin.tie(nullptr); ios_base::sync_with_stdio(false);
  int n; cin >> n;
  V<> a(n), b(n); for (int i = 0; i < n; ++i) cin >> a[i] >> b[i];
  V<> va(n); iota(begin(va), end(va), 0);
  V<> vb(n); iota(begin(vb), end(vb), 0);
  V<> v(2 * n); iota(begin(v), end(v), 0);
  sort(rbegin(va), rend(va), [&](int i, int j) { return a[i] < a[j]; });
  sort(rbegin(vb), rend(vb), [&](int i, int j) { return b[i] < b[j]; });
  sort(begin(v), end(v), [&](int i, int j) { return (i < n ? a[i] : b[i - n]) < (j < n ? a[j] : b[j - n]); });
  QU qu(n);
  V<bool> used(2 * n);
  int pa = 0, pb = 0, p = 0;
  lint res = 0;
  for (int i = 0; i < n - 1; ++i) {
    while (used[va[pa]]) ++pa;
    while (used[vb[pb] + n]) ++pb;
    while (used[v[p]]) ++p;
    used[v[p]] = true;
    if (v[p] < n) {
      int qb = pb;
      while (qu.same(v[p], vb[qb])) ++qb;
      res += a[v[p]];
      used[vb[qb] + n] = true;
    } else {
      int qa = pa;
      while  (qu.same(v[p] - n, va[qa])) ++qa;
      res += b[v[p] - n];
      used[va[qa]] = true;
    }
  }
  while (used[va[pa]]) ++pa;
  while (used[vb[pb] + n]) ++pb;
  res += min(a[va[pa]], b[vb[pb]]);
  cout << res << '\n';
}

