    vector<P> sa(n), sb(n);
    vector<ll> ua(n, -1), ub(n, -1);
    UnionFind uf(n);
    REP(i, n){
        ll ta, tb;
        cin >> ta >> tb;
        pq.push(P(ta, i));
        pq.push(P(tb, i+n));
        a[i] = ta;
        b[i] = tb;
        sa[i] = P(ta, i);
        sb[i] = P(tb, i);
    }
    SORT(sa);
    SORT(sb);
    int acnt = 0;
    int bcnt = 0;
    ll ans = 0;
    REP(i, n - 2){
        P tmp = pq.top(); pq.pop();
        if(tmp.second < n){
            if(ub[sb[bcnt].second] != -1) bcnt++;
            if(ub[tmp.second] == sb[bcnt].second){
                ans += sb[bcnt+1].first;
                ua[tmp.second] = sb[bcnt+1].second;
                ub[sb[bcnt+1].second] = tmp.second;
                uf.unite(tmp.second, sb[bcnt+1].second);
            }else{
                ans += sb[bcnt].first;
                ua[tmp.second] = sb[bcnt].second;
                ub[sb[bcnt].second] = tmp.second;
                uf.unite(tmp.second, sb[bcnt].second);
                bcnt++;
            }
        }else{
            tmp.second -= n;
            if(ua[sa[acnt].second] != -1) acnt++;
            if(ua[tmp.second] == sa[acnt].second){
                ans += sa[acnt+1].first;
                ub[tmp.second] = sa[acnt+1].second;
                ua[sa[acnt+1].second] = tmp.second;
                uf.unite(tmp.second, sa[acnt+1].second);
            }else{
                ans += sa[acnt].first;
                ub[tmp.second] = sa[acnt].second;
                ua[sa[acnt].second] = tmp.second;
                uf.unite(tmp.second, sa[acnt].second);
                acnt++;
            }
        }
    }
    ll a1, a2, b1, b2;
    a1 = -1;
    REP(i, n){
        if(ua[i] == -1 && ub[i] == -1){
            a1 = a[i];
            b2 = b[i];
        }else if(ua[i] == -1){
            a2 = a[i];
        }else if(ub[i] == -1){
            b1 = b[i];
        }
    }
    if(a1 == -1){
        a1 = a2 = b1 = b2 = -1;
        REP(i, n){
            if(ua[i] == -1){
                if(a1 == -1){
                    a1 = i;
                }else{
                    a2 = i;
                }
            }
            if(ub[i] == -1){
                if(b1 == -1){
                    b1 = i;
                }else{
                    b2 = i;
                }
            }
        }
        if(uf.find(a1) == uf.find(b1)){
            ans += min(a[a1], b[b1]) + min(a[a2], b[b2]);            
        }else{
            ans += min(a[a1], b[b2]) + min(a[a2], b[b1]);       
        }
    }else{
        ans += min(a1, b1) + min(a2, b2);
    }
    cout << ans << endl;
}

