void solve() {
	int n;
	cin >> n;
	vector<pii> inp;
	vector<pii> real_inp;
	for (int i = 0; i < n; ++i) {
		int a, b;
		cin >> a >> b;
		real_inp.push_back({a, b});
		if (a > b) {
			swap(a, b);
		}
		inp.push_back({a, b});
	}

	vector<pair<pii, int>> all;
	for (int i = 0; i < n; ++i) {
		all.push_back({{inp[i].ff + inp[i].ss, -inp[i].ff}, i});
	}

	sort(all.begin(), all.end());

	set<pii> have_diff;
	set<pair<pii, int>> have_val;
	set<pair<pii, int>> rest_val;
	ll sum = 0;
	set<pii> part1, part2;

	function<void()> add = [&]() {
		auto it = rest_val.begin();
		sum += it->ff.ff;
		int ind = it->ss;
		part1.insert({inp[ind].ss, ind});
		rest_val.erase(it);
	};

	function<void()> change = [&]() {
		auto it = have_diff.begin();
		int val1 = it->ff;
		auto it2 = have_val.end();
		--it2;
		int val2 = -it2->ff.ff;
		if (szof(rest_val)) {
			it2 = rest_val.begin();
			val2 += it2->ff.ff;
		}
		if (!szof(rest_val) || val1 < val2) {
			sum += val1;
			int ind = have_diff.begin()->ss;
			part2.erase({-inp[ind].ss, ind});
			part1.insert({inp[ind].ss, ind});
			have_diff.erase({-inp[ind].ss, ind});
			have_val.erase({{inp[ind].ff + inp[ind].ss, -inp[ind].ff}, ind});
		} else {
			sum += val2;
			int ind = rest_val.begin()->ss;
			part1.insert({inp[ind].ss, ind});
			rest_val.erase(rest_val.begin());
			it2 = have_val.end();
			--it2;
			ind = it2->ss;
			part2.erase({-inp[ind].ss, ind});
			have_diff.erase({-inp[ind].ss, ind});
			have_val.erase({{inp[ind].ff + inp[ind].ss, -inp[ind].ff}, ind});
			rest_val.insert({{inp[ind].ff, inp[ind].ss}, ind});
		}
	};

	if (n % 2 == 0) {
		for (int i = 0; i < n / 2; ++i) {
			int ind = all[i].ss;
			have_diff.insert({-inp[ind].ss, ind});
			part2.insert({-inp[ind].ss, ind});
			have_val.insert({{inp[ind].ff + inp[ind].ss, -inp[ind].ff}, ind});
			sum += inp[ind].ff + inp[ind].ss;
		}
		for (int i = n / 2; i < n; ++i) {
			int ind = all[i].ss;
			rest_val.insert({{inp[ind].ff, inp[ind].ss}, ind});
		}
	} else {
		for (int i = 0; i <= n / 2; ++i) {
			int ind = all[i].ss;
			have_diff.insert({-inp[ind].ss, ind});
			part2.insert({-inp[ind].ss, ind});
			have_val.insert({{inp[ind].ff + inp[ind].ss, -inp[ind].ff}, ind});
			sum += inp[ind].ff + inp[ind].ss;
		}
		for (int i = n / 2 + 1; i < n; ++i) {
			int ind = all[i].ss;
			rest_val.insert({{inp[ind].ff, inp[ind].ss}, ind});
		}

		change();
	}

	ll ans = sum;
	// cerr << sum << endl;
	while (szof(have_diff) > 1) {
		add();
		change();
		// cerr << "part1" << endl;
		// for (pii p : part1) {
		// 	cerr << p.ss + 1 << " ";
		// }
		// cerr << endl;

		// cerr << "part2" << endl;
		// for (pii p : part2) {
		// 	cerr << p.ss + 1 << " ";
		// }
		// cerr << endl;
		while (szof(part1) && szof(part2) && part1.begin()->ff + part2.begin()->ff < 0) {
			sum += part1.begin()->ff + part2.begin()->ff;
			int ind1 = part1.begin()->ss;
			int ind2 = part2.begin()->ss;
			part1.erase({inp[ind1].ss, ind1});
			part2.erase({-inp[ind2].ss, ind2});

			part1.insert({inp[ind2].ss, ind2});
			part2.insert({-inp[ind1].ss, ind1});			

			have_diff.erase({-inp[ind2].ss, ind2});
			have_val.erase({{inp[ind2].ff + inp[ind2].ss, -inp[ind2].ff}, ind2});

			have_diff.insert({-inp[ind1].ss, ind1});
			have_val.insert({{inp[ind1].ff + inp[ind1].ss, -inp[ind1].ff}, ind1});
		}
		// cerr << "part1" << endl;
		// for (pii p : part1) {
		// 	cerr << p.ss + 1 << " ";
		// }
		// cerr << endl;

		// cerr << "part2" << endl;
		// for (pii p : part2) {
		// 	cerr << p.ss + 1 << " ";
		// }
		// cerr << endl;
		ans = min(ans, sum);
		// cerr << sum << endl;
	}

	ll sum1 = 0, sum2 = 0;
	for (int i = 0; i < n; ++i) {
		sum1 += real_inp[i].ff;
		sum2 += real_inp[i].ss;
	}

	ans = min(ans, min(sum1, sum2));

	cout << ans << "\n";
}


