ll solve3(V<t2> ablist)
{
    V<ll> idxs;
    idxs.pb(0); idxs.pb(1); idxs.pb(2);

    ll ret = 1e18;

    do {
        ll total = 0;
        total += min(get<0>(ablist[idxs[0]]), get<1>(ablist[idxs[1]]));
        total += min(get<0>(ablist[idxs[1]]), get<1>(ablist[idxs[2]]));
        total += min(get<0>(ablist[idxs[2]]), get<1>(ablist[idxs[0]]));
        ret = min(ret, total);
    } while (next_permutation(ALL(idxs)));

    return ret;
}

ll solve(V<t3> vlist, ll n, ll idx_x, ll idx_y)
{
    t3 tmp = vlist[idx_x];
    vlist[idx_x] = vlist[idx_y];
    vlist[idx_y] = tmp;

    ll cnts[2] = {};
    set<ll> idxs;
    ll total = 0;

    rep (i, n) {
        ll val = get<0>(vlist[i]);
        ll idx = get<1>(vlist[i]);
        ll type = get<2>(vlist[i]);
        total += val;
        idxs.insert(idx);
        cnts[type]++;
    }

    if (cnts[0] == n) return total;
    if (cnts[1] == n) return total;
    if (idxs.size() < n) return total;
    return 1e18;
}

