using namespace std;

const int N = 100'009;

int a[N];
int b[N];
int ab[N];
int o[N];

int main() {
  int n;
  scanf("%d", &n);
  assert(n != 2);
  long long sa = 0, sb = 0;
  for (int i = 0; i < n; ++i) {
    scanf("%d %d", a + i, b + i);
    sa += a[i];
    sb += b[i];
    ab[i] = a[i] + b[i];
  }
  long long ans = min(sa, sb);
  if (n % 2 == 0) {
    sort(ab, ab + n);
    long long cur = 0;
    for (int i = 0; i < n / 2; ++i) {
      cur += ab[i];
    }
    ans = min(ans, cur);
  }
  if (n > 2) {
    for (int i = 0; i < n; ++i) {
      o[i] = i;
    }
    sort(o, o + n, [](int i, int j) {
      int mni = min(a[i], b[i]);
      int mnj = min(a[j], b[j]);
      return mni != mnj ? mni > mnj : i < j;
    });
    auto cmp = [](int i, int j) {
      int mxi = max(a[i], b[i]);
      int mxj = max(a[j], b[j]);
      return mxi != mxj ? mxi < mxj : i < j;
    };
    set<int, decltype(cmp)> s(cmp);
    long long cur = 0;
    int k = (n - 1) / 2;
    for (int i = k; i < n; ++i) {
      cur += min(a[o[i]], b[o[i]]);
      s.insert(o[i]);
    }
    while ((int)s.size() > k) {
      s.erase(*s.rbegin());
    }
    for (int e : s) {
      cur += max(a[e], b[e]);
    }
    ans = min(ans, cur);
    for (int i = k - 1; i >= 1; --i) {
      cur += a[o[i]] + b[o[i]];
      s.insert(o[i]);
      for (int j = 0; j < 2; ++j) {
        cur -= max(a[*s.rbegin()], b[*s.rbegin()]);
        s.erase(*s.rbegin());
      }
      ans = min(ans, cur);
    }
  }
  printf("%lld\n", ans);
}

