typedef long long ll;
const int MAXN = 100005;
struct ii {
	ll a, b;
	bool operator < (ii o) const {
		return tie(a, b) < tie(o.a, o.b);
	}
};

ll N;
ii arr[2*MAXN], pos[MAXN];

int main() {
	ios::sync_with_stdio(0); cin.tie(0);

	cin >> N;
	ll a = 0, b = 0;
	for (int i = 0; i < N; i++) {
		cin >> arr[2*i].a >> arr[2*i|1].a;
		pos[i] = {arr[2*i].a, arr[2*i|1].a};
		a += arr[2*i].a;
		b += arr[2*i|1].a;
		arr[2*i].b = arr[2*i|1].b = i;
	}
	sort(arr, arr+2*N);

	multiset<ii> s;
	ll sum = 0;
	for (int i = 0; i < N; i++) s.insert(arr[i]), sum += arr[i].a;

	ll ans = min(a, b);
	for (int i = 0;i < N; i++) {
		if (s.find({pos[i].a, i}) != s.end()) {
			s.erase(s.find({pos[i].a, i}));
			sum -= pos[i].a;
		}
		if (s.find({pos[i].b, i}) != s.end()) {
			s.erase(s.find({pos[i].b, i}));
			sum -= pos[i].b;
		}
		vector<ii> keluar;
		while ((int)s.size() > N-2) {
			sum -= s.rbegin()->a;
			keluar.push_back(*s.rbegin());
			s.erase(prev(s.end()));
		}
		s.insert({pos[i].a, i});
		s.insert({pos[i].b, i});
		sum += pos[i].a + pos[i].b;
		ans = min(ans, sum);

		for (auto j: keluar) {
			s.insert(j);
			sum += j.a;
		}
		while ((int)s.size() > N) {
			sum -= s.rbegin()->a;
			s.erase(prev(s.end()));
		}
	}
	cout << ans << "\n";

	return 0;
}

