using namespace std;
typedef long long ll;

void solve(long long N, vector<long long> A, vector<long long> B){
	vector<pair<ll, ll>> C;
	vector<bool> used(2 * N);
	for(int i = 0; i < N; ++i) {
		C.push_back(make_pair(A[i], i));
		C.push_back(make_pair(B[i], i + N));
	}
	sort(C.begin(), C.end());
	ll res = 0;
	for(int i = 0; i < N - 1; ++i) {
		res += C[i].first;
		used[C[i].second] = true;
	}
	ll g = 0, al = 0, be = 0;
	for(int i = 0; i < N; ++i) {
		if(!used[i] && !used[i + N]) {
			++g;
		} else if(!used[i]) {
			++al;
		} else if(!used[i + N]) {
			++be;
		}
	}
	ll mn = (ll)1e18;
	for(int i = 0; i < N; ++i) {
		if (!used[i] && !used[i + N]) {
			if (g > 1 || al == 0) {
				mn = min(mn, A[i]);
			}
			if (g > 1 || be == 0) {
				mn = min(mn, B[i]);
			}
		} else {
			if(!used[i]) {
				mn = min(mn, A[i]);
			}
			if(!used[i+N]) {
				mn = min(mn, B[i]);
			}
		}
	}
	cerr << mn << endl;
	res += mn;
	cout << res << endl;
}

int main(){	
	long long N;
	scanf("%lld",&N);
	vector<long long> B(N-1+1);
	vector<long long> A(N-1+1);
	for(int i = 0 ; i <= N-1 ; i++){
		scanf("%lld",&A[i]);
		scanf("%lld",&B[i]);
	}
	solve(N, A, B);
	return 0;
}

