        }
    }
    reverse(b + 1, b + n + 1);
    reverse(a + 1, a + n + 1);
    for (int i = 0; i < N; i++) t[i] = 0;
    for (int i = 1; i <= n; i++){
        s1[i] = s1[i - 1] + a[i].F;
        s2[i] = s2[i - 1] + b[i].F;
    }
    for (int i = 1; i <= n; i++){
        inc(b[i].S, 1);
        if (a[i].F > b[i].F) break;
        if (sum(a[i].S) == a[i].S){
            if (i != n){
              //  if (a[i + 1].F > b[i + 1].F && a[i + 1].S == b[i + 1].S) cout << "!!" << endl;
                if (a[i + 1].S == b[i + 1].S){
                    if (i + 2 <= n) ans = min(ans, s1[i - 1] + s2[n] - s2[i + 2] + min(a[i].F, b[i + 2].F) + min(a[i + 1].F, b[i].F) + b[i + 1].F);
                    if (i + 2 <= n) ans = min(ans, s1[i - 1] + s2[n] - s2[i + 1] + min(a[i].F, b[i + 1].F) + min(a[i + 2].F, b[i].F));
                } else
                ans = min(ans, s1[i - 1] + s2[n] - s2[i + 1] + min(a[i].F, b[i + 1].F) + min(a[i + 1].F, b[i].F));
            }

          // cout << ans << endl;
        } else{
            ans = min(ans, s1[i] + s2[n] - s2[i]);
        }
    }
    res = 0;
    for (int i = 1; i <= n; i++) res += min(a[i].F, b[i].F);
    int cnt = 0;
    for (int i = 1; i <= n; i++){
        if (a[i].F == b[i].F){
            cnt++;
        }
    }
    if (cnt > 1){
        cout << res;
        return 0;
    }
    if (a[1].F > b[1].F){
        ans = min(ans, s2[n]);
    }
    if (a[n].F < b[n].F){
        ans = min(ans, s1[n]);
    }
    cout << ans;
}

