    rep(i, n) {
        int a, b;
        cin >> a >> b;
        x[i*2] = make_tuple(a, i, 0);
        x[i*2+1] = make_tuple(b, i, 1);
    }
    sort(x.begin(), x.end());

    bool a, b; //A, Bを使ったか
    a = b = false;
    int ans = 0;
    bool dup = false; //A, Bの両方を使う頂点があるか
    set<int> s;
