struct node{
	ll X,Y;
};
inline bool operator < (node p,node q){if(p.X!=q.X)return p.X<q.X;else return p.Y>q.Y;} 
struct nd{
	ll X,Y;
};
inline bool operator < (nd p,nd q){if(p.Y!=q.Y)return p.Y<q.Y;else return p.X>q.X;}
multiset<node> q1;
multiset<nd> q2;
multiset<node> q3;
multiset<nd> q4;
inline void Solve()
{	ll ans=1e18;
	ll res=0;
	while(q1.size()>1)
	{	
		node tmp=*q1.begin();
		q1.erase(q1.find(tmp));
		nd tmp2;tmp2.X=tmp.X;tmp2.Y=tmp.Y;
		q2.erase(q2.find(tmp2));
		nd tmp3=*q2.rbegin();
		q2.erase(q2.find(tmp3));
		q1.erase(q1.find((node){tmp3.X,tmp3.Y}));
		res+=min(tmp.X,tmp3.Y);
		node tmp4=(node){tmp3.X,tmp.Y};
		q1.insert(tmp4);
		nd tmp5;tmp5.X=tmp4.X;tmp5.Y=tmp4.Y;
		q2.insert(tmp5);
	}node tt=*q1.begin();
	res+=min(tt.X,tt.Y);ans=res;
	res=0;
	while(q4.size()>1)
	{
		nd tmp=*q4.begin();
		q4.erase(q4.find(tmp));
		node tmp2;tmp2.X=tmp.X;tmp2.Y=tmp.Y;
		q3.erase(q3.find(tmp2));
		node tmp3=*q3.rbegin();
		q3.erase(q3.find(tmp3));
