template <class T> void chmin(T& x, T y) { if (x > y) x = y; }
int main() {
    int N; cin >> N;
    vector<int> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i] >> B[i];
    Int ans = 1e18;
    chmin(ans, accumulate(begin(A), end(A), 0LL));
    chmin(ans, accumulate(begin(B), end(B), 0LL));
    vector<tuple<int, int, int>> C;
    for (int i = 0; i < N; i++) {
        C.emplace_back(A[i], i, 0);
        C.emplace_back(B[i], i, 1);
    }
    sort(begin(C), end(C));
    vector<int> used(N);
    Int sum = 0;
    bool ok = false;
    for (int i = 0; i < N; i++) {
        int val, idx, t;
        tie(val, idx, t) = C[i];
        sum += val;
        used[idx] |= 1 << t;
    }
    for (int u : used) if (u == 3) ok = true;
    if (ok) {
        chmin(ans, sum);
    } else {
        for (int i = 0; i < N; i++) {
            int last = get<0>(C[N-1]);
            if (get<1>(C[N-1]) == i) {
                last = get<0>(C[N-2]);
            }
            if (used[i] == 1) {
                chmin(ans, sum + B[i] - last);
            } else {
                chmin(ans, sum + A[i] - last);
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

