using namespace std;

int n;
int a[100000];
int b[100000];
int p[100000];
long long s;
long long ans;

void solve() {
  multiset<pair<int, int>> ms;
  for (int i = 0; i < n; i++) {
    ms.emplace(b[i], i);
    if (a[p[0]] > a[i]) {
      p[0] = i;
    }
  }
  ms.erase(make_pair(b[p[0]], p[0]));
  for (int i = 0; i + 1 < n; i++) {
    auto l = ms.begin();
    auto r = prev(ms.end());
    if (abs(l->first - a[p[i]]) > abs(r->first - a[p[i]])) {
      p[i + 1] = l->second;
      ms.erase(l);
    } else {
      p[i + 1] = r->second;
      ms.erase(r);
    }
  }
  s = 0;
  for (int i = 0; i < n; i++) {
    int x = p[i];
    int y = p[(i + 1) % n];
    s += min(a[x], b[y]);
  }
  ans = min(ans, s);
}

void link(int i, int j) {
  p[i] = j;
  s += min(a[i], b[j]);
}

void cut(int i) {
  int j = p[i];
  s -= min(a[i], b[j]);
}

unsigned xor64(void) {
  static unsigned long long x = 88172645463325252ULL;
  x = x ^ (x << 13); x = x ^ (x >> 7);
  return x = x ^ (x << 17);
}

void exec() {
  for (int ii = 0; ii < 10000000; ii++) {
    int i = xor64() % n;
    int j = xor64() % n;
    if (i == j) continue;
    int x = p[i];
    int y = p[j];
    cut(i);
    cut(j);
    link(i, y);
    link(j, x);
    if (ans < s) {
      cut(i);
      cut(j);
      link(i, x);
      link(j, y);
    } else if (ans > s) {
      ans = s;
    }
  }
}



