    scanf("%d %d", &a[i], &b[i]);
  }
  solve();
  exec();
  for (int i = 0; i < n; i++) {
    swap(a[i], b[i]);
    p[i] = 0;
  }
  solve();
  exec();
  printf("%lld\n", ans);
}

