int n, a[N], b[N];
ll tot, suma, sumb, sum, res;
pli all[N];
bool vis[N];

int main() {
    cin >> n;
    rep(i, 1, n) {
        scanf("%d%d", &a[i], &b[i]);
        tot += a[i] + b[i];
        suma += a[i], sumb += b[i];
        all[i << 1] = make_pair(a[i], i);
        all[i << 1 | 1] = make_pair(b[i], i);
    }
    sort(all + 1, all + (n << 1) + 2, greater<pli>());
    bool ff = 0;
    res = max(suma, sumb);
    rep(i, 1, n) {
        if (vis[all[i].second]) {
            ff = 1;
        }
        vis[all[i].second] = 1;
        sum += all[i].first;
    }
    if (ff) {
        res = max(res, sum);
    } else {
        rep(i, n + 1, n << 1) {
            if (all[n].second == all[i].second)
                res = max(res, sum + all[i].first - all[n - 1].first);
            else
                res = max(res, sum + all[i].first - all[n].first);
        }
    }
    printf("%lld\n", tot - res);
    return 0;
}

