#include <bits/stdc++.h>
using namespace std;

typedef pair <int, int> ii;
typedef long long ll;

const int Maxn = 100005;

int n;
int A[Maxn], B[Maxn];
vector <ii> seq;
set <ii> S[2];
ll my[2];
ll suma, sumb;
int wh[2 * Maxn];

void Fix()
{
    while (S[0].size() > n - 2) {
        set <ii>::iterator it = S[0].end(); it--;
        S[1].insert(*it); my[1] += it->first;
        wh[it->second] = 1;
        my[0] -= it->first; S[0].erase(it);
    }
    while (S[0].size() < n - 2) {
        set <ii>::iterator it = S[1].begin();
        S[0].insert(*it); my[0] += it->first;
        wh[it->second] = 0;
        my[1] -= it->first; S[1].erase(it);
    }
}

int main()
{
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &A[i], &B[i]);
        seq.push_back(ii(A[i], 2 * i));
        seq.push_back(ii(B[i], 2 * i + 1));
        suma += A[i]; sumb += B[i];
    }
    ll res = min(suma, sumb);
    sort(seq.begin(), seq.end());
    for (int i = 0; i < seq.size(); i++) {
        wh[seq[i].second] = i < n - 2? 0: 1;
        my[wh[seq[i].second]] += seq[i].first;
        S[wh[seq[i].second]].insert(seq[i]);
    }
    for (int i = 0; i < n; i++) {
        int inda = wh[2 * i], indb = wh[2 * i + 1];
        my[inda] -= A[i]; S[inda].erase(ii(A[i], 2 * i));
        my[indb] -= B[i]; S[indb].erase(ii(B[i], 2 * i + 1));
        Fix();
        res = min(res, ll(A[i]) + ll(B[i]) + my[0]);
        my[inda] += A[i]; S[inda].insert(ii(A[i], 2 * i));
        my[indb] += B[i]; S[indb].insert(ii(B[i], 2 * i + 1));
        Fix();
    }
    printf("%lld\n", res);
    return 0;
}

