const int MAX = 100000;
int main() {
	int N, A, B;
	static pair<pair<int, int>, int> G[MAX], G2[MAX];
	cin >> N;
	for (int i = 0;i < N;++ i) {
		cin >> A >> B;
		G[i] = make_pair(make_pair(A, B), i);
		G2[i] = make_pair(make_pair(B, A), i);
	}
	sort(G, G+N);
	sort(G2, G2+N);
	int64_t BSum = 0;
	for (int i = 0;i < N;++ i) BSum += G[i].first.second;

	int64_t ans = BSum, tmp = ans;
	if (G[0].second == G2[N - 1].second) {
		ans = min(ans, tmp + G[0].first.first - G2[N - 2].first.first);
	}
	for (int i = 0, j = 0;i < N;++ i) {
		tmp += G[i].first.first;
		while (j < N && (G2[j].first.first < G[i].first.first || G2[j].second == -1)) ++ j;
		if (j >= N) break;
		if (G2[j].second == G[i].second) {
			if (j >= N - 1) break;
			G2[j + 1].second = -1;
			tmp -= G2[N - i - 1].first.first;
		} else {
			G2[j].second = -1;
			tmp -= G2[N - i - 1].first.first;
		}
		if (i != 0 || G[0].second != G2[N - 1].second) ans = min(ans, tmp);
	}
	cout << ans;
	return 0;
}
