long long solve(const vector<long long> &A, const vector<long long> &B){
  //cerr << "-----------------------solve-------------------------" << endl;
  int N = A.size();
  priority_queue<pair<long long,int>> pq_a, pq_b;
  vector<int> I(N);
  iota(I.begin(), I.end(), 0);
  for(int i = 0; i < N; ++i){
    pq_a.emplace(A[i],i);
    pq_b.emplace(-B[i],i);
  }
  long long ret = 0;
  for(int i = 0; i < N-1; ++i){
    auto a = pq_a.top(), b = pq_b.top();
    pq_a.pop(), pq_b.pop();
    if(I[a.second] == I[b.second]){
      auto b_ = pq_b.top();
      pq_b.pop();
      b = b_;
    }
    //cerr << a.first << " " << b.first << endl;
    ret += min(a.first,-b.first);
    I[b.second] = I[a.second];
  }
  ret += min(pq_a.top().first,-pq_b.top().first);
  //cerr << "ret = " << ret << endl;
  return ret;
}

int main(){
  int N;
  cin >> N;
  vector<long long> A(N), B(N);
  for(int i = 0; i < N; ++i){
    cin >> A[i] >> B[i];
  }
  cerr << solve(A,B) << " " << solve(B,A) << endl;
  cout << min(solve(A,B),solve(B,A)) << endl;
  return 0;
}

