std::priority_queue<std::pair<int, int>> que;

int main() {
  // freopen("data", "r", stdin);
  scanf("%d", &n);
  for (int i = 1; i <= n; ++i) {
    scanf("%d %d", A + i, B + i);
    tmp1 += A[i], tmp2 += B[i];
  }
  ans = std::min(tmp1, tmp2);
  for (int i = 1; i <= n; ++i) {
    if (que.size() >= n && que.top().first > A[i]) {
      sum -= que.top().first;
      vis[que.top().second] = 0;
      que.pop();
    }
    if (que.size() < n) {
      sum += A[i];
      vis[i] = 1;
      que.push({ A[i], i });
    }
    if (que.size() >= n && que.top().first > B[i]) {
      sum -= que.top().first;
      vis[que.top().second] = 0;
      que.pop();
    }
    if (que.size() < n) {
      sum += B[i];
      vis[i + n] = 1;
      que.push({ B[i], i + n });
    }
  }
  sum2 = sum3 = sum;
  tmp1 = que.top().first;
  que.pop();
  sum2 -= tmp1;
  tmp2 = que.top().first;
  que.pop();
  sum3 -= tmp1 + tmp2;
  for (int i = 1; i <= n; ++i) {
    if (vis[i] && vis[i + n]) {
      ans = std::min(ans, sum);
    } else if (vis[i]) {
      ans = std::min(ans, sum2 + B[i]);
    } else if (vis[i + n]) {
      ans = std::min(ans, sum2 + A[i]);
    } else {
