struct A
{
  A(int a = 0, int b = 0, int i = 0)
    : a(a), b(b), i(i)
  {}
  int a, b, i;
};

int main() {
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);
  int n;
  std::cin >> n;
  auto f1 = [](const A& x, const A &y) {
    if (x.a == y.a)
      return x.i < y.i;
    return x.a < y.a;
  };
  auto f2 = [](const A& x, const A &y) {
    if (x.b == y.b)
      return x.i > y.i;
    return x.b > y.b;
  };
  std::set<A, decltype(f1)> aa(f1);
  std::set<A, decltype(f2)> bb(f2);
  for (int i = 0; i < n; i++) {
    int a, b;
    std::cin >> a >> b;
    A x(a, b, i);
    aa.insert(x);
    bb.insert(x);
  }
  long long sum = 0;
  int idxs = n;
  for (int i = 0; i < n - 1; i++) {
    auto ita = aa.begin();
    auto itb = bb.begin();
    A x = *ita;
    A y = *itb;
    if (x.i == y.i) {
      auto nita = ita;
      auto nitb = itb;
      nita++; nitb++;
      if (std::abs(nitb->b - ita->a) > std::abs(itb->b - nita->a)) {
        itb = nitb;
      } else {
        ita = nita;
      }
    }
    auto ita2 = aa.end();
    auto itb2 = bb.end();
    ita2--; itb2--;
    x = *ita2;
    y = *itb2;
    if (x.i == y.i) {
      auto nita2 = ita2;
      auto nitb2 = itb2;
      nita2--; nitb2--;
      if (std::abs(nitb2->b - ita2->a) > std::abs(itb2->b - nita2->a)) {
        itb2 = nitb2;
      }
      else {
        ita2 = nita2;
      }
    }
    if (std::abs(itb2->b - ita2->a) > std::abs(itb->b - ita->a)) {
      ita = ita2;
      itb = itb2;
    }
    x = *ita;
    y = *itb;
    if (x.i != y.i) {
      aa.erase(ita);
      aa.erase(y);
      bb.erase(itb);
      bb.erase(x);
      sum += std::min(x.a, y.b);
      A xy = A(y.a, x.b, idxs++);
      aa.insert(xy);
      bb.insert(xy);
    }
    else {
      throw 1;
    }
  }
  std::cout << sum + std::min(aa.begin()->a, aa.begin()->b) << std::endl;
}

