int main() {
	int n; reader(n);
	vector<Pll> vp;
	vector<pair<ll, int>> vp2;
	FOR(i, n) {
		ll a, b; reader(a, b);
		vp.emplace_back(a, b);
		vp2.emplace_back(a, i + 1);
		vp2.emplace_back(b, -i - 1);
	}
	sort(vp2.begin(), vp2.end());
	int lc = 0, rc = 0;
	ll cnt = 0;
	ll sm = 0;
	FOR(i, n) {
		sm += vp2[i].first;
		if (vp2[i].second > 0) lc++;
		else rc++;
		cnt += abs(vp2[i].second);
	}
	if (cnt == ll(n) * (n + 1) / 2 && lc > 0 && rc > 0) {
		ll curAns = ll(1e16);
