	int sgn = 1;
	char ch;
	x = 0;
	for (ch = getchar(); (ch < '0' || ch > '9') && ch != '-'; ch = getchar()) ;
	if (ch == '-') ch = getchar(), sgn = -1;
	for (; '0' <= ch && ch <= '9'; ch = getchar()) x = x * 10 + ch - '0';
	x *= sgn;
}

template <class T>
void write (T x) {
	if (x < 0) putchar('-'), write(-x);
	else if (x < 10) putchar(x + '0');
	else write(x / 10), putchar(x % 10 + '0');
}

struct node {
	int id;
	long long val;
	bool operator < (node rhs) const {
		return val < rhs.val;
	}
} vec[N << 1];

int n;
bool ina[N], inb[N];
long long a[N], b[N], ans = inf, sum = 0ll, sum1 = 0ll, sum2 = 0ll;
int main () {
	read(n);
	for (int i = 1; i <= n; i++) {
		vec[i].id = i, read(vec[i].val);
		sum1 += (a[i] = vec[i].val);
		vec[i + n].id = i + n, read(vec[i + n].val);
		sum2 += (b[i] = vec[i + n].val);
	}
	ans = min(sum1, sum2);
	sort(vec + 1, vec + (n << 1 | 1));

	for (int i = 1; i <= n; i++) ina[i] = inb[i] = false;
	for (int i = 1; i <= n; i++) {
		if (vec[i].id <= i) ina[vec[i].id] = true; 
		else inb[vec[i].id - n] = true;
		sum += vec[i].val;
	}

	bool flag = false;
	for (int i = 1; i <= n; i++) {
		if (ina[i] && inb[i]) flag = true;
	}
	if (flag) ans = min(ans, sum);
	else {
		if (max(vec[n + 1].id - vec[n].id, vec[n].id - vec[n + 1].id) != n) ans = min(ans, sum + vec[n + 1].val - vec[n].val);
		else {
			ans = min(ans, sum + vec[n + 2].val - vec[n].val);
			if (max(vec[n + 1].id - vec[n - 1].id, vec[n - 1].id - vec[n + 1].id) != n) ans = min(ans, sum + vec[n + 1].val - vec[n].val);
		}
	}

	write(ans), putchar('\n');
	return 0;
}

