void solve() {
  int n; cin >> n;
  pqasc<tuple<int, int, int>> q;
  vector<pair<int, int>> as;
  vector<pair<int, int>> ve;
  vector<long long> su(n * 2 + 1);
  rep(i, n) {
    int a, b; cin >> a >> b;
    q.emplace(a, i, 0);
    q.emplace(b, i, 1);
    ve.emplace_back(a, i);
    ve.emplace_back(b, i);
    as.emplace_back(a, b);
  }
  sort(all(ve));
  rep(i, 2 * n) su[i + 1] += su[i] + ve[i].first;

  long long ans = 0;
  set<int> in;
  vector<int> co(2);
  rep(i, n) {
    int x, y, z;
    tie(x, y, z) = q.top(), q.pop();
    ans += x;
    in.insert(y);
    co[z]++;
  }
  if (in.size() == n && (co[0] == 0 || co[1] == 0)) {
    cout << ans << '\n';
    return;
  }
  ans = 1e18;
  rep(i, n) {
    long long sum = su[n];
    int a, b;
    tie(a, b) = as[i];
    int x = lower_bound(all(ve), make_pair(a, i)) - ve.begin();
    int y = lower_bound(all(ve), make_pair(b, i)) - ve.begin();
    if (x < n && y < n) {
      sum -= a + b, sum += ve[n].first + ve[n + 1].first;
    } else if (x < n && y == n) {
      sum -= a, sum += ve[n + 1].first;
    } else if (x == n && y < n) {
      sum -= b, sum += ve[n + 1].first;
    } else if (x < n) {
      sum -= a, sum += ve[n].first;
    } else if (y < n) {
      sum -= b, sum += ve[n].first;
    }
    amin(ans, sum);
  }
  cout << ans << '\n';
}

