void solve() {
  int n; cin >> n;
  vector<pair<int, int>> as;
  vector<tuple<int, int, int>> ve;
  long long sum = 0;
  rep(i, n) {
    int a, b; cin >> a >> b;
    as.emplace_back(a, b);
    ve.emplace_back(a, i, 0);
    ve.emplace_back(b, i, 1);
  }
  sort(all(ve));
  int co = 0;
  rep(i, n) {
    int x, j, k;
    tie(x, j, k) = ve[i];
    sum += x;
    co += k == 1;
  }
  if (co == 0 || co == n) {
    cout << sum << '\n';
    return;
  }
  long long ans = 1e18;
  rep(i, n) {
    long long su = sum;
    int a, b;
    tie(a, b) = as[i];
    int x = lower_bound(all(ve), make_tuple(a, i, 0)) - ve.begin();
    int y = lower_bound(all(ve), make_tuple(b, i, 1)) - ve.begin();
    int f = get<0>(ve[n]);
    int g = get<0>(ve[n + 1]);
    if (x < n && y < n) {
      su -= a + b, su += f + g;
    } else if (x < n && y == n) {
      su -= a, su += g;
    } else if (x == n && y < n) {
      su -= b, su += g;
    } else if (x < n) {
      su -= a, su += f;
    } else if (y < n) {
      su -= b, su += f;
    }
    amin(ans, su);
  }
  cout << ans << '\n';
}

