template <class T> void read(T &x)
{
    x=0; char c=gc(); int flag=0;
    while (c<'0'||c>'9') flag|=(c=='-'),c=gc();
    while (c>='0'&&c<='9') x=(x<<3)+(x<<1)+(c^48),c=gc();
    if (flag) x=-x;
}
template <class T> T _max(T a,T b){return a>b ? a : b;}
template <class T> T _min(T a,T b){return a<b ? a : b;}
template <class T> bool checkmax(T &a,T b){return b>a ? a=b,1 : 0;}
template <class T> bool checkmin(T &a,T b){return b<a ? a=b,1 : 0;}
const int N=100005;
int n,a[N],b[N],rnk[N<<1];
pii c[N<<1];
ll ans=0,pre[N<<1];
void init()
{
    read(n);
	for (int i=1;i<=n;++i)
	{
		read(a[i]); read(b[i]);
		c[i+i-1]=m_p(a[i],i+i-1);
		c[i+i]=m_p(b[i],i+i);
	}
	sort(c+1,c+n+n+1);
	for (int i=1;i<=n+n;++i)
	{
		rnk[c[i].second]=i;
	}
	//outarr(rnk,1,n+n);
}

void solve()
{
	ll tmp1=0,tmp2=0;
	for (int i=1;i<=n;++i)
	{
		tmp1+=a[i];
		tmp2+=b[i];
	}
	ans=_min(tmp1,tmp2);
	for (int i=1;i<=n;++i)
	{
		pre[i]=pre[i-1]+(ll)c[i].first;
	}
	for (int i=1;i<=n;++i)
	{
		if (rnk[i+i-1]<=n&&rnk[i+i]<=n)
		{
			checkmin(ans,pre[n]);
		}
		else if (rnk[i+i-1]>n&&rnk[i+i]>n)
		{
			checkmin(ans,pre[n-2]+a[i]+b[i]);
		}
		else if (rnk[i+i-1]<=n&&rnk[i+i]>n)
		{
			if (rnk[i+i-1]==n) checkmin(ans,pre[n-2]+a[i]+b[i]);
			else checkmin(ans,pre[n-1]+b[i]);
		}
		else
		{
			if (rnk[i+i]==n) checkmin(ans,pre[n-2]+a[i]+b[i]);
			else checkmin(ans,pre[n-1]+a[i]);
		}
	}
	printf("%lld\n",ans);
} 

#undef int
int main()
{
    int T=1;
    //read(T);
    while (T--)
    {
        init();
        solve();
    }
    return 0;
}

