using i64 = int64_t;
using vi = vector<i64>;
using vvi = vector<vi>;

bool visited[101010];
bool revisited;

struct edge {
    int a, id;
    bool out;
};

int main() {
    int n;
    cin >> n;
    vector<edge> vs;
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        vs.push_back((edge) {a, i, true});
        vs.push_back((edge) {b, i, false});
    }
    sort(vs.begin(), vs.end(), [](edge e1, edge e2) {
        return e1.a < e2.a;
    });

    i64 ans = 0;
    int incnt = 0;
    int outcnt = 0;
    int cntmax = (n + 1) / 2;
    for (edge& e: vs) {
        if (incnt + outcnt == n) {
            break;
        }
        if (visited[e.id] && !revisited) {
            if (e.out) {
                if (outcnt + 1 <= cntmax) {
                    outcnt++;
                    revisited = true;
                    ans += e.a;
                }
            } else {
                if (incnt + 1 <= incnt) {
                    incnt++;
                    revisited = true;
                    ans += e.a;
                }
            }
        }
        if (visited[e.id]) continue;
        if (!visited[e.id]) {
            if (e.out) {
                if (outcnt + 1 <= cntmax) {
                    outcnt++;
                    visited[e.id] = true;
                    ans += e.a;
                }
            } else {
                if (incnt + 1 <= cntmax) {
                    incnt++;
                    visited[e.id] = true;
                    ans += e.a;
                }
            }
        }
    }
    cout << ans << endl;
}

