    for (int i = 0; i < int(pick.size()); i++) {
        sum += pick[i];
        if (i+1 == n-2) ans = min(ans, sum + a[best] + b[best]); 
        if (i+1 == n) ans = min(ans, sum);
    }

    cout << ans << endl;
    return 0;
}

