long long s;
long long ans;

long long eval() {
  long long res = 0;
  for (int i = 0; i < n; i++) {
    int x = p[i];
    int y = p[(i + 1) % n];
    res += min(a[x], b[y]);
  }
  return res;
}

void solve() {
  multiset<pair<int, int>> ms;
  for (int i = 0; i < n; i++) {
    ms.emplace(b[i], i);
    if (a[p[0]] > a[i]) {
      p[0] = i;
    }
  }
  ms.erase(make_pair(b[p[0]], p[0]));
  for (int i = 0; i + 1 < n; i++) {
    auto l = ms.begin();
    auto r = prev(ms.end());
    if (abs(l->first - a[p[i]]) > abs(r->first - a[p[i]])) {
      p[i + 1] = l->second;
      ms.erase(l);
    } else {
      p[i + 1] = r->second;
      ms.erase(r);
    }
  }
  s = eval();
  ans = min(ans, s);
}

