#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using pii = pair<ll,ll>;

ll solve() {
    ll N, a, b;
    cin >> N;
    vector<pii> A(N), B(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> a >> b;
        A[i] = pii(a, i);
        B[i] = pii(b, i);
    }
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());
    int ia = -1, ib = -1, lab = -1;
    vector<int> c_ix(N);
    ll ans = 0;
    for ( int i = 0; i < N; i++ ) {
        if ( A[ia+1].first <= B[ib+1].first ) {
            ia++;
            lab = 0;
            ans += A[ia].first;
            c_ix[A[ia].second]++;
        } else {
            ib++;
            lab = 1;
            ans += B[ib].first;
            c_ix[B[ib].second]++;
        }
    }
    bool sep = true;
    for ( int i = 0; i < N; i++ ) {
        if ( c_ix[i] != 1 ) {
            sep = false;
            break;
        }
    }
    if ( ia == -1 || ib == -1 ) sep = false;
    if ( sep ) {
        if ( lab == 0 ) ans -= A[ia].first;
        else ans -= B[ib].first;
        int nab = -1;
        if ( A[ia+1].first <= B[ib+1].first ) nab = 0;
        else nab = 1;
        if ( nab != lab ) {
            if ( nab == 0 ) {
                if ( A[ia+1].second == B[ib].second && ia+1 < N-1 ) {
                    ia++;
                }
            } else {
                if ( A[ia].second == B[ib+1].second && ib+1 < N-1 ) {
                    ib++;
                }
            }
        }
        if ( A[ia+1].first <= B[ib+1].first ) {
            ia++;
            ans += A[ia].first;
        } else {
            ib++;
            ans += B[ib].first;
        }        
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

