void solve() {
  int n; cin >> n;
  pqasc<tuple<int, int, int>> q;
  rep(i, n) {
    int a, b; cin >> a >> b;
    q.emplace(a, i, 0);
    q.emplace(b, i, 1);
  }
  set<int> in;
  vector<int> co(2);
  long long ans = 0;
  tuple<int, int, int> la, lo;
  rep(i, n) {
    int x, y, z;
    tie(x, y, z) = q.top(), q.pop();
    if (i == n - 2) lo = make_tuple(x, y, z);
    if (i == n - 1) la = make_tuple(x, y, z);
    ans += x;
    in.insert(y);
    co[z]++;
  }
  if (in.size() == n && (co[0] == 1 || co[1] == 1)) {
    int x, y, z;
    tie(x, y, z) = la;
    ans -= x;
    in.erase(y);
    co[z]--;
    auto li = q.top(); q.pop();
    tie(x, y, z) = li;
    ans += x;
    in.insert(y);
    co[z]++;
    if (in.size() == n && (co[0] == 1 || co[1] == 1)) {
      ans -= x;
      in.erase(y);
      co[z]--;
      auto lu = q.top(); q.pop();
      ans -= get<0>(lo);
      ans += min(get<0>(lo) + get<0>(lu), get<0>(la) + get<0>(li));
    }
  }
  cout << ans << '\n';
}

