void add(const int n){
    int n_c[n+1];
    int i;
    int min_i;
    int min_cost = -1;
    int tmp_cost;

    min_i = 0;
    // cycle[n-1] -> cycle[0]
    // => cycle[n-1] -> n, n -> cycle[0]
    tmp_cost = path(cycle[n-1], n) + path(n, cycle[0]) - path(cycle[n-1], cycle[0]);
    min_cost = tmp_cost;

    for(i = 1; i < n; i++){
        memset(n_c, 0, sizeof(int) * (n+1));
        memcpy(n_c, cycle, sizeof(int) * n);
        tmp_cost = path(cycle[i-1], n) + path(n, cycle[i]) - path(cycle[i-1], cycle[i]);
        if(min_cost > tmp_cost){
            min_cost = tmp_cost;
            min_i = i;
        }
    }
    cost += min_cost; 
    insert(cycle, n, min_i, n);
}

void insert(int arr[], int ins_data, int ins_place, int n){
    int inserted = 0;
    int i;
    int *tmp;

    tmp = malloc(sizeof(int) * n);
    memcpy(tmp, malloc, sizeof(int) * n);

    if((0 > ins_place) || (n < ins_place)){
        return;
    }
    for(i = 0; i < n; i++){
        if(i == ins_place){
            arr[i] = ins_data;
        }
        arr[i + inserted] = tmp[i];
    }
    if(inserted == 0){
        arr[n] = ins_data;
    }
}

