	static class TaskX {

		int n;
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			n = in.nextInt();
			List<P> list = new ArrayList<>();
			long suma = 0, sumb = 0;
			for (int i = 0; i < n; i++) {
				long a = in.nextLong();
				long b = in.nextLong();
				list.add(new P(a, i));
				list.add(new P(b, i));
				suma += a; sumb += b;
			}

			Collections.sort(list);

			long ans = f(list.toArray(new P[0]));

			ans = Math.min(ans, suma);
			ans = Math.min(ans, sumb);

			out.println(ans);

		}

		long f(P[] p) {
			long ret = INF, base = 0;
			Map<Integer, Integer> map = new TreeMap<>();
			boolean ok = false;
			for (int i = 0; i < n; i++) {
				base += p[i].num;
				map.merge(p[i].idx, 1, Integer::sum);
				if (map.get(p[i].idx) >= 2) ok = true;
			}
			if (ok) {
				return base;
			}

			Map<Integer, Integer> tmap = new TreeMap<>(map);
			long tmp = base;
			tmp -= p[n-1].num;
			tmap.merge(p[n-1].idx, -1, Integer::sum);
			tmp += p[n].num;
			tmap.merge(p[n].idx, 1, Integer::sum);
			if (tmap.get(p[n].idx) >= 2) {
				ret = Math.min(ret, tmp);
			}

			tmap = new TreeMap<>(map);
			tmp = base;
			tmp -= p[n-1].num;
			tmap.merge(p[n-1].idx, -1, Integer::sum);
			tmp += p[n+1].num;
			tmap.merge(p[n+1].idx, 1, Integer::sum);
			if (tmap.get(p[n+1].idx) >= 2) {
				ret = Math.min(ret, tmp);
			}

			tmap = new TreeMap<>(map);
			tmp = base;
			tmp -= p[n-2].num;
			tmap.merge(p[n-2].idx, -1, Integer::sum);
			tmp += p[n].num;
			tmap.merge(p[n].idx, 1, Integer::sum);
			if (tmap.get(p[n].idx) >= 2) {
				ret = Math.min(ret, tmp);
			}

			return ret;
		}
	}

