        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] a = new int[n];
            int[] b = new int[n];
            in.readIntArrays(a, b);
            int[] all = ArrayUtils.concatenate(a, b);
            int[] order = ArrayUtils.order(all);
            int[] qty = new int[n];
            long answer = Long.MAX_VALUE;
            int[][] variants = new int[4][];
            variants[0] = ArrayUtils.createOrder(n);
            variants[1] = ArrayUtils.createOrder(n);
            variants[1][n - 1] = n;
            variants[2] = ArrayUtils.createOrder(n);
            variants[2][n - 1] = n;
            variants[2][n - 2] = n - 1;
            variants[3] = ArrayUtils.createOrder(n);
            variants[3][n - 1] = n + 1;
            for (int[] arr : variants) {
                int left = 0;
                int right = 0;
                Arrays.fill(qty, 0);
                for (int j : arr) {
                    if (order[j] < n) {
                        left++;
                    } else {
                        right++;
                    }
                    qty[order[j] % n]++;
                }
                if (left != 0 && right != 0 && ArrayUtils.maxElement(qty) == 1) {
                    continue;
                }
                long current = 0;
                for (int j : arr) {
                    current += all[order[j]];
                }
                answer = Math.min(answer, current);
            }
            out.printLine(answer);
        }

    }

    static interface IntStream extends Iterable<Integer>, Comparable<IntStream> {
        public IntIterator intIterator();

        default public Iterator<Integer> iterator() {
            return new Iterator<Integer>() {
                private IntIterator it = intIterator();

                public boolean hasNext() {
                    return it.isValid();
                }

                public Integer next() {
                    int result = it.value();
                    it.advance();
                    return result;
                }
            };
        }

        default public int compareTo(IntStream c) {
            IntIterator it = intIterator();
            IntIterator jt = c.intIterator();
            while (it.isValid() && jt.isValid()) {
                int i = it.value();
                int j = jt.value();
                if (i < j) {
                    return -1;
                } else if (i > j) {
                    return 1;
                }
                it.advance();
                jt.advance();
            }
            if (it.isValid()) {
                return 1;
            }
            if (jt.isValid()) {
                return -1;
            }
            return 0;
        }

        default public int max() {
            int result = Integer.MIN_VALUE;
            for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                int current = it.value();
                if (current > result) {
                    result = current;
                }
            }
            return result;
        }

    }

