          long orig = Math.min(b[x], a[y]) + (long) Math.min(b[y], a[z]) + (long) Math
              .min(b[z], a[t]);
          long modified = Math.min(b[x], a[z]) + (long) Math.min(b[z], a[y]) + (long) Math
              .min(b[y], a[t]);
          if (modified < orig) {
