          long orig = Math.min(b[x], a[y]) + (long) Math.min(b[y], a[z]) + (long) Math
              .min(b[z], a[s]) + (long) Math.min(b[s], a[t]);
          {
            long modified =
                Math.min(b[x], a[z]) + (long) Math.min(b[z], a[s]) + (long) Math
                    .min(b[s], a[y]) + (long) Math.min(b[y], a[t]);
            if (modified < orig) {
              // Assert.assertTrue(false);
