            }
          }
          {
            long modified =
                Math.min(b[x], a[s]) + (long) Math.min(b[s], a[y]) + (long) Math
                    .min(b[y], a[z]) + (long) Math.min(b[z], a[t]);
            if (modified < orig) {
              // Assert.assertTrue(false);
