    static class TaskC {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = new int[n];
            int[] b = new int[n];
            PriorityQueue<int[]> que = new PriorityQueue<>(Comparator.comparingInt(x -> x[0]));
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
                b[i] = in.nextInt();
                que.add(new int[]{a[i], i, 0});
                que.add(new int[]{b[i], i, 1});
            }
            List<Integer> xs = new ArrayList<>();
            Set<Integer> use = new TreeSet<>();
            Set<Integer> use2 = new TreeSet<>();
            for (int i = 0; i <= n; i++) {
                int[] p = que.poll();
                use.add(p[1]);
                use2.add(p[2]);
                xs.add(p[0]);
                if (i == n - 1 && use.size() == n && use2.size() == 2) {
                    xs.remove(xs.size() - 1);
                    continue;
                }
                if (i >= n - 1) {
                    out.println(xs.stream().mapToInt(x -> x).sum());
                    return;
                }
            }
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static class Node {
        public long aValue;
        public long bValue;

        public Node(final long aValue, final long bValue) {
            this.aValue = aValue;
            this.bValue = bValue;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Node node = (Node) o;
            return aValue == node.aValue &&
                    bValue == node.bValue;
        }

        @Override
        public int hashCode() {
            return Objects.hash(aValue, bValue);
        }
    }
    public static void main(String [] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final PriorityQueue<Long> a = new PriorityQueue<>();
        final PriorityQueue<Long> b = new PriorityQueue<>(
                Comparator.reverseOrder()
        );
        final Map<Node, Integer> nodes = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            long currentA = scanner.nextLong();
            long currentB = scanner.nextLong();
            a.add(currentA);
            b.add(currentB);
            final Node node = new Node(currentA, currentB);
            final int count = nodes.getOrDefault(node, 0);
            nodes.put(node, count + 1);
        }
        long result = 0;

        while (!a.isEmpty()) {
            long aValue = a.poll();
            long bValue = b.poll();
            Node currentNode = new Node(aValue, bValue);
            if (nodes.containsKey(currentNode) && nodes.get(currentNode) == 1) {
                long newBValue = b.poll();
                result += Math.min(aValue, newBValue);
                b.add(bValue);
            } else if (!nodes.containsKey(currentNode)) {
                result += Math.min(aValue, bValue);
            } else {
                result += Math.min(aValue, bValue);
            }
        }
        System.out.println(result);
    }
}

