    long stupid(int[] a, int[] b) {
      int n = a.length;
      int[] p = new int[n];
      for (int i = 0; i < n; ++i) {
        p[i] = i;
      }
      long res = Long.MAX_VALUE;
      do {
        long cur = 0;
        for (int i = 0; i < n; ++i) {
          int j = (i + 1) % n;
          cur += Math.min(a[p[i]], b[p[j]]);
        }
        res = Math.min(res, cur);
      } while (Permutations.nextPermutation(p));
      return res;
    }

