			haveSmallRight |= smallRight;
			if (smallLeft && smallRight) {
				bad = false;
			}
		}
		if (!haveSmallLeft || !haveSmallRight) {
			bad = false;
		}
		if (bad) {
			ans += c[n] - c[n - 1];
		}
		out.println(ans);
	}

