	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			PriorityQueue<Long> A = new PriorityQueue<Long>();
			PriorityQueue<Long> B = new PriorityQueue<Long>();

			for (int i = 0; i < n; i++) {
				long a = in.nextLong();
				long b = in.nextLong();
				A.add(a);
				B.add(b);
			}

			long ans = 0;
			int ac = 0, bc = 0;
			while (n-- > 0) {
				if (ac <= bc) {
					ans += A.remove();
					ac++;
				} else {
					long ta = A.peek();
					long ba = B.peek();

					if (ta <= ba) {
						ans += A.remove();
						ac++;
					} else {
						ans += B.remove();
						bc++;
					}
				}
			}
			out.println(ans);
		}
	}

