				N from = na.get(0);
				N to = nb.get(0);
				cost += min(from.a, to.b);
				break;
			}

			long cost1 = 0;
			N from1 = null;
			N to1 = null;
			long cost2 = 0;
			N from2 = null;
			N to2 = null;
			int fi1 = -1;
			int ti1 = -1;
			int fi2 = -1;
			int ti2 = -1;
			{
				N from = na.getFirst();
				int len = nb.size();
				for (int i = len - 1; i >= 0; i--) {
					N to = nb.get(i);
					if (uf.rootIndex(from.i) != uf.rootIndex(to.i)) {
						cost1 = -max(from.a, to.b);
						from1 = from;
						to1 = to;
						fi1 = 0;
						ti1 = i;
