    public long doSolve(int n, int[] a, int[] b) {
      int[] next = greedy(n, a, b, 1, false);
      long res = eval(a, b, next);
      int buben = 5 + Math.min(200, 100 * 1000 / n);
      for (int cyc = 0; cyc < buben; ++cyc) {
        for (boolean comp : new boolean[]{true/*, false*/}) {
