            continue;
          }
          // if (n >= 50 * 1000 && cyc == 2) continue;
          int[] tnext = greedy(n, a, b, cyc, comp);
          long val = eval(a, b, tnext);
          if (val < res) {
            res = val;
            next = tnext;
          }
        }
      }

