  static class Permutations {

    public static boolean nextPermutation(int[] p) {
      for (int a = p.length - 2; a >= 0; --a) {
        if (p[a] < p[a + 1]) {
          for (int b = p.length - 1; ; --b) {
            if (p[b] > p[a]) {
              int t = p[a];
              p[a] = p[b];
              p[b] = t;
              for (++a, b = p.length - 1; a < b; ++a, --b) {
                t = p[a];
                p[a] = p[b];
                p[b] = t;
              }
              return true;
            }
          }
        }
      }
      return false;
    }

  }

  static class InputReader {

    private InputStream stream;
    private byte[] buffer = new byte[10000];
    private int cur;
    private int count;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public static boolean isSpace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int read() {
      if (count == -1) {
        throw new InputMismatchException();
      }
      try {
        if (cur >= count) {
          cur = 0;
          count = stream.read(buffer);
          if (count <= 0) {
            return -1;
          }
        }
      } catch (IOException e) {
        throw new InputMismatchException();
      }
      return buffer[cur++];
    }

    public int readSkipSpace() {
      int c;
      do {
        c = read();
      } while (isSpace(c));
      return c;
    }

    public int nextInt() {
      int sgn = 1;
      int c = readSkipSpace();
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9') {
          throw new InputMismatchException();
        }
        res = res * 10 + c - '0';
        c = read();
      } while (!isSpace(c));
      res *= sgn;
      return res;
    }

  }
}

import java.util.*;

public class Main {
	int N;
	List<Integer> A = new ArrayList<>();
	List<Integer> B = new ArrayList<>();
	int result = 0;

	private static class Elem {
		int index, val;

		private Elem(int index, int val) {
			this.index = index;
			this.val = val;
		}
	}

	private Main() {
		Scanner in = new Scanner(System.in);
		N = Integer.parseInt(in.nextLine());
		for (int i = 0; i < N; ++i) {
			String[] tokens = in.nextLine().split(" ");
			A.add(Integer.parseInt(tokens[0]));
			B.add(Integer.parseInt(tokens[1]));
		}
		in.close();
	}

	private void calc() {
		List<Elem> a = new ArrayList<>();
		List<Integer> b = new ArrayList<>();
		for (int i = 0; i < N; ++i) {
			a.add(new Elem(i, A.get(i)));
		}
		b.addAll(B);
		Collections.sort(a, new Comparator<Elem>() {
			@Override
			public int compare(Elem o1, Elem o2) {
				if (o1.val < o2.val) {
					return -1;
				} else if (o1.val > o2.val) {
					return 1;
				} else {
					return 0;
				}
			}
		});
		Collections.sort(b, new Comparator<Integer>() {
			@Override
			public int compare(Integer o1, Integer o2) {
				if (o1 < o2) {
					return 1;
				} else if (o1 > o2) {
					return -1;
				} else {
					return 0;
				}
			}
		});

		for (int i = 0; i < N; ++i) {
			int aVal = a.get(i).val;
			if (b.size() == 1) {
				int bVal = b.get(0);
				result += Math.min(aVal, bVal);
			} else {
				int index = 0;
				if (b.get(index) == B.get((a.get(i).index))) {
					index++;
				}
				int bVal = b.get(index);
				result += Math.min(aVal, bVal);
				b.remove(index);
			}
		}
	}

	private void show() {
		System.out.println(result);
	}

	public static void main(String[] args) {
		Main ins = new Main();
		ins.calc();
		ins.show();
	}

}

