  static class Permutations {

    public static boolean nextPermutation(int[] p) {
      for (int a = p.length - 2; a >= 0; --a) {
        if (p[a] < p[a + 1]) {
          for (int b = p.length - 1; ; --b) {
            if (p[b] > p[a]) {
              int t = p[a];
              p[a] = p[b];
              p[b] = t;
              for (++a, b = p.length - 1; a < b; ++a, --b) {
                t = p[a];
                p[a] = p[b];
                p[b] = t;
              }
              return true;
            }
          }
        }
      }
      return false;
    }

  }

  static class InputReader {

    private InputStream stream;
    private byte[] buffer = new byte[10000];
    private int cur;
    private int count;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public static boolean isSpace(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int read() {
      if (count == -1) {
        throw new InputMismatchException();
      }
      try {
        if (cur >= count) {
          cur = 0;
          count = stream.read(buffer);
          if (count <= 0) {
            return -1;
          }
        }
      } catch (IOException e) {
        throw new InputMismatchException();
      }
      return buffer[cur++];
    }

    public int readSkipSpace() {
      int c;
      do {
        c = read();
      } while (isSpace(c));
      return c;
    }

    public int nextInt() {
      int sgn = 1;
      int c = readSkipSpace();
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9') {
          throw new InputMismatchException();
        }
        res = res * 10 + c - '0';
        c = read();
      } while (!isSpace(c));
      res *= sgn;
      return res;
    }

  }
}

import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static class Node {
        public long aValue;
        public long bValue;

        public Node(final long aValue, final long bValue) {
            this.aValue = aValue;
            this.bValue = bValue;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Node node = (Node) o;
            return aValue == node.aValue &&
                    bValue == node.bValue;
        }

        @Override
        public int hashCode() {
            return Objects.hash(aValue, bValue);
        }
    }
    public static void main(String [] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final PriorityQueue<Long> a = new PriorityQueue<>();
        final PriorityQueue<Long> b = new PriorityQueue<>(
                Comparator.reverseOrder()
        );
        final Map<Long, Integer> aCounts = new HashMap<>();
        final Map<Long, Integer> bCounts = new HashMap<>();
        final Map<Node, Integer> nodes = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            long currentA = scanner.nextLong();
            long currentB = scanner.nextLong();
            a.add(currentA);
            b.add(currentB);
            final Node node = new Node(currentA, currentB);
            final int count = nodes.getOrDefault(node, 0);
            nodes.put(node, count + 1);
            final int aCount = aCounts.getOrDefault(currentA, 0);
            final int bCount = bCounts.getOrDefault(currentB, 0);
            aCounts.put(currentA, aCount + 1);
            bCounts.put(currentB, bCount + 1);
        }
        long result = 0;

        while (!a.isEmpty()) {
            long aValue = a.poll();
            long bValue = b.poll();
            Node currentNode = new Node(aValue, bValue);
            if (nodes.containsKey(currentNode)
                    && nodes.get(currentNode) == 1
                    && bCounts.get(bValue) == 1
            ) {
                long newBValue = b.poll();
                result += Math.min(aValue, newBValue);
                b.add(bValue);
            } else {
                result += Math.min(aValue, bValue);
            }
        }
        System.out.println(result);
    }
}

