		int[] a = new int[n];
		int[] b = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = nextInt();
			b[i] = nextInt();
		}

		// out.println(slow(a, b));
		out.println(go(a, b));
		// out.println((sum - go(a, b)) / 2);
		// out.println((sum - slow(a, b)) / 2);
	}

