    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.Comparator;
import java.util.HashSet;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static class Node implements Comparable<Node> {
        public long value;
        public int index;

        public Node(final long value, final int index) {
            this.value = value;
            this.index = index;
        }


        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Node node = (Node) o;
            return value == node.value &&
                    index == node.index;
        }

        @Override
        public int hashCode() {
            return Objects.hash(value, index);
        }

        @Override
        public int compareTo(Node o) {
            if (this.value < o.value) {
                return -1;
            } else if (this.value == o.value) {
                return 0;
            } else {
                return 1;
            }

        }
    }
    public static void main(String [] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();
        final PriorityQueue<Node> a = new PriorityQueue<>(
        );
        final PriorityQueue<Node> b = new PriorityQueue<>(
                Comparator.reverseOrder()
        );
        final Set<Integer> visited = new HashSet<>();

        for (int i = 1; i <= n; ++i) {
            long currentA = scanner.nextLong();
            long currentB = scanner.nextLong();
            a.add(new Node(currentA, i));
            b.add(new Node(currentB, i));
        }
        long result = 0;

        while (!a.isEmpty()) {
            Node aNode = a.poll();
            Node bNode = b.poll();
            Set<Node> bNodes = new HashSet<>();
            while (aNode.index == bNode.index || ((!b.isEmpty()) && visited.contains(bNode.index))) {
                bNodes.add(bNode);
                bNode = b.poll();
            }
            result += Math.min(aNode.value, bNode.value);
            visited.add(bNode.index);
            b.addAll(bNodes);
        }
        System.out.println(result);
    }
}

