        long half = 0;
        Set<Integer> found = new HashSet<>();
        int a = 0;
        int b = 0;
        boolean ab = false;
        for (int i = 0; i < N; i++) {
            Node node = all[i];
            half += node.n;
            if( node.a ) {
                a++;
            } else {
                b++;
            }
            if( found.contains(node.i) ) {
                ab = true;
            } else {
                found.add( node.i );
            }
        }
        if( a == 0 || b == 0 || ab ) {
            return half;

        } else {
            Node x1 = all[N-1];
            Node y1 = all[N];

            if( x1.i != y1.i ) {
                return half - x1.n + y1.n;
            } else {
                Node x2 = all[N-2];
                Node y2 = all[N+1];
                if( y1.n - x2.n < y2.n - x1.n ) {
                    return half - x2.n + y1.n;
                } else {
                    return half - x1.n + y2.n;
                }
            }
        }
    }

    static class Node {
        int i;
        int n;
        boolean a;

        public Node(int i, int n, boolean a) {
            this.i = i;
            this.n = n;
            this.a = a;
        }
    }

