public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CMinCostCycle solver = new CMinCostCycle();
        solver.solve(1, in, out);
        out.close();
    }

    static class CMinCostCycle {
        public void solve(int testNumber, LightScanner in, PrintWriter out) {
            int n = in.ints();
            List<CMinCostCycle.Node> a = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                a.add(new CMinCostCycle.Node(in.ints(), true, i));
                a.add(new CMinCostCycle.Node(in.ints(), false, i));
            }
            a.sort(Comparator.comparing(node -> node.cost));
            int[] use = new int[n];
            long ans = 0;
            boolean du = false;
            int type = 0;
            for (int i = 0; i < n; i++) {
                int index = a.get(i).i;
                ans += a.get(i).cost;
                if (use[index] > 0) {
                    du = true;
                }
                if (a.get(i).in) {
                    type |= 1;
                } else {
                    type |= 2;
                }
                use[index]++;
            }
            if (!du && type == 3) {
                ans -= a.get(n - 1).cost;
                if (a.get(n - 1).i == a.get(n).i) {
                    ans += a.get(n + 1).cost;
                } else {
                    ans += a.get(n).cost;
                }
            }
            out.println(ans);
        }

        static class Node {
            int cost;
            boolean in;
            int i;

            public Node(int cost, boolean in, int i) {
                this.cost = cost;
                this.in = in;
                this.i = i;
            }

        }

    }

