public class Kyopuro{
    public void AtCoder(){
        int n = int.Parse(Console.ReadLine());
        int[] a = new int[n];
        int[] b = new int[n];
        int[] c = new int[n * 2];
        string[] s;
        for(int i=0; i<n; i++){
            s = Console.ReadLine().Split(' ');
            a[i] = int.Parse(s[0]);
            b[i] = int.Parse(s[1]);
            c[i] = a[i];
            c[n + i] = b[i];
        }
		Array.Sort(c);
		var d = new Dictionary<int, int>();
		for(int i=0; i<n; i++){
		    if(d.ContainsKey(c[i])){
		        d[c[i]]++;
		    } else {
		        d.Add(c[i], 1);
		    }
		}
		bool f = false;
		for(int i=0; i<n; i++){
		    if(d.ContainsKey(a[i]) && d.ContainsKey(b[i])){
		        if(a[i] == b[i]){
    		        if(d[a[i]] > 1) f = true;
    		    } else {
    		        if(d[a[i]] > 0 && d[b[i]] > 0) f = true;
    		    }
		    }
		}
		bool g = true;
		bool h = true;
		if(!f){
		    for(int i=0; i<n; i++){
		        if(a[i] < b[i]) h = false;
		        if(a[i] > b[i]) g = false;
		    }
		    if(g || h) f = true;
		}
		long ans = 0;
		for(int i=0; i<n; i++) ans += c[i];
		if(f) Console.WriteLine(ans);
		else{
		    Console.WriteLine(ans - c[n-1] + c[n]);
		}
