    Array.Sort(all);

    bool perfect = false;
    if(n==1)
    {
        perfect = true;
    }
    else if(all[n-1]==all[n])
    {
        perfect = true;
    }
    else
    {
        Array.Sort(sortedA);
        Array.Sort(sortedB);
        if(sortedA[n-1]==all[n-1])
        {
            perfect = true;
        }
        else if (sortedB[n - 1] == all[n - 1]) { perfect = true; }
    }

    if(perfect)
    {
        Console.Write(sum);
    }
    else
    {
        Console.Write(sum - all[n - 1] + all[n]);
    }
}

