namespace Competitive
{
    internal class Solution
    {
        public int N;
        public long[] A, B;
        public long MOD = 1000000007;

        public void Run()
        {
            N = Input.ReadInt();
            A = new long[N];
            B = new long[N];
            for (int i = 0; i < N; i++)
            {
                var line = Input.ReadLongArray();
                A[i] = line[0];
                B[i] = line[1];
            }

            // ABを合わせてソート
            var ab = new long[2 * N];
            for (int i = 0; i < N; i++)
            {
                ab[i] = A[i];
                ab[N + i] = B[i];
            }
            Array.Sort(ab);

            // 使いたい最後の値
            var last = ab[N - 1];

            int both = 0;
            int a = 0;
            int b = 0;
            List<long> AA = new List<long>();
            List<long> BB = new List<long>();
            List<long> AAE = new List<long>();
            List<long> BBE = new List<long>();

            for (int i = 0; i < N; i++)
            {
                if (A[i] <= last && B[i] <= last)
                {
                    both++;
                }
                else if (A[i] <= last)
                    a++;
                else if (B[i] <= last)
                    b++;

                // listに追加
                if (A[i] <= last)
                {
                    AA.Add(A[i]);
                }
                else
                {
                    AAE.Add(A[i]);
                }

                if (B[i] <= last)
                {
                    BB.Add(B[i]);
                }
                else
                {
                    BBE.Add(B[i]);
                }

            }

            AA.Sort();
            AAE.Sort();
            BB.Sort();
            BBE.Sort();

            // 小さいN個に偏りがあればOK
            // タイがある場合もOKか??
            if (both > 0 || a >= N || b >= N　|| (AA.Count + BB.Count) > N)
            {
                long ret = 0;
                for (int i = 0; i < N; i++)
                {
                    ret += (long)ab[i];
                }
                Console.WriteLine(ret);
                return;
            }

            // ダメな場合は、Aの次に大きい値と、Bの次に大きい値をとる
            {
                long ret = 0;
                for (int i = 0; i < N; i++)
                {
                    ret += (long)ab[i];
                }
                long ret1 = ret - AA.Last() + BBE.First();
                long ret2 = ret - BB.Last() + AAE.First();
                Console.WriteLine(Math.Min(ret1, ret2));
                return;
            }
        }
    }

