public class Kyopuro{
    public void AtCoder(){
        int n = int.Parse(Console.ReadLine());
        int[] a = new int[n];
        int[] b = new int[n];
        int[] c = new int[n * 2];
        string[] s;
        for(int i=0; i<n; i++){
            s = Console.ReadLine().Split(' ');
            a[i] = int.Parse(s[0]);
            b[i] = int.Parse(s[1]);
            c[i] = a[i];
            c[n + i] = b[i];
        }
		Array.Sort(c);
		var d = new Dictionary<int, int>();
		for(int i=0; i<n; i++){
		    if(d.ContainsKey(c[i])){
		        d[c[i]]++;
		    } else {
		        d.Add(c[i], 1);
		    }
		}
		bool f = false;
		for(int i=0; i<n; i++){
		    if(d.ContainsKey(a[i]) && d.ContainsKey(b[i])){
		        if(a[i] == b[i]){
    		        if(d[a[i]] > 1) f = true;
    		    } else {
    		        if(d[a[i]] > 0 && d[b[i]] > 0) f = true;
    		    }
		    }
		}
		int g = 0;
		int h = 0;
		if(!f){
		    for(int i=0; i<n; i++){
		        if(a[i] < b[i]) h++;
		        if(a[i] > b[i]) g++;
		    }
		    if(g == 0 || h == 0) f = true;
		}
		long ans = 0;
		for(int i=0; i<n; i++) ans += c[i];
		if(f) Console.WriteLine(ans);
		else{
		    if(n > 2){
		        int x = 0;
		        int y = 0;
		        int z = 0;
		        int u = -1;
		        for(int i=0; i<n; i++){
		            x = Math.Min(a[i], b[i]);
		            y = Math.Max(a[i], b[i]);
		            if(x == c[n-1] && y == c[n]){
		                f = true;
		                z++;
		                u = i;
		            }
		        }
		        if(z == 1){
		            if(a[u] < b[u] && h > 1){
		                f = true;
	                    ans = ans - c[n-1] + c[n+1];
	                }
	                if(a[u] > b[u] && g > 1){
	                    f = true;
	                    ans = ans - c[n-2] + c[n];
	                }
	                if(a[u] == b[u]){
	                    f = true;
	                    ans = Math.Min(ans - c[n-1] + c[n+1], ans - c[n-2] + c[n]);
	                }
		        }
		    }
		    if(!f) ans = ans - c[n-1] + c[n];
		    Console.WriteLine(ans);
		}
    }

