	for (int i = 1; i <= n; i++)
	{
		scanf("%lld %lld", &a[i], &b[i]);
		tans1 += a[i], tans2 += b[i];
		c[i] = a[i], c[i + n] = b[i];
	}

	ll ans = min(tans1, tans2);

	sort(c + 1, c + 2 * n + 1);
	for (int i = 1; i <= n; i++)
		pre[i] = pre[i - 1] + c[i];
	for (int i = 1; i <= n; i++)
	{
