		if (p1 > n && p2 > n)
			ans = min(ans, x + y + pre[n - 2]);
		else if (p1 <= n && p2 > n)
			ans = min(ans, pre[n - 1] + y);
		else if (p1 <= n && p2 <= n)
			ans = min(ans, pre[n]);
	}
