import sys
from collections import deque
import copy

def get_read_func(fileobject):
    if fileobject == None :
        return raw_input
    else:
        return fileobject.readline

class UnionFind:
    def __init__(self, n):
        self.par = [i for i in range(n+1)]
        self.rank = [0 for i in range(n+1)]

    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if self.rank[x] < self.rank[y]:
            self.par[x] = y
        else:
            self.par[y] = x
            if self.rank[x] == self.rank[y]:
                self.rank[x] += 1

    def same_check(self, x, y):
        return self.find(x) == self.find(y)


def main():
    if len(sys.argv) > 1:
        f = open(sys.argv[1])
    else:
        f = None
    read_func = get_read_func(f);
    input_raw = read_func().strip().split()
    N = int(input_raw[0])
    A_list = []
    B_list = []
    for i in range(N):
        input_raw = read_func().strip().split()
        [A, B] = [long(input_raw[0]), long(input_raw[1])]
        A_list.append((A, i))
        B_list.append((B, i))

    A_list.sort(reverse = True)
    B_list.sort()
    uf = UnionFind(N)
    score = 0L
    is_used = [False for i in range(N)]
    visited = set([])
    for i in range(N):
        for j in range(N):
            if A_list[j][0] <= B_list[i][0]:
                break
            if is_used[A_list[j][1]] == True:
                continue

            if uf.same_check(A_list[j][1], B_list[i][1]) == False:
                uf.union(A_list[j][1], B_list[i][1])
                is_used[A_list[j][1]] = True
                score += B_list[i][0]
                break

    for i in range(N):
        if is_used[A_list[i][1]] == False:
            score += A_list[i][0]
    print score


