#define ll long long
#define INF 1e+9
#define geta 1000000
using P = pair<int,int>;
int main(){
  priority_queue<P, vector<P> greater<P> > q;
  priority_queue<P> dq;
  int used[100001]={};
  int n, cnt = 0;
  int acnt = 0, bcnt = 0, scnt = 0;
  ll ans = 0;
  cin >> n;
  int a,b;
  for(int i=0;i<n;i++){
    cin >> a >> b;
    q.push(P(a,i));
    q.push(P(b,i + geta));
  }
  while(cnt < n){
    int d,p;
    tie(d,p)=q.top();q.pop();
    if(p > geta){
      if(used[p-geta] == 1){
        scnt++;
        used[p-geta] = 2;
      }
      bcnt++;
      cnt++;
      used[p-geta] = 1;
      ans += d;
    }else{
      if(used[p] == 1){ 
        scnt++;
        used[p] = 2;
      }
      acnt++;
      cnt++;
      used[p] = 1;
      ans += d;
    }
    dq.push(P(d,p));
  }
  while(scnt > max(acnt,bcnt)- min(acnt,bcnt)){
    int d,p;
    tie(d,p)=dq.top();dq.pop();
    if(p>geta){
      if(used[p-geta] == 2) continue;
      used[p-geta]--;
      ans -= d;
    }else{
      if(used[p] == 2) continue;
      used[p]--;
      ans -= d;
    }
    tie(d,p)=q.top();q.pop();
    if(p > geta){
      if(used[p-geta] == 1){
        scnt++;
        used[p-geta] = 2;
      }
      bcnt++;
      cnt++;
      used[p-geta] = 1;
      ans += d;
    }else{
      if(used[p] == 1){ 
        scnt++;
        used[p] = 2;
      }
      acnt++;
      cnt++;
      used[p] = 1;
      ans += d;
    }
  }
  cout << ans << endl;
}

