fn count(edges: Vec<(u64, bool, usize)>) -> Option<u64> {
    let n = edges.len();

    let mut used = vec![false; n];
    let mut right_count = 0;
    let mut sum = 0;
    for (w, is_right, i) in edges.into_iter() {
        used[i] = true;
        if is_right {
            right_count += 1;
        }
        sum += w;
    }

    if used.iter().any(|&u| !u) || right_count == 0 || right_count == n {
        Some(sum)
    } else {
        None
    }
}

