use std::cmp;

fn solve(a: &Vec<usize>, b: &Vec<usize>) -> usize {
    let n = a.len();
    let mut v = vec![];
    for i in 0..n {
        v.push((a[i], i));
        v.push((b[i], i));
    }
    v.sort();

    let mut ans = 0;
    let mut used_count = vec![0; n];
    for i in 0..n {
        let (t, i) = v[i];
        used_count[i] += 1;
        ans += t;
    }

    let used_two = used_count.iter().any(|&c| c == 2);
    if used_two {
        return ans;
    }

    let mut min = 1e15 as usize;
    for i in 0..n {
        let (t, i) = v[i];
        let ans = ans - t;
        let (t, j) = v[n];
        if i == j {
            let (t, _) = v[n + 1];
            min = cmp::min(ans + t, min);
        } else {
            min = cmp::min(ans + t, min);
        }
    }
    min
}

