fn solve(v: Vec<(u64, u64)>) -> u64 {
    let mut left = vec![];
    let mut right = vec![];
    for vi in v {
        if vi.0 <= vi.1 {
            left.push(vi);
        } else {
            right.push(vi);
        }
    }
    //println!("{:?} {:?}", left, right);

    let mut total = 0;
    for l in left.iter() {
        total += l.0;
    }
    for r in right.iter() {
        total += r.1;
    }

    if left.len() == 0 || right.len() == 0 {
        return total;
    }
    if left.len() == 1 && right.len() == 1 {
        let l = left[0];
        let r = right[0];
        return min(l.0, r.1) + min(l.1, r.0);
    }

    let mut left_left: Vec<(usize, (u64, u64))> = (0..).zip(left).collect();
    let mut right_right: Vec<(usize, (u64, u64))> = (0..).zip(right).collect();
    let mut left_right = left_left.clone();
    let mut right_left = right_right.clone();

    left_left.sort_by_key(|a| (a.1).0);
    left_right.sort_by_key(|a| (a.1).1);

    right_left.sort_by_key(|a| (a.1).0);
    right_right.sort_by_key(|a| (a.1).1);

    let ln = left_left.len();
    let rn = right_right.len();

    let mut ret = 1e18 as u64;

    for ll in left_left.iter() {
        let lidx = ll.0;
        let ain = (ll.1).0;

        for sel in 0..min(2, rn) {
            let rr = right_right[rn - 1 - sel];
            let ridx = rr.0;
            let aout = (rr.1).1;

            let lr_rl = (
                left_right.iter().find(|lr| lr.0 != lidx),
                right_left.iter().find(|rl| rl.0 != ridx),
            );
            if let (Some(lr), Some(rl)) = lr_rl {
                ret = min(
                    ret,
                    total + min(ain, aout) + min((lr.1).1, (rl.1).0) - ain - aout,
                );
            } else if let (Some(lr), None) = lr_rl {
                ret = min(
                    ret,
                    total + min(ain, aout) + min((lr.1).1, (rr.1).0) - ain - aout,
                );
            } else if let (None, Some(rl)) = lr_rl {
                ret = min(
                    ret,
                    total + min(ain, aout) + min((ll.1).1, (rl.1).0) - ain - aout,
                );
            }
        }
    }

    for rr in right_right.iter() {
        let ridx = rr.0;
        let aout = (rr.1).1;

        for sel in 0..min(2, ln) {
            let ll = left_left[ln - 1 - sel];
            let lidx = ll.0;
            let ain = (ll.1).0;

            let lr_rl = (
                left_right.iter().find(|lr| lr.0 != lidx),
                right_left.iter().find(|rl| rl.0 != ridx),
            );
            if let (Some(lr), Some(rl)) = lr_rl {
                ret = min(
                    ret,
                    total + min(ain, aout) + min((lr.1).1, (rl.1).0) - ain - aout,
                );
            } else if let (None, Some(rl)) = lr_rl {
                ret = min(
                    ret,
                    total + min(ain, aout) + min((ll.1).1, (rl.1).0) - ain - aout,
                );
            } else if let (Some(lr), None) = lr_rl {
                ret = min(
                    ret,
                    total + min(ain, aout) + min((lr.1).1, (rr.1).0) - ain - aout,
                );
            }
        }
    }
    ret
}

