    fn cmp(&self, other: &Self) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

use std::cmp;
use std::collections::BinaryHeap;

fn main() {
    read!();
    let nodes = readx::<(u64, u64)>();
    let cost1: u64 = nodes.iter().map(|&(a, _)| a).sum();
    let cost2: u64 = nodes.iter().map(|&(_, b)| b).sum();

    let mut taken = BinaryHeap::new();
    let mut left = BinaryHeap::new();
    for (a, b) in nodes {
        let (less, greater) = if a <= b { (a, b) } else { (b, a) };
        taken.push(less);
        left.push(Reverse(greater));
    }

    taken.pop();
    taken.push(left.pop().unwrap().0);
    while left.peek().map_or(false, |&Reverse(x)| x < *taken.peek().unwrap()) {
        taken.pop();
        taken.push(left.pop().unwrap().0);
    }
    let cost3: u64 = taken.into_iter().sum();
    println!("{}", cmp::min(cmp::min(cost1, cost2), cost3));
}

