fn main() {
    input! {
        n: usize,
        xys: [(i64,i64); n],
    };
    let mut xs: Vec<(i64, usize)> = xys.iter().enumerate().map(|(i,&(x,_))| (x,i)).collect();
    let ys: Vec<(i64, usize)> = xys.iter().enumerate().map(|(i,&(_,y))| (y,i)).collect();
    let mut heap = BinaryHeap::from(ys);
    xs.sort();
    let mut res = 0;
    let mut dset = DisjointSet::new(n);
    for i in 0..n-2 {
        let (x,i) = xs[i];
        let (y1,k1) = heap.pop().unwrap();
        if i != k1 && !dset.same(i, k1) {
            res += min(x, y1);
            dset.unite(i, k1);
        }
        else {
            {
                let (y2,k2) = heap.pop().unwrap();
                assert!(i != k2 && !dset.same(i, k2));
                res += min(x, y2);
                dset.unite(i, k2);
            }
            heap.push((y1,k1));
        }
    }
    let (y1,k1) = heap.pop().unwrap();
    let (y2,k2) = heap.pop().unwrap();
    if xs[n-2].1 != k1 && xs[n-1].1 != k2 && !dset.same(xs[n-2].1, k1) {
        res += min(xs[n-2].0, y1);
        res += min(xs[n-1].0, y2);
    }
    else {
        assert!(xs[n-2].1 != k2 && xs[n-1].1 != k1 && !dset.same(xs[n-2].1, k2));
        res += min(xs[n-2].0, y2);
        res += min(xs[n-1].0, y1);
    }
    println!("{}", res);
}


struct DisjointSet {
    ps: Vec<Option<usize>>,
    ns: Vec<i64>,
}

impl DisjointSet {
    fn new(n: usize) -> DisjointSet {
        DisjointSet { ps: vec![None; n], ns: vec![1; n] }
    }

    fn unite(&mut self, x: usize, y: usize) {
        let nx = self.find(x);
        let ny = self.find(y);
        if nx == ny {
            return;
        }
        let (a,b) = if self.ns[nx] < self.ns[ny] { (nx,ny) } else { (ny,nx) };
        self.ps[a] = Some(b);
        self.ns[b] += self.ns[a];
    }

    fn find(&mut self, x: usize) -> usize {
        match self.ps[x] {
            Some(y) => {
                let res = self.find(y);
                self.ps[x] = Some(res);
                res
            },
            None => {
                x
            },
        }
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
}

