use std::cmp;
use std::collections::BinaryHeap;

fn main() {
    input!(n: usize, ab: [(usize, usize); n]);
    let mut x = ab
        .iter()
        .map(|&(a, b)| (cmp::min(a, b), a, b))
        .collect::<Vec<_>>();
    x.sort();

    let mut wastes = vec![];
    let mut mins = vec![];
    let mut ans = 0;
    let mut left_count = 0;
    for &(min, a, b) in x.iter() {
        ans += min;
        if min == a {
            left_count += 1;
            mins.push(a);
            wastes.push(b);
        } else {
            mins.push(b);
            wastes.push(a);
        }
    }

    if left_count != 0 && left_count != n {
        mins.sort();
        wastes.sort();

        let min_waste = wastes[0];
        let max_min = mins[mins.len() - 1];
        ans -= max_min;
        ans += min_waste;
    }
    println!("{}", ans);
}

