use std::cmp;
use std::collections::BinaryHeap;

fn solve(ab: &Vec<(usize, usize)>) -> usize {
    let n = ab.len();
    let mut v = vec![];
    for (i, &(a, b)) in ab.iter().enumerate() {
        v.push((a, i));
        v.push((b, i));
    }
    v.sort();

    let mut used_count = vec![0; n];
    let mut ans = 0;
    for i in 0..n {
        let (x, i) = v[i];
        used_count[i] += 1;
        ans += x;
    }

    for i in 0..n {
        if used_count[i] == 2 {
            return ans;
        }
    }

    let mut min = 1e15 as usize;

    for i in 0..n {
        assert_eq!(used_count[i], 1);
        let (a, b) = ab[i];
        let ans = ans - cmp::min(a, b);
        let (w, j) = v[n];
        if j == i {
            let (w, _) = v[n + 1];
            min = cmp::min(min, ans + w);
        } else {
            min = cmp::min(min, ans + w);
        }
    }
    min
}

fn main() {
    input!(n: usize, ab: [(usize, usize); n]);

    let ans0: usize = ab.iter().map(|&(a, _)| a).sum();
    let ans1: usize = ab.iter().map(|&(_, b)| b).sum();
    let ans2 = solve(&ab);
    println!("{}", cmp::min(cmp::min(ans0, ans1), ans2));
}

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let mut edges = Vec::with_capacity(2 * n);
    for i in 0..n {
        let a: u64 = sc.read();
        let b: u64 = sc.read();
        edges.push((a, i, true));
        edges.push((b, i, false));
    }
    edges.sort_by_key(|e| e.0);

    let mut candidates = vec![];
    if let Some(ans) = calc(&edges) {
        candidates.push(ans);
    }

    edges.swap(n, n - 1);
    if let Some(ans) = calc(&edges) {
        candidates.push(ans);
    }
    edges.swap(n, n - 1);

    edges.swap(n - 2, n);
    if let Some(ans) = calc(&edges) {
        candidates.push(ans);
    }
    edges.swap(n - 2, n);

    edges.swap(n - 1, n + 1);
    if let Some(ans) = calc(&edges) {
        candidates.push(ans);
    }
    edges.swap(n - 1, n + 1);

    candidates.sort();
    println!("{}", candidates[0]);
}

fn calc(edges: &[(u64, usize, bool)]) -> Option<u64> {
    let n = edges.len() / 2;
    let mut a_count = 0;
    let mut count = vec![0; n];
    let mut sum = 0;
    for i in 0..n {
        let (cost, i, is_a) = edges[i];
        count[i] += 1;
        sum += cost;
        if is_a {
            a_count += 1;
        }
    }
    if count.iter().any(|&e| e >= 2) || a_count == n || a_count == 0 {
        Some(sum)
    } else {
        None
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

