use std::cmp;
use std::collections::VecDeque;

fn main() {
    let sc = std::io::stdin();
    let mut sc = Scanner { reader: sc.lock() };
    let n: usize = sc.read();
    let mut a: Vec<usize> = vec![0; n];
    let mut b: Vec<usize> = vec![0; n];
    for i in 0..n {
        a[i] = sc.read();
        b[i] = sc.read();
    }

    let all_a: usize = a.iter().sum();
    let all_b: usize = b.iter().sum();

    let mut ans = cmp::min(all_a, all_b);

    let mut cur: usize = (0..n).map(|i| cmp::min(a[i], b[i])).sum();

    let mut max = (0..n)
        .map(|i| (cmp::max(a[i], b[i]), i))
        .collect::<Vec<_>>();
    max.sort();

    let mut min = (0..n)
        .map(|i| (cmp::min(a[i], b[i]), i))
        .collect::<Vec<_>>();
    min.sort();
    min.reverse();

    let mut removed = vec![false; n];

    let mut max_q: VecDeque<(usize, usize)> = max.iter().map(|&t| t).collect();
    let mut min_q: VecDeque<(usize, usize)> = min.iter().map(|&t| t).collect();
    while !max_q.is_empty() && !min_q.is_empty() {
        while let Some((_, i)) = max_q.pop_front() {
            if !removed[i] {
                max_q.push_front((cmp::max(a[i], b[i]), i));
                break;
            }
        }
        while let Some((_, i)) = min_q.pop_front() {
            if !removed[i] {
                min_q.push_front((cmp::min(a[i], b[i]), i));
                break;
            }
        }
        if max_q.is_empty() || min_q.is_empty() {
            break;
        }
        let max_i = max_q.pop_front().unwrap().1;
        let min_i = min_q.pop_front().unwrap().1;
        if max_i == min_i {
            break;
        }
        removed[max_i] = true;
        removed[min_i] = true;
        cur += cmp::max(a[max_i], b[max_i]);
        cur -= cmp::min(a[min_i], b[min_i]);
        ans = cmp::min(ans, cur);
    }
    println!("{}", ans);
}

pub struct Scanner<R> {
    reader: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .reader
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

