use std::cmp;
use std::collections::BinaryHeap;

fn main() {
    read!();
    let nodes = readx::<(u64, u64)>();
    let cost1: u64 = nodes.iter().map(|&(a, _)| a).sum();
    let cost2: u64 = nodes.iter().map(|&(_, b)| b).sum();

    let mut taken = BinaryHeap::new();
    let mut left = BinaryHeap::new();
    for (i, (a, b)) in nodes.into_iter().enumerate() {
        let (less, greater) = if a <= b { (a, b) } else { (b, a) };
        taken.push((less, i));
        left.push((Reverse(greater), i));
    }

    while let Some((Reverse(x), i1)) = left.pop() {
        let (_, i2) = taken.pop().unwrap();
        taken.push((x, i1));
        if i1 != i2 {
            break;
        }
    }
    while left.peek().map_or(false, |&(Reverse(x), _)| x < taken.peek().unwrap().0) {
        taken.pop();
        let (Reverse(x), i) = left.pop().unwrap();
        taken.push((x, i));
    }
    let cost3: u64 = taken.into_iter().map(|(x, _)| x).sum();
    println!("{}", cmp::min(cmp::min(cost1, cost2), cost3));
}

