fn solve(v: Vec<(u64, u64)>) -> u64 {
    let mut edges = vec![];
    let n = v.len();
    for i in 0..n {
        edges.push((v[i].0, i, 0));
        edges.push((v[i].1, i, 1));
    }
    edges.sort();

    let mut ans = 0;
    let mut flag = vec![0; n];
    for i in 0..n {
        ans += edges[i].0;
        let idx = edges[i].1;
        flag[idx] |= 1 << edges[i].2;
    }

    let mut types = vec![0; 4];
    for i in 0..n {
        types[flag[i]] += 1;
    }

    assert!(types[0] == types[3]);

    if types[1] == n || types[2] == n {
        return ans;
    }
    if types[0] >= 1 {
        return ans;
    }

    let mut best = std::u64::MAX;
    for i in n - 2..n {
        let eidx = edges[i].1;
        for j in n..2 * n {
            if edges[j].1 != eidx {
                best = min(best, ans + edges[j].0 - edges[i].0);
                break;
            }
        }
    }
    return best;
}

fn main() {
    input! {
        n: usize,
        v: [(u64, u64); n]
    };

    let ans = solve(v);
    println!("{}", ans);
}

