    let mut e = vec![];
    for i in 0..n {
        a[i] = it.next().unwrap().parse().unwrap();
        b[i] = it.next().unwrap().parse().unwrap();
        e.push((a[i], 1, i));
        e.push((b[i], 2, i));
    }
    e.sort_by_key(|e| e.0);
    let mut set = vec![std::collections::BTreeSet::new(); 4];
    for i in 0..n {
        set[0].insert(i);
    }
    let mut sum = 0;
    for i in 0..n {
        let (c, b, k) = e[i];
        sum += c;
        for j in (0..3).rev() {
            if set[j].contains(&k) {
                set[j].remove(&k);
                set[j | b].insert(k);
            }
        }
    }
    if !set[0].is_empty() || set[1].len() == n || set[2].len() == n {
        println!("{}", sum);
        return;
    }
    let mut ans = std::u64::MAX;
    for &(c, _, k) in &e[n..(n + 2)] {
        for &u in &set[1] {
            if u != k || set[1].len() == 1 {
                ans = std::cmp::min(ans, sum - a[u] + c);
            }
        }
        for &u in &set[2] {
            if u != k || set[2].len() == 1 {
                ans = std::cmp::min(ans, sum - b[u] + c);
            }
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}
